class TestEPdf(unittest.TestCase):
    """Pelos bytes e não pela extensão."""

    def caminho(self, conteudo):
        f = tempfile.NamedTemporaryFile(delete=False, suffix=".seja-o-que-for")
        f.write(conteudo); f.close()
        self.addCleanup(lambda: os.path.exists(f.name) and os.remove(f.name))
        return f.name

    def test_pdf_sem_extensao(self):
        # a vortal entrega ficheiros sem extensão nenhuma; um anúncio
        # trazia um "Caderno de Encargos" de 291 KB que ficava por ler
        self.assertTrue(radar.e_pdf(self.caminho(b"%PDF-1.7 tralha")))

    def test_pdf_com_lixo_antes_da_assinatura(self):
        # a norma tolera-o e o pypdf lê-os na mesma
        self.assertTrue(radar.e_pdf(self.caminho(b"\r\n   %PDF-1.4 x")))

    def test_o_que_nao_e_pdf(self):
        self.assertFalse(radar.e_pdf(self.caminho(b"PK" + bytes(2000))))

    def test_zip_com_pdf_por_comprimir_nao_e_pdf(self):
        # o "%PDF" fica no byte 46 e a janela de 1 KB apanhava-o: o
        # extrair_textos mandava o pacote ao pypdf e nunca o abria
        import io, zipfile
        saco = radar.io.BytesIO()
        with zipfile.ZipFile(saco, "w") as z:
            z.writestr("CE_Clausulas.pdf", b"%PDF-1.7 conteudo")
        self.assertFalse(radar.e_pdf(self.caminho(saco.getvalue())))

    def test_ficheiro_que_nao_existe(self):
        self.assertFalse(radar.e_pdf("nao-existe-de-certeza.pdf"))


class TestTextoDoZip(unittest.TestCase):
    """Há entidades que entregam a peça dentro de um ZIP."""

    def zip_com(self, ficheiros):
        import zipfile
        f = tempfile.NamedTemporaryFile(delete=False, suffix=".zip")
        f.close()
        with zipfile.ZipFile(f.name, "w") as z:
            for nome, dados in ficheiros:
                z.writestr(nome, dados)
        self.addCleanup(
            lambda: os.path.exists(f.name) and os.remove(f.name))
        return f.name

    def test_zip_sem_pdf_nenhum(self):
        caminho = self.zip_com([("leia.txt", b"nada")])
        self.assertEqual(radar.texto_do_zip(caminho, {"encargos"}),
                         ("", "não é PDF"))

    def test_pdf_ilegivel_nao_e_digitalizacao(self):
        # dizer "scan" a um PDF cifrado manda a pessoa procurar uma
        # digitalização quando o que falta é um pacote de Python
        caminho = self.zip_com([("CE_Clausulas.pdf", b"%PDF-1.7 estragado")])
        _, estado = radar.texto_do_zip(caminho, {"encargos"})
        self.assertTrue(estado.startswith("erro"), estado)

    def test_ficheiro_que_nao_e_zip(self):
        _, estado = radar.texto_do_zip("nao-existe-de-certeza.zip",
                                       {"encargos"})
        self.assertTrue(estado.startswith("erro"), estado)

    # -- 23/09/2026: o "programa do concurso.zip" que vinha DENTRO do ZIP
    # da plataforma ficava fechado, e os .docx nao se liam. Ele viu-o
    # numa ficha: «esse doc nao conseguimos ler».

    @staticmethod
    def docx(texto):
        saco = radar.io.BytesIO()
        import zipfile
        with zipfile.ZipFile(saco, "w") as z:
            z.writestr("word/document.xml",
                       "<w:document><w:body><w:p><w:r><w:t>%s</w:t></w:r></w:p>"
                       "</w:body></w:document>" % texto)
        return saco.getvalue()

    @staticmethod
    def zip_em_bytes(ficheiros):
        saco = radar.io.BytesIO()
        import zipfile
        with zipfile.ZipFile(saco, "w") as z:
            for nome, dados in ficheiros:
                z.writestr(nome, dados)
        return saco.getvalue()

    def test_o_zip_de_dentro_abre_e_o_docx_le_se(self):
        dentro = self.zip_em_bytes([("Programa_de_Concurso.docx",
                                     self.docx("O objecto e a manutencao"))])
        caminho = self.zip_com([("programaconcurso.zip", dentro),
                                ("leia.txt", b"nada")])
        texto, estado = radar.texto_do_zip(caminho, set())
        self.assertEqual(estado, "ok")
        self.assertIn("O objecto e a manutencao", texto)
        self.assertIn("programaconcurso.zip/Programa_de_Concurso.docx", texto)

    def test_nao_se_desce_para_sempre(self):
        # um ZIP dentro de um ZIP dentro de um ZIP... para no fundo
        camada = self.zip_em_bytes([("Programa.docx", self.docx("no fundo"))])
        for _ in range(radar.FUNDO_DOS_ZIP + 2):
            camada = self.zip_em_bytes([("mais.zip", camada)])
        caminho = self.zip_com([("pecas.zip", camada)])
        self.assertEqual(radar.texto_do_zip(caminho, set()), ("", "não é PDF"))

    def test_o_7z_abre_como_o_zip_com_um_zip_dentro(self):
        """23/09/2026: um concurso de quatro lotes entregava as pecas de
        cada lote num .7z de 32 MB, e ficavam «não é PDF»."""
        import py7zr
        dentro = self.zip_em_bytes([("Programa_de_Concurso.docx",
                                     self.docx("Lote 1: estrada nacional"))])
        f = tempfile.NamedTemporaryFile(delete=False, suffix=".7z")
        f.close()
        self.addCleanup(lambda: os.path.exists(f.name) and os.remove(f.name))
        with py7zr.SevenZipFile(f.name, "w") as z:
            z.writestr(self.docx("Caderno de encargos do lote"),
                       "LOTE 1/Caderno_de_Encargos.docx")
            z.writestr(dentro, "LOTE 1/pecas.zip")
            z.writestr(b"nao interessa", "LOTE 1/leia.txt")
        texto, estado = radar.texto_do_7z(f.name, set())
        self.assertEqual(estado, "ok")
        self.assertIn("Caderno de encargos do lote", texto)
        self.assertIn("Lote 1: estrada nacional", texto)
        self.assertIn("LOTE 1/pecas.zip/Programa_de_Concurso.docx", texto)

    def test_um_7z_estragado_e_erro_e_nao_veredicto(self):
        f = tempfile.NamedTemporaryFile(delete=False, suffix=".7z")
        f.write(b"isto nao e um 7z")
        f.close()
        self.addCleanup(lambda: os.path.exists(f.name) and os.remove(f.name))
        _, estado = radar.texto_do_7z(f.name, set())
        self.assertTrue(estado.startswith("erro"), estado)

    def test_um_zip_de_nome_generico_da_ao_modelo_o_programa_de_dentro(self):
        caminho = self.zip_com([("PECAS/Programa_de_Concurso.docx",
                                 self.docx("Criterio de adjudicacao: preco")),
                                ("PECAS/Anexo_I.docx", self.docx("modelo de declaracao"))])
        texto, _ = radar.texto_do_zip(caminho, set())
        docs = [{"nome": "1_ACINGOV_PECAS_DO_PROCEDIMENTO.zip", "texto": texto}]
        recorte, usados = radar.pecas_para_analise(docs, "programa", ())
        self.assertIn("Criterio de adjudicacao", recorte)
        self.assertNotIn("modelo de declaracao", recorte)
        self.assertTrue(usados and "Programa_de_Concurso.docx" in usados[0], usados)


