class TestJuntarLeituras(unittest.TestCase):
    """Uma leitura parcial não pode apagar o que já estava lido."""

    ANTES = {"objecto": "- fazer X", "equipa": "- 20 perfis com preços",
             "documentos_proposta": "- DEUCP",
             "preco_anormalmente_baixo": "40%"}

    def test_o_pedido_que_falhou_mantem_o_valor_antigo(self):
        # a tabela de 20 perfis do INFARMED desapareceu assim: 429 no
        # pedido da equipa, chave ausente, INSERT por cima
        junto = radar.juntar_leituras({"objecto": "- fazer Y"}, self.ANTES)
        self.assertEqual(junto["objecto"], "- fazer Y")
        self.assertEqual(junto["equipa"], "- 20 perfis com preços")
        self.assertEqual(junto["documentos_proposta"], "- DEUCP")

    def test_nao_consta_e_resposta_e_substitui(self):
        junto = radar.juntar_leituras({"equipa": "não consta"}, self.ANTES)
        self.assertEqual(junto["equipa"], "não consta")

    def test_sem_leitura_anterior_fica_por_ler(self):
        # None e nao "" desde 28/09/2026: "" fazia a ficha dizer que a
        # peca foi lida (TestORecorteLevaAResposta)
        junto = radar.juntar_leituras({"objecto": "- fazer X"}, None)
        self.assertEqual(junto["objecto"], "- fazer X")
        self.assertIsNone(junto["equipa"])

    def test_devolve_sempre_os_quatro_campos(self):
        self.assertEqual(set(radar.juntar_leituras({}, None)),
                         set(radar.CAMPOS_DA_ANALISE))


class TestJuntarFontes(unittest.TestCase):
    """As fontes têm de acompanhar os campos que o juntar_leituras guarda."""

    ANTES = "Caderno de Encargos.pdf, Programa.pdf"

    def test_leitura_parcial_nao_perde_a_peca_de_antes(self):
        # o objecto ficou do Caderno de Encargos lido antes; dizer só
        # "Programa.pdf" era atribuí-lo à peça errada na ficha
        juntas = radar.juntar_fontes(["Programa.pdf"], self.ANTES, True)
        self.assertIn("Caderno de Encargos.pdf", juntas)
        self.assertIn("Programa.pdf", juntas)

    def test_leitura_inteira_fica_so_com_as_desta_vez(self):
        # sem falhas, o que está guardado veio todo daqui: uma peça que
        # deixou de existir não pode continuar a ser citada
        self.assertEqual(radar.juntar_fontes(["Programa.pdf"], self.ANTES, False),
                         "Programa.pdf")

    def test_sem_fontes_novas_ficam_as_de_antes(self):
        self.assertEqual(radar.juntar_fontes([], self.ANTES, False), self.ANTES)

    def test_nao_repete(self):
        self.assertEqual(
            radar.juntar_fontes(["Programa.pdf"], "Programa.pdf", True),
            "Programa.pdf")

    def test_sem_leitura_anterior(self):
        self.assertEqual(radar.juntar_fontes(["Programa.pdf"], None, True),
                         "Programa.pdf")
        self.assertEqual(radar.juntar_fontes([], None, True), "")


class TestPapeisDaPeca(unittest.TestCase):
    """Que peça é cada ficheiro, pelo nome que a entidade lhe deu."""

    def test_nomes_por_extenso(self):
        for nome in ("1_Caderno_de_Encargos.pdf", "Caderno de Encargos.pdf",
                     "CADERNO_ENCARGOS_INFARMED(PRR)_WEBSITE_20260267.pdf"):
            self.assertEqual(radar.papeis_da_peca(nome), {"encargos"}, nome)
        for nome in ("2_Programa_do_Procedimento.pdf", "ProgramaConcurso.pdf",
                     "EPVL_CPi02-2627_ProgramaConsurso-Energia_signed.pdf"):
            self.assertEqual(radar.papeis_da_peca(nome), {"programa"}, nome)

    def test_os_nomes_que_a_validacao_encontrou(self):
        # 28/09/2026: quatro agentes compararam as 70 leituras com as pecas,
        # e estes quatro ficavam por ler -- o Caderno da ESPAP como
        # «Anexo.1-CdE», o da Marinha como «CADE», o Programa com a gralha
        # da propria entidade, e o Convite que faz de Programa na consulta
        self.assertEqual(radar.papeis_da_peca(
            "09. 2026_P389-Operacao.24x7-Anexo.1-CdE.pdf"), {"encargos"})
        self.assertEqual(radar.papeis_da_peca(
            "1_3026009118_20260914_CADE_DITIC_signed.pdf"), {"encargos"})
        self.assertEqual(radar.papeis_da_peca("3_Pograma_de_Concurso.pdf"),
                         {"programa"})
        self.assertEqual(radar.papeis_da_peca(
            "9-14_Convite_ Visita de estudo a Bruxelas.pdf"), {"programa"})

    def test_siglas(self):
        # ficavam por ler com o texto ja extraido e ali a jeito
        self.assertEqual(radar.papeis_da_peca("1_02_CE_28_2026_CP_DO_signed.pdf"),
                         {"encargos"})
        self.assertEqual(radar.papeis_da_peca("1_2026.06.30_CE_Outsourcing_vf.pdf"),
                         {"encargos"})
        self.assertEqual(radar.papeis_da_peca("2_01_PP_28_2026_CP_DO_signed.pdf"),
                         {"programa"})

    def test_cp_e_concurso_publico_nao_programa(self):
        # "CP" no meio do nome é Concurso Público
        self.assertNotIn("programa", radar.papeis_da_peca("02_CE_28_CP_DO.pdf"))

    def test_um_ficheiro_pode_ser_as_duas_pecas(self):
        self.assertEqual(radar.papeis_da_peca("Programa_CE_12027226.pdf"),
                         {"encargos", "programa"})

    def test_o_que_nao_e_peca(self):
        # o "Lista.pdf" é o índice das peças e diz "Caderno de Encargos"
        # lá dentro -- por isso é que se vai pelo nome e não pelo conteúdo
        for nome in ("Lista.pdf", "Minuta do anúncio.pdf", "Anúncio DR.pdf",
                     "419971092.pdf", "espd-request.zip", "Anuncio_JOUE.pdf"):
            self.assertEqual(radar.papeis_da_peca(nome), set(), nome)


class TestOrcamentoDoDia(unittest.TestCase):
    """A conta tem dois tectos e só um se vê nos cabeçalhos."""

    class FalsaResposta:
        def __init__(self, texto):
            self.text, self.headers = texto, {}

    def test_reconhece_o_tecto_do_dia(self):
        # esperar e repetir num limite diário é tempo deitado fora:
        # uma releitura levou uma hora a não fazer nada
        self.assertTrue(radar.orcamento_do_dia_esgotado(self.FalsaResposta(
            "Rate limit reached ... on tokens per day (TPD): Limit 200000")))

    def test_nao_confunde_com_o_tecto_do_minuto(self):
        # esse passa sozinho ao fim de segundos, e vale a pena esperar
        self.assertFalse(radar.orcamento_do_dia_esgotado(self.FalsaResposta(
            "Rate limit reached ... on tokens per minute (TPM): Limit 8000")))

    def test_aguenta_resposta_vazia(self):
        self.assertFalse(radar.orcamento_do_dia_esgotado(
            self.FalsaResposta("")))


class TestEsperaPedida(unittest.TestCase):
    """Quanto esperar depois de um 429 -- o tecto de tokens por minuto.

    Marcar tres concursos seguidos bate no tecto; desistir a primeira
    perdia a leitura de um deles sem ninguem dar por isso.
    """

    class FalsaResposta:
        def __init__(self, cabecalhos, texto):
            self.headers, self.text = cabecalhos, texto

    def test_usa_o_cabecalho_da_api(self):
        self.assertEqual(radar.espera_pedida(
            self.FalsaResposta({"retry-after": "12.5"}, "")), 13.5)

    def test_sem_cabecalho_le_a_mensagem(self):
        self.assertEqual(radar.espera_pedida(self.FalsaResposta(
            {}, "Please try again in 8.42s. Visit...")), 9.42)

    def test_sem_pistas_espera_o_bastante(self):
        self.assertEqual(radar.espera_pedida(
            self.FalsaResposta({}, "nada")), 20.0)

    def test_ha_um_tecto_para_nao_ficar_pendurado(self):
        self.assertEqual(radar.espera_pedida(
            self.FalsaResposta({"retry-after": "9999"}, "")), 70)


class TestPrazoDeEsclarecimentos(unittest.TestCase):
    """Regra supletiva do art. 50.º CCP: 1.º terço do prazo das propostas.

    Não se lê do Programa de Concurso — calcula-se do que o anúncio já
    dá. Encontrada literalmente em 4 dos 6 PCs legíveis que se leram."""

    def esc(self, pub, prazo):
        d = radar.prazo_de_esclarecimentos(pub, prazo)
        return str(d) if d else None

    def test_primeiro_terco(self):
        # 27 dias entre publicação e prazo -> 9 dias depois da publicação
        self.assertEqual(self.esc("2026-08-25", "2026-09-21"), "2026-09-03")
        self.assertEqual(self.esc("2026-08-18", "2026-09-01"), "2026-08-22")

    def test_prazo_muito_curto(self):
        # 3 dias -> 1 dia; arredonda para baixo, nunca ultrapassa o terço
        self.assertEqual(self.esc("2026-08-25", "2026-08-28"), "2026-08-26")

    def test_datas_em_falta_ou_invalidas(self):
        for pub, prazo in (("2026-08-25", ""), ("", "2026-09-01"),
                           ("lixo", "2026-09-01"), (None, None)):
            with self.subTest(pub=pub, prazo=prazo):
                self.assertIsNone(self.esc(pub, prazo))

    def test_prazo_antes_da_publicacao_nao_inventa_data(self):
        self.assertIsNone(self.esc("2026-09-01", "2026-08-25"))
        self.assertIsNone(self.esc("2026-08-25", "2026-08-25"))

    def test_aparece_na_tabela_marcado_como_supletivo(self):
        anuncio = dict(TestTabelaEssencial.ANUNCIO, data_pub="2026-08-18")
        linha = next(l for l in radar.essencial_do_anuncio(anuncio, [])
                     if l[0] == "Data de esclarecimentos")
        rotulo, valor, falta, nota = linha
        self.assertIn("22/08/2026", valor)   # prazo 01/09/2026
        self.assertFalse(falta)              # deixou de estar em falta
        self.assertIn("supletiva", nota)     # mas diz que é calculado


class TestTextoDoPdf(unittest.TestCase):
    """Nunca rebentar: um PDF ilegível não pode parar a recolha."""

    def test_ficheiro_inexistente_devolve_erro_nao_excepcao(self):
        texto, estado = radar.texto_do_pdf("nao-existe-de-todo.pdf")
        self.assertEqual(texto, "")
        self.assertTrue(estado.startswith("erro"))

    def test_ficheiro_que_nao_e_pdf(self):
        texto, estado = radar.texto_do_pdf(__file__)   # este .py
        self.assertEqual(texto, "")
        self.assertTrue(estado.startswith("erro"))

    def test_ha_um_limiar_para_distinguir_digitalizacoes(self):
        # abaixo de N chars por página o PDF é imagem, e guardar o
        # "texto" dele seria guardar lixo
        self.assertGreater(radar.CHARS_POR_PAGINA_MINIMO, 0)


class TestDatas(unittest.TestCase):

    def test_normaliza_para_iso(self):
        self.assertEqual(radar.normaliza_data("23-08-2026"), "2026-08-23")
        self.assertEqual(radar.normaliza_data("23/08/2026"), "2026-08-23")
        self.assertEqual(radar.normaliza_data("2026-08-23"), "2026-08-23")


class TestETitulo(unittest.TestCase):
    """Distinguir um titulo de seccao de uma frase do corpo.

    Sem isto o orcamento de tokens gastava-se em frases que so por acaso
    tinham a palavra la dentro, e o anexo do fim do Caderno de Encargos
    -- que e onde mora o objecto -- ficava de fora do que se enviava.
    """

    def titulo(self, linha):
        return radar.e_titulo(linha.strip(), radar.simplifica(linha.strip()))

    def test_titulos_reais(self):
        for linha in ("Cláusula 1ª - Objeto do procedimento",
                      "Artigo 9.º  - Documentos da proposta",
                      "Anexo I - Especificações Técnicas",
                      "1. Objeto da Solução Tecnológica",
                      "3. Equipa",
                      "Perfil de Equipa"):
            self.assertTrue(self.titulo(linha), linha)

    def test_frases_do_corpo_nao_sao_titulos(self):
        # acabam em pontuacao de frase, ou comecam por minuscula
        for linha in ("2. As rejeições de serviços são objeto de notificação.",
                      "no âmbito do contrato;",
                      "equipa, em conjunto:",
                      "à prestação de serviços objeto do presente Caderno.",
                      "h)  Não subcontratar a execução do objeto do contrato, se"):
            self.assertFalse(self.titulo(linha), linha)

    def test_linha_comprida_nao_e_titulo(self):
        self.assertFalse(self.titulo("Verificação de Requisitos Legais: "
                                     "Funcionalidade para assinalar a "
                                     "conformidade de cada documento"))


class TestAncorasDoRecorte(unittest.TestCase):

    def empresa(self, linha, ancoras):
        import re
        curta = radar.simplifica(linha)
        return any(re.search(padrao, curta) for _, padrao in ancoras)

    def test_resolucao_nao_e_solucao(self):
        # "Clausula 24a - Resolucao do contrato" casava com "solucao" por
        # nao haver fronteira de palavra, e comia o orcamento todo
        self.assertFalse(self.empresa("Cláusula 24ª - Resolução do contrato",
                                   radar.ANCORAS_OBJECTO))
        self.assertFalse(self.empresa("Cláusula 35ª - Resolução de litígios",
                                   radar.ANCORAS_OBJECTO))
        self.assertTrue(self.empresa("1. Objeto da Solução Tecnológica",
                                  radar.ANCORAS_OBJECTO))

    def test_o_que_interessa_empresa(self):
        self.assertTrue(self.empresa("3. Equipa", radar.ANCORAS_EQUIPA))
        self.assertTrue(self.empresa("Cláusula 39ª Profissionais",
                                  radar.ANCORAS_EQUIPA))
        self.assertTrue(self.empresa("Artigo 9.º - Documentos da proposta",
                                  radar.ANCORAS_PROGRAMA))


class TestRecorteRelevante(unittest.TestCase):
    """O anexo do fim tem de sobreviver ao corte."""

    def documento(self):
        rotina = ("Cláusula %d - Penalidades" + chr(10) +
                  "Texto de rotina. " * 60 + chr(10))
        corpo = "".join(rotina % n for n in range(1, 20))
        return (corpo + chr(10) + "3. Equipa" + chr(10) +
                "A equipa é composta por um gestor e um arquiteto." + chr(10))

    def test_apanha_o_anexo_do_fim(self):
        d = self.documento()
        r = radar.recorte_relevante(d, radar.ANCORAS_EQUIPA, 4000)
        self.assertIn("3. Equipa", r)
        self.assertIn("gestor e um arquiteto", r)

    def test_respeita_o_tecto(self):
        # o tecto e o limite de tokens por minuto da API: passar dele e 413
        d = self.documento()
        self.assertLessEqual(len(radar.recorte_relevante(
            d, radar.ANCORAS_EQUIPA, 2000)), 2000)

    def test_a_equipa_nao_disputa_o_orcamento_com_o_objecto(self):
        # num Caderno de Encargos de 167 mil caracteres, a tabela de
        # perfis estava na posicao 136 mil e as ancoras do objecto
        # gastavam o orcamento muito antes; o modelo respondia
        # "conforme o Anexo I", que e verdade e nao serve
        cabeca = ("Cláusula %d Objeto e âmbito da solução" + chr(10) +
                  "Texto de rotina sobre o objeto. " * 40 + chr(10))
        documento = ("".join(cabeca % n for n in range(1, 30)) + chr(10) +
                     "Cláusula 39ª Profissionais" + chr(10) +
                     "Gestor de Projeto 8 anos Certificação em Gestão" + chr(10))
        r = radar.recorte_relevante(documento, radar.ANCORAS_EQUIPA, 4000)
        self.assertIn("Gestor de Projeto 8 anos", r)

    def test_sem_ancoras_devolve_o_principio(self):
        d = "Texto sem titulos nenhuns. " * 300
        r = radar.recorte_relevante(d, radar.ANCORAS_OBJECTO, 500)
        self.assertEqual(r, d[:500])


class TestORecorteLevaAResposta(unittest.TestCase):
    """O que chega ao modelo tem de conter a resposta (28/09/2026).

    Quatro agentes compararam as 70 leituras com as peças, e das 59
    passagens que provaram lá estar só 20 chegavam ao modelo. Cada teste é
    uma das causas medidas nesse dia."""

    NL = chr(10)

    def rotina(self, n=20):
        return "".join(("Cláusula %d - Penalidades" % i) + self.NL +
                       "Texto de rotina. " * 60 + self.NL for i in range(1, n))

    def test_a_frase_da_lista_vale_sem_ser_titulo(self):
        # «...pelos seguintes documentos:» acaba em dois pontos, nao e
        # titulo, e so os titulos ancoravam
        d = (self.rotina() + "2. A proposta deve ser constituída, sob pena de "
             "exclusão, pelos seguintes documentos:" + self.NL +
             "a) Declaração de aceitação do Anexo I" + self.NL + self.rotina(5))
        r = radar.recorte_relevante(d, radar.ANCORAS_PROGRAMA, 4000)
        self.assertIn("Declaração de aceitação do Anexo I", r)

    def test_o_sumario_nao_leva_a_janela(self):
        # «7. DOCUMENTOS DA PROPOSTA 5», no sumario sem pontinhos, vinha
        # primeiro e ficava com a janela do artigo
        d = ("7. DOCUMENTOS DA PROPOSTA 5" + self.NL + "8. PREÇO 6" + self.NL +
             self.rotina() + "7. Documentos da proposta" + self.NL +
             "a) DEUCP" + self.NL + self.rotina(5))
        r = radar.recorte_relevante(d, radar.ANCORAS_PROGRAMA, 3000)
        self.assertIn("a) DEUCP", r)

    def test_a_tabela_do_fim_nao_e_cortada(self):
        # o orcamento cortava pela ordem do documento: a tabela dos perfis
        # no ultimo anexo era escolhida e depois deitada fora
        perfis = "".join("Experiência mínima de %d anos como Business Analyst" % n
                         + self.NL for n in range(3, 9))
        d = ("Perfil" + self.NL + "Texto sobre o perfil do concorrente. " * 40 +
             self.NL + self.rotina() + "ANEXO III – PERFIS DO PROCEDIMENTO" +
             self.NL + perfis)
        r = radar.recorte_relevante(d, radar.ANCORAS_EQUIPA, 3000)
        self.assertIn("5 anos como Business Analyst", r)
        self.assertLessEqual(len(r), 3000)

    def test_o_mesmo_documento_duas_vezes_conta_uma(self):
        # o PDF e o mesmo Caderno dentro do ZIP gastavam metade do recorte
        texto = "Cláusula 1 - Objeto" + self.NL + "Fornecer licenças." + self.NL
        docs = [{"nome": "Caderno_de_Encargos.pdf", "texto": texto},
                {"nome": "Caderno de Encargos rev 1.pdf", "texto": texto}]
        _, usados = radar.pecas_para_analise(docs, "encargos", radar.ANCORAS_OBJECTO)
        self.assertEqual(len(usados), 1, usados)

    def test_a_equipa_procura_tambem_no_programa(self):
        # as certificacoes exigidas estavam no Programa, e a leitura da
        # equipa so abria o Caderno: «nao consta»
        ce = "Cláusula 1 - Objeto" + self.NL + "Prestar serviços." + self.NL
        pp = (self.rotina(5) + "Requisitos mínimos da equipa" + self.NL +
              "Certificação em ISO 27001 Lead Implementer" + self.NL)
        docs = [{"nome": "Caderno_de_Encargos.pdf", "texto": ce},
                {"nome": "Programa_do_Concurso.pdf", "texto": pp}]
        recorte, _ = radar.pecas_para_analise(docs, "encargos", radar.ANCORAS_EQUIPA)
        self.assertIn("Lead Implementer", recorte)

    def test_o_programa_sem_ancoras_nao_entra_pelo_principio(self):
        # uma peca que se abre por acrescento so da o que as ancoras
        # apanharem: o principio do Programa nao e resposta nenhuma
        ce = "Cláusula 1 - Objeto" + self.NL + "Prestar serviços." + self.NL
        pp = "Artigo 1 - Disposições gerais" + self.NL + "Nada. " * 50
        docs = [{"nome": "Caderno_de_Encargos.pdf", "texto": ce},
                {"nome": "Programa_do_Concurso.pdf", "texto": pp}]
        recorte, usados = radar.pecas_para_analise(docs, "encargos",
                                                   radar.ANCORAS_OBJECTO)
        self.assertNotIn("Disposições gerais", recorte)
        self.assertEqual(usados, ["Caderno_de_Encargos.pdf"])

    def test_sem_leitura_a_peca_em_falta_nao_passa_por_lida(self):
        # o campo que nao se leu fica None: com "" a ficha dizia «o
        # Programa foi lido e nao encontrou a lista» sem Programa nenhum
        junto = radar.juntar_leituras({"objecto": "- fazer X"}, None)
        self.assertIsNone(junto["documentos_proposta"])

    def pecas_grandes(self):
        # um Caderno e um anexo tecnico enormes, e um Programa cheio de
        # frases que as ancoras da equipa apanham
        perfis = "".join("Experiência mínima de %d anos em Java" % n + self.NL
                         for n in range(1, 400))
        return [{"nome": "Caderno_de_Encargos.pdf",
                 "texto": "3. Equipa" + self.NL + perfis},
                {"nome": "Anexo_Especificacao_Tecnica.pdf",
                 "texto": "3. Equipa" + self.NL + perfis},
                {"nome": "Programa_do_Concurso.pdf",
                 "texto": "Requisitos mínimos da equipa" + self.NL + perfis}]

    def test_o_pedido_nao_passa_de_tecto_e_meio(self):
        # 28/09/2026: a releitura bateu no limite da Groq (413). O portugues
        # destes documentos anda nos 2,75 caracteres por token, e 2 x o
        # tecto, com as instrucoes e a resposta, chegava aos 7 400 tokens
        recorte, _ = radar.pecas_para_analise(self.pecas_grandes(), "encargos",
                                              radar.ANCORAS_EQUIPA, 7000)
        self.assertLessEqual(len(recorte), 7000 * 1.5)

    def test_a_peca_por_acrescento_leva_so_uma_zona(self):
        # com o tecto da peca, o Programa aberto por acrescento enchia o
        # pedido ate ao tecto total em quase todos os concursos
        docs = self.pecas_grandes()[2:]
        docs.insert(0, {"nome": "Caderno_de_Encargos.pdf", "texto": "Nada." + self.NL})
        recorte, _ = radar.pecas_para_analise(docs, "encargos",
                                              radar.ANCORAS_EQUIPA, 7000)
        programa = recorte.split("### Programa_do_Concurso.pdf")[1]
        self.assertLessEqual(len(programa), radar.TECTO_SECUNDARIA + 20)

    def test_a_reserva_e_a_groq_com_outro_modelo(self):
        # a NVIDIA deixou de servir a 3/09/2026 (o modelo saiu), e ha quase
        # um mes que o dia acabava quando o tecto da Groq acabava; o tecto
        # diario da Groq e por modelo
        reserva = {f[0]: f for f in radar.FORNECEDORES}["groq-reserva"]
        self.assertEqual(reserva[1], radar.GROQ_URL)
        self.assertNotEqual(reserva[2], radar.GROQ_MODELO)

    def test_a_nvidia_le_sem_raciocinio(self):
        # 28/09/2026: com o raciocinio ligado os modelos da NVIDIA passavam
        # os minutos a «pensar» e estouravam o timeout; o gpt-oss-120b de la
        # saiu a 3/09 (410)
        nvidia = {f[0]: f for f in radar.FORNECEDORES}["nvidia"]
        self.assertNotEqual(nvidia[2], "openai/gpt-oss-120b")
        self.assertEqual(nvidia[5].get("chat_template_kwargs"),
                         {"enable_thinking": False})

    def test_o_cerebras_vem_logo_a_seguir_a_groq_e_so_com_chave(self):
        # o mesmo modelo da Groq, com 1 milhao de tokens por dia: vem antes
        # das reservas de outros modelos; sem chave, a cadeia salta-o
        nomes = [f[0] for f in radar.FORNECEDORES]
        self.assertEqual(nomes[:2], ["groq", "cerebras"])
        # e a reserva da Groq no fim, desde 29/09/2026: o único modelo que
        # errou números (TestTerceiraRondaDaLeitura)
        self.assertEqual(nomes[-1], "groq-reserva")
        with unittest.mock.patch.object(radar, "ler_chave",
                                        lambda nomes, var: "" if var == "CEREBRAS_API_KEY" else "k"):
            self.assertNotIn("cerebras", [f[0] for f in radar.cadeia_de_fornecedores({})])

    def test_o_gemini_entra_antes_da_reserva_e_so_com_chave(self):
        # 30/09/2026: o Gemini entra atrás de todos os outros e antes da
        # reserva da Groq, até as leituras dele serem julgadas; a chave é
        # a de um projecto Google só para a leitura (o MiroFish usa outro)
        nomes = [f[0] for f in radar.FORNECEDORES]
        self.assertEqual(nomes[-2:], ["gemini", "groq-reserva"])
        gemini = {f[0]: f for f in radar.FORNECEDORES}["gemini"]
        self.assertIn("generativelanguage.googleapis.com", gemini[1])
        self.assertEqual(gemini[3], ("gemini_API_KEY.txt",))
        with unittest.mock.patch.object(radar, "ler_chave",
                                        lambda nomes, var: "" if var == "GEMINI_API_KEY" else "k"):
            self.assertNotIn("gemini", [f[0] for f in radar.cadeia_de_fornecedores({})])


class TestSegundaRondaDaLeitura(unittest.TestCase):
    """29/09/2026: quatro agentes voltaram a julgar as 70 leituras,
    relidas com o código da primeira ronda, e a régua das passagens
    (agora 88) passou de 52 a 82. Cada teste é uma causa medida nesse
    dia."""

    NL = chr(10)

    def rotina(self, n=20):
        return "".join(("Cláusula %d - Penalidades" % i) + self.NL +
                       "Texto de rotina. " * 60 + self.NL for i in range(1, n))

    def test_a_clausula_curta_do_local_nao_perde_para_a_zona_densa(self):
        # 21295: a «Cláusula 5.ª Local da prestação de serviços» ficava
        # fora, porque as janelas se escolhiam só pela densidade e uma
        # zona cheia de títulos ganhava-lhe sempre
        local = ("Cláusula 5.ª Local da prestação de serviços" + self.NL +
                 "A prestação de serviços será executada nas instalações da "
                 "entidade, sitas no Parque de Saúde de Lisboa." + self.NL)
        # nomes distintos: o mesmo título repetido conta uma vez só
        densa = "".join("%d. Âmbito do módulo %s" % (i, chr(97 + i % 26) * (1 + i // 26))
                        + self.NL + "Descrição do módulo. " * 5 + self.NL
                        for i in range(1, 60))
        d = local + self.rotina(8) + densa
        r = radar.recorte_relevante(d, radar.ANCORAS_OBJECTO, 3000)
        self.assertIn("Parque de Saúde de Lisboa", r)

    def test_a_lista_vai_ate_ao_fim_do_artigo(self):
        # 21295, 21296, 21924: as notas entre as alíneas empurravam a e),
        # a f) e a g) para fora dos 2 500 caracteres da janela
        notas = "Nota: texto longo sobre os currículos. " * 40 + self.NL
        artigo = ("Artigo 6.º" + self.NL + "Documentos que constituem as propostas" +
                  self.NL + "1. As propostas devem ser constituídas pelos seguintes "
                  "documentos, sob pena de exclusão:" + self.NL +
                  "a) DEUCP;" + self.NL + "b) Modelo da proposta;" + self.NL +
                  "c) Currículos;" + self.NL + notas + "d) Declaração;" + self.NL +
                  notas + "e) Documentos dos terceiros;" + self.NL +
                  "g) O formulário principal da proposta." + self.NL +
                  "Artigo 7.º" + self.NL + "Preço base" + self.NL)
        d = self.rotina() + artigo + self.rotina(5)
        r = radar.recorte_relevante(d, radar.ANCORAS_PROGRAMA, 7000)
        self.assertIn("formulário principal da proposta", r)
        # e acaba no artigo seguinte: o resto não vem por arrasto
        self.assertNotIn("Preço base", r)

    def test_o_limiar_nao_perde_o_lugar_para_a_lista(self):
        # 14680: as seis frases da lista juntavam-se na mesma zona, e a
        # frase do preço anormalmente baixo, sozinha, ficava sem janela
        lista = "".join("Os documentos que constituem a proposta devem %d. " % i +
                        "Texto. " * 30 + self.NL for i in range(8))
        d = (self.rotina(5) + lista + self.rotina(10) +
             "Considera-se que o preço total é anormalmente baixo quando "
             "for inferior a 2.000.000,00 €." + self.NL + self.rotina(5))
        r = radar.recorte_relevante(d, radar.ANCORAS_PROGRAMA, 3000)
        self.assertIn("2.000.000,00", r)

    def test_o_pab_do_titulo_numerado(self):
        # 21877: «15.5. Preço Anormalmente Baixo por Artigo Unitário (PAB
        # Unitário)» não passa por título, e o «inferior» estava na linha
        # seguinte
        d = (self.rotina() + "15.5.  Preço Anormalmente Baixo por Artigo "
             "Unitário (PAB Unitário)" + self.NL + "considera-se que a proposta "
             "de um preço unitário inferior a 60% do Preço Máximo" + self.NL +
             self.rotina(5))
        r = radar.recorte_relevante(d, radar.ANCORAS_PROGRAMA, 3000)
        self.assertIn("inferior a 60%", r)

    def test_a_lista_partida_pelo_ocr(self):
        # 23010: «deve ainda indicar/apresentar os seguintes» e, na linha
        # de baixo, «elementos/docu mentos:»; e não a lista da habilitação
        d = (self.rotina() + "3. Na proposta, o concorrente deve ainda "
             "indicar/apresentar os seguintes" + self.NL + "elementos/docu mentos:" +
             self.NL + "f) Preços unitários, não superiores ao Despacho n.º 1371/2016" +
             self.NL + self.rotina(5))
        r = radar.recorte_relevante(d, radar.ANCORAS_PROGRAMA, 3000)
        self.assertIn("1371/2016", r)
        curta = radar.simplifica("deve apresentar os seguintes documentos de habilitação:")
        self.assertFalse(re.search(radar.ANCORAS_PROGRAMA[0][1], curta))
        # 23577: «deverá ser constituída com os seguintes documentos»
        self.assertTrue(re.search(radar.ANCORAS_PROGRAMA[0][1], radar.simplifica(
            "1. Cada proposta deverá ser constituída com os seguintes documentos:")))

    def test_o_ultimo_documento_escolhe_dentro_do_que_sobra(self):
        # 23265: o anexo técnico tinha a lista dos perfis na segunda
        # janela, e o [:1,5 x tecto] cortava-o pela ordem do texto
        ce = self.rotina(12) + "3. Equipa" + self.NL + "Texto. " * 900 + self.NL
        anexo = ("5. Requisitos Técnicos" + self.NL + "Requisito. " * 400 + self.NL +
                 self.rotina(8) + "9. Equipa Técnica" + self.NL +
                 "uma equipa multidisciplinar que inclua, no mínimo, os seguintes "
                 "perfis: Gestor de projeto; UX Designer" + self.NL)
        docs = [{"nome": "Caderno_de_Encargos.pdf", "texto": ce},
                {"nome": "Anexo_Clausulas_tecnicas.pdf", "texto": anexo}]
        recorte, _ = radar.pecas_para_analise(docs, "encargos", radar.ANCORAS_EQUIPA, 4000)
        self.assertIn("UX Designer", recorte)
        self.assertLessEqual(len(recorte), 6000)

    def test_sem_caderno_o_programa_faz_as_vezes_dele(self):
        # 22005: «Peças do procedimento» são o Programa e o Caderno num
        # PDF só; pelo nome só passavam por Programa, e a leitura do
        # objecto levava delas uma zona de 2 500 caracteres
        texto = ("Cláusula 1.ª Objeto" + self.NL + "Licenças." + self.NL +
                 self.rotina(10) + "Entrega dos bens objeto do contrato" + self.NL +
                 "Os bens devem ser entregues faseadamente no IPO-Porto." + self.NL)
        docs = [{"nome": "Peças do procedimento CP 2298_26.pdf", "texto": texto}]
        recorte, _ = radar.pecas_para_analise(docs, "encargos", radar.ANCORAS_OBJECTO)
        self.assertIn("IPO-Porto", recorte)

    def test_o_local_nomeado_sem_regime(self):
        # 23794, 21877: a morada vinha numa frase «situada na» ou num
        # título «LOCALIZAÇÃO», e não batia; a força maior de todos os
        # Cadernos («com origem nas instalações do adjudicatário») não
        # gasta a reserva
        rx = radar.ANCORAS_OBJECTO[0][1]
        for frase in ("vigilância no edifício situado na Rua de São Martinho",
                      "Locais de entrega dos bens"):
            self.assertTrue(re.search(rx, radar.simplifica(frase)), frase)
        self.assertFalse(re.search(rx, radar.simplifica(
            "e) Incêndios ou inundações com origem nas instalações do adjudicatário")))
        titulos = [r for p, r in radar.ANCORAS_OBJECTO if p == 1]
        self.assertTrue(any(re.search(r, "2.5 localizacao e delimitacoes") for r in titulos))
        # no corpo, «localização» é ruído (a especificação de um SIG, 22001)
        self.assertFalse(any(re.search(r, "com indicacao da localizacao")
                             for p, r in radar.ANCORAS_OBJECTO if p == 0))

    def test_a_pergunta_do_local_aceita_o_sitio_sem_regime(self):
        # os quatro perfis: «não consta» com a cláusula «Local de…» a
        # chegar ao modelo, porque a pergunta só aceitava um regime
        i = radar.INSTRUCOES_OBJECTO
        self.assertIn("mesmo sem regime nenhum", i)
        self.assertIn("não é \"Remoto\"", i)
        self.assertIn("cabeçalho", i)
        self.assertNotIn("Se o documento não disser nada sobre presença nem regime", i)

    def test_o_sla_vence_a_manutencao(self):
        # 22719, 22949, 23728: «Tempos de resposta: —» com o SLA nas peças
        manutencao = "".join("%d. Manutenção do equipamento %d" % (i, i) + self.NL +
                             "Texto. " * 30 + self.NL for i in range(1, 40))
        d = (manutencao + self.rotina(5) + "Em situações de urgência: a) O tempo "
             "de resposta máximo é de 4 horas" + self.NL + "b) O prazo de "
             "reposição é de 8 horas." + self.NL + self.rotina(3))
        r = radar.recorte_relevante(d, radar.ANCORAS_SERVICOS, 3000)
        self.assertIn("4 horas", r)

    def test_a_equipa_em_frases_do_corpo(self):
        # 23804 («6 FTEs»), 21969 («os seguintes perfis»), 22956
        # («deverá(ão) possuir experiência técnica em»)
        rx = radar.ANCORAS_EQUIPA[0][1]
        for frase in ("dimensão miníma da equipa (equipa base) para 6 FTEs",
                      "a equipa afeta deve incluir, no mínimo, os seguintes perfis:",
                      "O(s) Programador(es) deverá(ão) possuir experiência técnica em C#"):
            self.assertTrue(re.search(rx, radar.simplifica(frase)), frase)
        # a «equipa técnica» das grelhas de pontuação não (21631)
        self.assertFalse(re.search(rx, radar.simplifica(
            "Equipa técnica constituída por 2 elementos")))

    def test_a_pergunta_da_equipa(self):
        # 21631 e 20445 (a dimensão mínima), 23265 (a lista só de
        # nomes), 22754 (o gestor do contrato da ESPAP como perfil)
        i = radar.INSTRUCOES_EQUIPA
        for pedaco in ("DIMENSÃO MÍNIMA", "gestor do contrato",
                       "lista só com os nomes", "noutra tabela ou num total"):
            self.assertIn(pedaco, i)
        # e não cresce sem conta: o pedido inteiro fica debaixo do limite
        # da Groq. Eram 2 842; a 29/09/2026 passou a 2 939 com a página em
        # cada linha, o nível de serviço e o que só pontua (3.ª ronda), e
        # o maior pedido de todos foi de 13 430 a 13 933 caracteres
        self.assertLessEqual(len(i), 2939)

    def test_a_pergunta_das_obras_sem_alvara(self):
        # o alvará vem do anúncio, e a leitura só produzia negações
        # falsas; a remissão para a lei é um requisito, e não «—»
        self.assertNotIn("Alvará:", radar.INSTRUCOES_OBRAS)
        self.assertIn("Lei n.º", radar.INSTRUCOES_OBRAS)

    def test_o_objecto_das_obras_le_a_memoria_descritiva(self):
        # 11 de 17 obras com o objecto feito de cláusulas-tipo: o que se
        # constrói está na memória descritiva, que se chama «MD»
        for nome in ("2. MD_signed.pdf", "ConstCivil_MDJ_ADig.pdf",
                     "1-MDAVAC-Valado-v1.docx"):
            self.assertIn("tecnico", radar.papeis_da_peca(nome), nome)
        obras = dict((n, (q, a, i)) for n, q, a, i in
                     radar.leituras_da_familia(list(radar.LEITURAS), "obras"))
        quais, ancoras, instrucao = obras["objecto"]
        self.assertIn("livro de", instrucao)
        ce = ("Cláusula 1.ª Objeto" + self.NL + "O presente caderno tem por objeto a "
              "empreitada X, de acordo com o projeto." + self.NL + self.rotina(10))
        md = ("MEMÓRIA DESCRITIVA E JUSTIFICATIVA" + self.NL + "A presente memória "
              "descritiva refere-se à intervenção nos edifícios C1 e C2." + self.NL)
        docs = [{"nome": "Caderno_de_Encargos.pdf", "texto": ce},
                {"nome": "2. MD_signed.pdf", "texto": md}]
        recorte, _ = radar.pecas_para_analise(docs, quais, ancoras)
        self.assertIn("edifícios C1 e C2", recorte)
        self.assertLess(recorte.index("edifícios C1 e C2"), recorte.index("empreitada X"))

    def test_a_vigilancia_com_a_hora_longe(self):
        # 23794: «vigilância», e não «vigilante», com a hora a 66 caracteres
        rx = radar.ANCORAS_MAO_DE_OBRA[0][1]
        self.assertTrue(re.search(rx, radar.simplifica(
            "* A vigilância das 0:00-07:00h na noite de quarta-feira")))
        self.assertTrue(re.search(rx, radar.simplifica(
            "Serviço de vigilância - Quarta-Feira para Quinta-Feira | Reforço com "
            "mais 1 vigilante | 00:00-07:00")))

    def test_o_progconc_e_o_programa(self):
        # 23492: sem ele a leitura da proposta só tinha o CE
        self.assertEqual(radar.papeis_da_peca("2_ProgConc_40.341.233.109_26.pdf"),
                         {"programa"})

    def test_o_anexo_partido_pelo_extractor(self):
        # 23610 e 23612: «Anexo I II» e a leitura dizia «Anexo II», o
        # modelo da declaração, em vez do III, o da proposta de preço
        self.assertIn("Anexo III ao presente",
                      radar.sem_indice("modelo constante do Anexo I II ao presente"))
        self.assertIn("Anexos I e II", radar.sem_indice("os Anexos I e II"))


class TestTerceiraRondaDaLeitura(unittest.TestCase):
    """29/09/2026, à tarde: quatro perfis julgaram as 75 leituras relidas
    com a segunda ronda, e o princípio que ele deu nesse dia manda nesta:
    «não quero que decida por ninguém, mas sim que faça um resumo em que
    se pode confiar, sempre com a leitura das peças associada». A régua
    passou a 113 passagens; as 88 de antes ficam em 82 e as 25 novas vão
    de 12 a 21. Cada teste é uma causa medida nesse dia."""

    NL = chr(10)

    def rotina(self, n=20):
        return "".join(("Cláusula %d - Penalidades" % i) + self.NL +
                       "Texto de rotina. " * 60 + self.NL for i in range(1, n))

    # --- o recorte ------------------------------------------------------

    def test_o_ordinal_do_sumario_nao_separa_o_titulo_do_corpo(self):
        # 23577: «14ª Documentos da proposta» dava a chave «a documentos
        # da proposta», e o sumário -- onde os títulos se juntam -- ficava
        # com a janela, e o limiar do corpo de fora
        chave = lambda t: radar.RX_NUMERACAO_DO_TITULO.sub("", radar.simplifica(t))
        self.assertEqual(chave("14ª Documentos da proposta"), "documentos da proposta")
        self.assertEqual(chave("1.º Objeto"), "objeto")
        self.assertEqual(chave("A proposta"), "a proposta")

    def test_a_caucao_considerada_anormalmente_baixa_nao_e_o_limiar(self):
        # 23577: «seja considerado anormalmente baixo, o valor da caução»
        # levava a reserva do limiar, que ficava fora
        rx = radar.ANCORAS_PROGRAMA[1][1]
        self.assertFalse(re.search(rx, radar.simplifica(
            "Caso o preço contratual seja considerado anormalmente baixo, o valor da caução")))
        for frase in ("considera-se que o preço de uma proposta é anormalmente baixo quando",
                      "São consideradas propostas de preço anormalmente baixo as que"):
            self.assertTrue(re.search(rx, radar.simplifica(frase)), frase)

    def test_os_documentos_depois_da_adjudicacao_nao_sao_a_lista(self):
        # 14680: «o ACE deve apresentar os seguintes documentos no prazo
        # de 20 dias contados da notificação da adjudicação»
        rx = radar.ANCORAS_PROGRAMA[0][1]
        self.assertFalse(re.search(rx, radar.simplifica(
            "o ACE deve apresentar os seguintes documentos no prazo de 20 (vinte) dias "
            "contados da notificação da adjudicação:")))

    def test_a_numeracao_em_dois_niveis_e_titulo(self):
        # 21724: «7.3. Requisitos» do Técnico de Helpdesk não era título
        for t in ("7.3. Requisitos", "7.3 Requisitos", "15.5. Preço Anormalmente Baixo"):
            self.assertTrue(radar.e_titulo(t, radar.simplifica(t)), t)
        # uma linha de tabela continua a não ser
        self.assertFalse(radar.e_titulo("2 Security Gateway", "2 security gateway"))
        rx = [r for p, r in radar.ANCORAS_EQUIPA if p == 1][0]
        self.assertTrue(re.search(rx, "7.3. requisitos"))

    def test_o_nivel_de_servico_nos_contratos_de_ti(self):
        # 21811, 22036, 22540, 22956: a família «equipa» nunca o pedia
        fortes = [r for p, r in radar.ANCORAS_EQUIPA if p == 0]
        for frase in ("Para pedidos classificados com prioridade elevada, o tempo máximo de",
                      "níveis de serviço (SLA) para tempo de resposta a incidentes:",
                      "Tempo máximo de resposta técnica remota 30 minutos",
                      "Cocontratante deverá assegurar os seguintes tempos máximos"):
            self.assertTrue(any(re.search(r, radar.simplifica(frase)) for r in fortes), frase)
        self.assertIn("Nível de serviço", radar.INSTRUCOES_EQUIPA)

    def test_as_licencas_com_cpv_de_ti_sao_bens(self):
        # 21659, 22682, 23589: artigos com quantidade lidos como perfis
        f = radar.familia_do_contrato
        for titulo, cpv in (("Licenciamento e manutenção de rede check Point", "72267000"),
                            ("Aquisição de Serviços de Suporte e Renovação do "
                             "Licenciamento CISCO", "72500000"),
                            ("Serviços Renovação Suporte AVAMAR 2026", "72100000")):
            self.assertEqual(f("Aquisição de Serviços", cpv, titulo), "bens", titulo)
        # com trabalho de equipa no mesmo contrato, fica equipa
        for titulo in ("Aquisição de serviços de suporte técnico e manutenção adaptativa "
                       "e evolutiva da plataforma DSpace",
                       "Renovação de Licenciamento, Manutenção Operativa e Evolutiva"):
            self.assertEqual(f("Aquisição de Serviços", "72267000", titulo), "equipa", titulo)
        # e sem designação, como antes
        self.assertEqual(f("Aquisição de Serviços", "72267000"), "equipa")
        texto = ("6 - OBJETO DO CONTRATO\nDesignação do contrato: Licenças Office 2024\n"
                 "Tipo de Contrato Principal: Aquisição de Serviços\n")
        self.assertEqual(radar.familia_do_anuncio(texto, "72268000"), "bens")

    def test_a_lista_dos_itens_dos_bens(self):
        # 21659: «2- O fornecimento compreende os seguintes itens:»
        rx = radar.ANCORAS_BENS[0][1]
        self.assertTrue(re.search(rx, radar.simplifica(
            "2- O fornecimento compreende os seguintes itens:")))

    def test_o_lista_pdf_pelo_que_diz(self):
        # 23513: os artigos (16 AEC Collection, 20 AutoCAD LT) estavam no
        # «Lista.pdf», que ficava de fora por ser «o índice das peças»
        artigos = ("Município de Santarém" + self.NL + "Procedimento 157" + self.NL +
                   "Lista de artigos" + self.NL + "Linha Cod. Designação Unidade Qtd")
        self.assertEqual(radar.papeis_da_peca("Lista.pdf", artigos), {"tecnico"})
        self.assertEqual(radar.papeis_da_peca("Lista.pdf"), set())
        self.assertEqual(radar.papeis_da_peca("Lista.pdf", "Caderno de Encargos.pdf"), set())
        docs = [{"nome": "Caderno_de_Encargos.pdf", "texto": "Cláusula 1 - Objeto" + self.NL},
                {"nome": "Lista.pdf", "texto": artigos + self.NL +
                 "4 4 AutoCAD LT - Government Single-user UN 20"}]
        recorte, _ = radar.pecas_para_analise(docs, "encargos", radar.ANCORAS_BENS)
        self.assertIn("AutoCAD LT", recorte)

    def test_o_mapa_das_obras_vai_pelos_capitulos(self):
        # 23723: «1.0 CONSTRUÇÃO DE MURO DE BETÃO CICLÓPICO NA RUA DE
        # REVILHÃES» estava no mapa, e o objecto era uma remissão
        mapa = self.NL.join([
            "Município de Amarante", "Procedimento CP/56/2026",
            "Lista de todas as espécies de trabalhos previstos no Caderno de Encargos",
            "Linha Cod. Designação Unidade Qtd",
            " 1.0 CONSTRUÇÃO DE MURO DE BETÃO CICLÓPICO NA RUA DE REVILHÃES",
            " 1.1 ESTALEIRO",
            "1 1.1.1 Fornecimento, montagem e desmontagem de estaleiro " + "texto " * 200,
            "VG 1", " 2.0 MURO DE PEDRA NA RUA DA GRANJA"])
        capitulos = radar.capitulos_do_mapa(mapa, 7000)
        self.assertIn("MURO DE BETÃO CICLÓPICO", capitulos)
        self.assertIn("RUA DA GRANJA", capitulos)
        self.assertNotIn("Fornecimento, montagem", capitulos)
        self.assertEqual(radar.capitulos_do_mapa("Cláusula 1 - Objeto", 7000), "")
        obras = dict((n, (q, a)) for n, q, a, _ in
                     radar.leituras_da_familia(list(radar.LEITURAS), "obras"))
        quais, ancoras = obras["objecto"]
        recorte, _ = radar.pecas_para_analise(
            [{"nome": "Lista.pdf", "texto": mapa}], quais, ancoras)
        self.assertIn("RUA DA GRANJA", recorte)
        self.assertIn("Capítulos do mapa", radar.INSTRUCOES_OBJECTO_OBRAS)

    def test_o_caderno_da_ip_partido_por_capitulos(self):
        # 21999: a equipa técnica no «Cap7_CondicoesParticulares_L1.pdf»,
        # e a memória descritiva em «..._Mem Descritiva_12jan26.pdf»
        self.assertIn("encargos", radar.papeis_da_peca("Cap7_CondicoesParticulares_L1.pdf"))
        self.assertIn("encargos", radar.papeis_da_peca("Cap1_ClausulasGerais_L1.pdf"))
        self.assertEqual(radar.papeis_da_peca("CCP 2026_EN249-3_Mem Descritiva_12jan26.pdf"),
                         {"tecnico"})
        self.assertEqual(radar.papeis_da_peca("MQTEN249-3.0026.2026.pdf"), {"tecnico"})

    def test_a_frase_que_abre_a_equipa_das_obras(self):
        # 14680 e 21999: a lista da equipa técnica abre numa frase do
        # corpo, e o título não chegava
        rx = radar.ANCORAS_OBRAS[0][1]
        for frase in ("A equipa técnica a afetar à obra na substituição das Escadas "
                      "deverá integrar, obrigatoriamente, os seguintes técnicos:",
                      "7.3.2 O elenco da Equipa Técnica é o seguinte:"):
            self.assertTrue(re.search(rx, radar.simplifica(frase)), frase)

    def test_os_servicos_leem_a_resposta_e_a_carteira(self):
        # 22460 e 23351
        rx = radar.ANCORAS_SERVICOS[0][1]
        for frase in ("d) Dar resposta a qualquer solicitação, no prazo máximo de 24 horas;",
                      "Técnicos Eletricistas com carteira profissional, emitida pela DGEG",
                      "Artigo 10.º Habilitações necessárias"):
            self.assertTrue(re.search(rx, radar.simplifica(frase)), frase)

    def test_sem_artigos_a_lista_leva_a_janela_do_artigo(self):
        # 14680: o Programa em .docx perde a numeração dos títulos, e a
        # lista ficava nos 2 500 caracteres; as últimas alíneas caíam
        itens = "".join("Documento %d, com a designação longa que o Programa lhe dá. " % i
                        + "Texto. " * 40 + self.NL for i in range(1, 10))
        d = ("Documentos que constituem a proposta" + self.NL +
             "Sob pena de exclusão, a proposta deverá ser constituída pelos seguintes "
             "documentos:" + self.NL + itens + "Declaração de compromisso de cibersegurança."
             + self.NL + "Texto de rotina. " * 400)
        self.assertLess(len(d.split("cibersegurança")[0]), radar.JANELA_DO_ARTIGO)
        self.assertGreater(len(d.split("cibersegurança")[0]), radar.JANELA_FORTE)
        r = radar.recorte_relevante(d, radar.ANCORAS_PROGRAMA, 7000)
        self.assertIn("cibersegurança", r)

    # --- A. a leitura sempre associada às peças -------------------------

    def test_a_pagina_marcada_no_recorte(self):
        paginas = ["Cláusula %d - Penalidades%sTexto de rotina. %s" % (i, self.NL, self.NL)
                   for i in range(1, 5)]
        paginas[2] = ("Cláusula 3 - Objeto" + self.NL + "O objeto é a manutenção." +
                      self.NL)
        texto = "\f".join(paginas)
        r = radar.recorte_relevante(texto, radar.ANCORAS_OBJECTO, 400)
        self.assertIn("[pág. 3]" + self.NL + "Cláusula 3 - Objeto", r)
        self.assertLessEqual(len(r), 400)
        self.assertNotIn("\f", r)
        # sem as marcas do extractor não se inventam páginas
        self.assertNotIn("[pág.", radar.recorte_relevante(
            texto.replace("\f", self.NL), radar.ANCORAS_OBJECTO, 400))

    def test_a_pergunta_pede_a_pagina_em_cada_linha(self):
        for instrucao in [i for _, _, _, i in radar.LEITURAS] + [
                v[3] for v in radar.CAMPO_11.values() if v[3]]:
            self.assertIn("(pág. 12)", instrucao)
            self.assertIn("(Programa, pág. 5)", instrucao)

    def test_o_numero_que_nao_esta_nas_pecas_fica_por_confirmar(self):
        # 23853: «caudais nominais 1200 m3/h», e a tabela diz 1540
        lido = ("Caudal máximo de insuflação [m3/h] 1540" + self.NL +
                "Perfil Recursos Horas Estimadas" + self.NL + "Business analyst  4 1920"
                + self.NL + "[pág. 7]" + self.NL + "experiência mínima de dois anos, 1 2 meses"
                + self.NL + "Cláusula 41.ª" + self.NL + "1.200.000,00 € ; 99,72%")
        f = lambda linha: radar.numeros_por_confirmar(linha, lido)
        marcada = f("- caudais nominais 1200 m3/h (pág. 4)")
        self.assertIn("[confirmar: o número 1200 não está nas páginas lidas]", marcada)
        # o que o PDF parte, os milhares, o extenso, a página citada, o
        # número da lista e os nomes com algarismos não são invenção
        for linha in ("- Business analyst: 4 recursos, 1920 horas (pág. 7)",
                      "Experiência: 2 anos; prazo 12 meses (Programa, pág. 7)",
                      "- 1 200 000 €; 99,72 %; 1.200.000,00 €", "12. DEUCP",
                      "- Cláusula 41.2: filtros ePM1, m3/h"):
            self.assertEqual(f(linha), linha, linha)
        self.assertEqual(f(marcada), marcada)            # não se marca duas vezes

    def test_as_clausulas_tipo_saem_do_objecto(self):
        # 21659 e 21764 (licenças): «Cumprir a legislação», «Assegurar o sigilo»
        objecto = self.NL.join(["- 72 licenças Nokia SR (pág. 2)",
                                "- Cumprir a legislação aplicável",
                                "- Assegurar o sigilo", "- Comunicar à ESPAP quaisquer alterações"])
        self.assertEqual(radar.sem_clausulas_tipo(objecto), "- 72 licenças Nokia SR (pág. 2)")
        # só delas, fica como veio: a leitura falhou, e isso vê-se
        self.assertEqual(radar.sem_clausulas_tipo("- Assegurar o sigilo"), "- Assegurar o sigilo")

    def test_o_local_do_anuncio_quando_a_leitura_nao_o_tem(self):
        texto = self.NL.join(["9 - LOCAL DA EXECUÇÃO DO CONTRATO",
                              "LOCAL DA EXECUÇÃO DO CONTRATO (PROCEDIMENTO)",
                              "País: Portugal", "Localidade: Presa", "Distrito: Santarém",
                              "Concelho: Sardoal", "Freguesia: Freguesia de Alcaravela",
                              "País: Portugal", "Localidade: Freguesia de Candemil - Amarante",
                              "Distrito: Porto", "Concelho: Amarante",
                              "Freguesia: Freguesia de Candemil - Amarante"])
        seccoes = radar.seccoes_do_texto(texto)
        self.assertEqual(radar.local_do_anuncio(seccoes),
                         "Presa, Freguesia de Alcaravela, Sardoal, Santarém; "
                         "Freguesia de Candemil - Amarante, Porto")
        analise = {"objecto": "- x", "equipa": "- y", "documentos_proposta": "1. z",
                   "preco_anormalmente_baixo": "não consta", "localizacao": "não consta",
                   "fontes": "CE.pdf", "modelo": "m"}
        anuncio = {"titulo": "Obra", "entidade": "Município", "preco_base": "",
                   "prazo": "2026-10-07", "data_pub": "2026-09-20", "cpv": "45000000",
                   "ref": "1/2026"}
        linha = next(l for l in radar.essencial_do_anuncio(anuncio, seccoes, analise)
                     if l[0] == "Local de prestação de serviços")
        self.assertIn("Freguesia de Alcaravela", linha[1])
        self.assertIn("segundo o anúncio", linha[3])

    def test_o_rotulo_da_pergunta_nao_e_o_nome_do_perfil(self):
        # 21568, 21713, 21724
        perfis = radar.perfis_da_equipa(
            "Nome do perfil tal e qual está no documento: Gestor de Projeto (pág. 4)"
            + self.NL + "Quantidade: 1 (pág. 4)" + self.NL + "Formação: — ")
        self.assertEqual(perfis[0]["nome"], "Gestor de Projeto (pág. 4)")
        self.assertEqual(perfis[0]["pessoas"], "1")

    # --- B. as perguntas -------------------------------------------------

    def test_a_pergunta_da_equipa_separa_o_que_pontua_e_nao_junta_o_ou(self):
        # 20445 e 21631 (escalões lidos como requisitos), 21568 (o «ou»),
        # 21296 (as linhas repetidas), 21724 (a secção à parte), 22458 e
        # 23486 (o bloco do conjunto sem frase que o sustente)
        i = " ".join(radar.INSTRUCOES_EQUIPA.split())
        for pedaco in ("(pontua)", "\"ou\" fica \"ou\"", "linhas iguais repetidas",
                       "«6.3.", "SÓ quando uma frase das peças o diz"):
            self.assertIn(pedaco, i)
        self.assertNotIn("entram sempre nesse bloco", i)

    def test_a_pergunta_da_proposta_segue_o_artigo(self):
        # 21296, 21924: a «habilitação dos terceiros» e a certidão
        # permanente saíam, por terem «habilitação» no nome
        i = " ".join(radar.INSTRUCOES_PROPOSTA.split())
        self.assertIn("habilitação dos terceiros", i)
        self.assertIn("DEPOIS da adjudicação", i)
        self.assertIn("50%", i)                            # o limiar com a base (22102)

    def test_as_clausulas_tipo_em_todas_as_familias(self):
        self.assertIn("de bens ou de licenças", " ".join(radar.INSTRUCOES_OBJECTO.split()))
        self.assertIn("outros trabalhos", " ".join(radar.INSTRUCOES_OBJECTO_OBRAS.split()))

    # --- C. a cadeia -----------------------------------------------------

    def test_a_reserva_da_groq_vem_no_fim(self):
        # foi o único modelo que errou números (23389, 23265)
        self.assertEqual([f[0] for f in radar.FORNECEDORES][-1], "groq-reserva")


class TestQuartaRondaDaLeitura(unittest.TestCase):
    """30/09/2026: quatro perfis julgaram as 76 leituras relidas com a
    terceira ronda. A página que o modelo escreve estava certa em 76 a
    85 % das linhas -- o erro típico é a página ao lado, numa lista que
    passa a quebra --, e a conferência dos números tinha marcas falsas e
    um buraco. A página e a conferência passaram a ser do código: cada
    teste é um caso desse dia."""

    NL = chr(10)

    def confere(self, linha, lido):
        return radar.numeros_por_confirmar(linha, lido)

    # --- a conferência dos números -------------------------------------

    def test_a_pagina_com_o_hifen_nao_separavel_nao_e_numero(self):
        # 21925: «(pág. 40\u201141)» com U+2011, onze marcas falsas
        lido = "[pág. 40]" + self.NL + "Formação e garantia."
        for linha in ("- Formação (pág. 40\u201141)", "- Formação (pág. 40—41)",
                      "- Garantia (pág. 4; pág. 6)",
                      "- Formação (1_275CP26_Caderno_de_Encargos.zip/1.1.1 - "
                      "PC260622.03.A05 - Anexo_ Clausulas tecnicas.docx - "
                      "PC260622.03.A05.pdf, pág. 1)"):
            self.assertEqual(self.confere(linha, lido), linha, linha)

    def test_o_espaco_estreito_separa_os_milhares(self):
        # 21568: «18\u202f000 subscritores», e a peça diz «18.000»
        lido = "conta existente com mais de 18.000 subscritores"
        for sep in (" ", "\u00a0", "\u202f", "\u2009"):
            linha = "- Mailchimp com mais de 18%s000 subscritores (pág. 20)" % sep
            self.assertEqual(self.confere(linha, lido), linha, repr(sep))

    def test_as_horas_numa_forma_so(self):
        # 23174: «09:00\u201118:00», e a peça diz «das 09.00h às 18.00h»
        lido = "horário de atendimento: dias úteis, das 09.00h às 18.00h"
        for linha in ("Prioridade Urgente: horário 2ª\u20116ª 09:00\u201118:00 (pág. 21)",
                      "Horário: 9h00 às 18h00", "Horário: 9:00 às 18.00h"):
            self.assertEqual(self.confere(linha, lido), linha, linha)
        # e uma hora que a peça não diz continua a marcar
        self.assertIn("confirmar", self.confere("Horário: 08:30 às 18:00", lido))

    def test_a_linha_da_tabela_nao_se_comprime_num_numero(self):
        # 21764: «1 I0041 Licenças UN 1,00 120.000,00 120.000,00» dava
        # «10012000000120000», sem apoio
        linha = "1 I0041 Licenças UN 1,00 120.000,00 120.000,00 (Lista.pdf)"
        lido = "Item Código Designação Un Qtd Preço" + self.NL + \
            "1 I0041 Licenças UN 1,00 120.000,00 120.000,00"
        self.assertEqual(self.confere(linha, lido), linha)

    def test_o_numero_de_varios_grupos_confere_se_inteiro(self):
        # 23010: «7\u202f000 km/ano», e o OCR tinha o «7» e o «000» soltos,
        # noutros sítios -- um número errado dado por certo
        lido = ("Lote 2 – Machico / Santana, 7 viaturas" + self.NL +
                "código postal 9200-000" + self.NL + "13 dias; 520 horas; 219 camas")
        for linha in ("Lote 2 – 7\u202f000 km/ano (pág. 26)",
                      "Lote 4 – 13\u202f520,00\u202f€", "Lote 1 – 219\u202f000,00\u202f€"):
            self.assertIn("confirmar", self.confere(linha, lido), linha)
        # e numa tabela, os milhares seguidos do número da coluna ao lado
        # são o número: o mapa de quantidades da 23010 (OCR) e o despacho
        # da 21618
        lido = ("L Funchal I Câmara de Lobos 83 000 219 L20,O0 €" + self.NL +
                "2 Machico / Santana 7s 000 198 000,00 €" + self.NL +
                "Despacho n.º 15 247/2004")
        for linha in ("Funchal – 83\u202f000\u202fkm/ano (pág. 26)", "Santana – 198\u202f000,00\u202f€",
                      "4. Taxas (conforme o Despacho n.º 15\u202f247/2004)"):
            self.assertEqual(self.confere(linha, lido), linha, linha)
        self.assertIn("7000", self.confere("Lote 2 – 7\u202f000\u202fkm/ano", lido))

    def test_os_anos_em_meses_continuam_a_marcar(self):
        # 22631: a peça diz «3 anos» e a leitura «36 meses» -- a regra é
        # copiar das peças, e a conta não se faz por ela
        self.assertIn("confirmar", self.confere("Garantia: 36 meses (pág. 21)",
                                                "garantia de 3 anos"))

    # --- a página posta pelo código -------------------------------------

    def recorte(self, *pecas):
        """«### nome» e, por página, «[pág. N]», como o recorte as põe."""
        partes = []
        for nome, paginas in pecas:
            corpo = self.NL.join(("[pág. %d]" % n + self.NL + tx) if n else tx
                                 for n, tx in paginas)
            partes.append("### %s%s%s" % (nome, self.NL, corpo))
        return (self.NL * 2).join(partes)

    ROTINA = "Texto de rotina sobre as penalidades contratuais aplicáveis. "

    def test_a_pagina_e_a_de_onde_a_linha_esta(self):
        # a página ao lado: 20445, 21924, 23780 (a do director de obra)
        lido = self.recorte(("CE.pdf", [
            (5, self.ROTINA * 3),
            (6, "O adjudicatário deve assegurar a manutenção preventiva dos "
                "equipamentos instalados." + self.NL + self.ROTINA)]))
        self.assertEqual(
            radar.paginas_pelo_codigo(
                "- Assegurar a manutenção preventiva dos equipamentos (pág. 8)", lido),
            "- Assegurar a manutenção preventiva dos equipamentos (pág. 6)")
        # a linha sem página, que a tem no texto, ganha-a (as de continuação)
        self.assertEqual(
            radar.paginas_pelo_codigo("Manutenção preventiva dos equipamentos instalados",
                                      lido),
            "Manutenção preventiva dos equipamentos instalados (pág. 6)")

    def test_a_lista_que_passa_a_quebra_leva_o_intervalo(self):
        # as alíneas a)–d) do 20445, citadas na 8 e que estão na 7-8
        lido = self.recorte(("CE.pdf", [
            (7, self.ROTINA + self.NL + "a) Relatório mensal de actividade; b) Plano de"),
            (8, "trabalhos detalhado e cronograma de execução;" + self.NL + self.ROTINA)]))
        self.assertEqual(
            radar.paginas_pelo_codigo(
                "- Plano de trabalhos detalhado e cronograma de execução (pág. 8)", lido),
            "- Plano de trabalhos detalhado e cronograma de execução (pág. 7–8)")

    def test_com_mais_de_uma_peca_diz_qual(self):
        lido = self.recorte(
            ("Programa_do_Procedimento.pdf", [(3, "A proposta é constituída pelo DEUCP.")]),
            ("Caderno_de_Encargos.pdf", [(9, "Local de execução: Rua da Holanda, n.º 1, "
                                            "em Lisboa.")]))
        self.assertEqual(
            radar.paginas_pelo_codigo("Local: Rua da Holanda, n.º 1, em Lisboa (pág. 3)", lido),
            "Local: Rua da Holanda, n.º 1, em Lisboa (Caderno de Encargos, pág. 9)")

    def test_a_linha_que_nao_se_acha_fica_so_com_uma_pagina_enviada(self):
        # 23780: citava a 41, e o recorte eram as 14 e 42-43; 22036 idem
        lido = self.recorte(("CE.pdf", [(14, self.ROTINA), (42, self.ROTINA)]))
        resumo = "- Director de obra com experiência em obras de natureza similar"
        self.assertEqual(radar.paginas_pelo_codigo(resumo + " (pág. 42)", lido),
                         resumo + " (pág. 42)")
        self.assertEqual(radar.paginas_pelo_codigo(resumo + " (pág. 41)", lido), resumo)
        self.assertEqual(radar.paginas_pelo_codigo(resumo + " (pág. 42\u201143)", lido), resumo)

    def test_sem_marcas_nao_ha_pagina(self):
        # 14680 e 23853: os .docx não têm páginas, e a «pág. 1» era inventada
        lido = self.recorte(("CE.docx", [(None, "O objecto é a manutenção dos "
                                                "elevadores do edifício sede.")]))
        for linha in ("- Manutenção dos elevadores do edifício sede (pág. 1)",
                      "- Outra coisa que se resumiu (pág. 1)"):
            self.assertEqual(radar.paginas_pelo_codigo(linha, lido),
                             linha.replace(" (pág. 1)", ""))

    def test_o_que_nao_consta_nao_tem_pagina(self):
        # 21877: «… não consta (pág. 23)»; uma ausência não tem página
        lido = self.recorte(("CE.pdf", [(23, self.ROTINA)]))
        valor = self.NL.join(["Garantia: não consta (pág. 23)", "Formação: — (pág. 23)", "",
                              "não consta"])
        self.assertEqual(radar.paginas_pelo_codigo(valor, lido),
                         self.NL.join(["Garantia: não consta", "Formação: —", "",
                                       "não consta"]))


class TestHabilitacaoECaucaoDoAnuncio(unittest.TestCase):
    """O alvará e a caução estão no anúncio do DR (§12 e §14), e faltavam
    em todas as fichas das obras (28/09/2026, a validação das leituras)."""

    def seccoes(self, habilitacao, caucao):
        return [("12", "DOCUMENTOS DE HABILITAÇÃO", habilitacao),
                ("14", "PRESTAÇÃO DE CAUÇÃO", caucao)]

    def test_o_alvara_com_a_categoria(self):
        s = self.seccoes(
            [("Habilitação para o exercício da atividade profissional", "Sim"),
             ("Tipo", "Alvará"),
             ("Descrição", "1.ª Subcategoria da 2.ª Categoria, classe 4")],
            [("Prestação de caução", "Não")])
        self.assertEqual(radar.habilitacao_do_anuncio(s),
                         "Alvará — 1.ª Subcategoria da 2.ª Categoria, classe 4")
        self.assertEqual(radar.caucao_do_anuncio(s), "Não")

    def test_a_caucao_com_a_percentagem(self):
        s = self.seccoes(
            [("Habilitação para o exercício da atividade profissional", "Não")],
            [("Prestação de caução", "Sim"), ("Percentagem", "5%"),
             ("Descrição da Garantia Exigida", "garantia bancária")])
        self.assertEqual(radar.habilitacao_do_anuncio(s), "Não exigida no anúncio")
        self.assertEqual(radar.caucao_do_anuncio(s), "Sim, 5% — garantia bancária")

    def test_sem_as_seccoes_fica_vazio(self):
        # vazio, e nao «Nao»: o anuncio nao disse nada, e a ficha diz isso
        self.assertEqual(radar.habilitacao_do_anuncio([]), "")
        self.assertEqual(radar.caucao_do_anuncio([]), "")


class TestLimpaCampo(unittest.TestCase):

    def test_desfaz_o_escape_a_dobrar(self):
        # o modelo escreve "\\n" no JSON e o json.loads so desfaz uma
        # camada, pelo que o "\n" aparecia a letra no meio do texto
        self.assertEqual(radar.limpa_campo("- um\\n- dois"),
                         "- um" + chr(10) + "- dois")

    def test_tira_espacos_e_colapsa_as_linhas_em_branco(self):
        # a linha em branco passou a valer: separa os blocos por perfil
        # da equipa. Continua a colapsar as seguidas e a limpar as
        # pontas -- era isso que este teste protegia, e continua a
        # proteger
        self.assertEqual(radar.limpa_campo("  a  \\n\\n  b "),
                         "a" + chr(10) + chr(10) + "b")
        self.assertEqual(radar.limpa_campo("a\\n\\n\\n\\nb"),
                         "a" + chr(10) + chr(10) + "b")
        self.assertEqual(radar.limpa_campo("\\n\\n a \\n\\n"), "a")

    def test_aguenta_vazio(self):
        self.assertEqual(radar.limpa_campo(None), "")


class TestCadeiaDeFornecedores(unittest.TestCase):
    """Quem entra na cadeia de reserva, e por que ordem.

    Um fornecedor sem chave configurada custava uma volta e um 401 a
    cada uma das três perguntas de cada concurso da fila — o contrário
    do que a cadeia existe para fazer.
    """

    FALSOS = (
        ("groq", "https://groq/x", "modelo-groq", ("g.txt",), "G_KEY", {}),
        ("openrouter", "https://or/x", "modelo-or", ("o.txt",), "O_KEY", {}),
        ("nvidia", "https://nv/x", "modelo-nv", ("n.txt",), "N_KEY",
         {"reasoning_effort": "low"}),
    )

    def setUp(self):
        self.enterContext(unittest.mock.patch.object(
            radar, "FORNECEDORES", self.FALSOS))
        # com_chaves() troca o ler_chave dentro do teste; o patch so
        # garante que volta ao verdadeiro no fim
        self.enterContext(unittest.mock.patch.object(
            radar, "ler_chave", radar.ler_chave))

    def com_chaves(self, *quais):
        radar.ler_chave = lambda nomes, var: ("k" if nomes[0][0] in quais
                                              else "")

    def test_so_entra_quem_tem_chave(self):
        self.com_chaves("g", "n")
        self.assertEqual([f[0] for f in radar.cadeia_de_fornecedores({})],
                         ["groq", "nvidia"])

    def test_a_ordem_e_a_da_lista(self):
        # a Groq à frente por ser a única com leituras julgadas boas
        self.com_chaves("o", "g")
        self.assertEqual([f[0] for f in radar.cadeia_de_fornecedores({})],
                         ["groq", "openrouter"])

    def test_sem_chave_nenhuma_a_cadeia_e_vazia(self):
        # é o que faz o analisar_pecas dizer "falta a chave da API"
        self.com_chaves()
        self.assertEqual(radar.cadeia_de_fornecedores({}), [])

    def test_fornecedor_pecas_prende_a_um_so(self):
        # serve para comparar leituras entre modelos sem mexer no código
        self.com_chaves("g", "o", "n")
        cadeia = radar.cadeia_de_fornecedores({"fornecedor_pecas": "openrouter"})
        self.assertEqual([f[0] for f in cadeia], ["openrouter"])

    def test_os_extras_viajam_com_o_fornecedor(self):
        # o reasoning_effort do NVIDIA vale 3,5s em vez de 168s, e é só
        # dele: um parâmetro a mais dava 400 noutro e tirava-o da cadeia
        self.com_chaves("n")
        self.assertEqual(radar.cadeia_de_fornecedores({})[0][4],
                         {"reasoning_effort": "low"})


class TestModeloDoFornecedor(unittest.TestCase):
    """O "modelo_pecas" do config antigo é da Groq, e só dela.

    Aplicado à cadeia toda, escolhia o modelo do fornecedor errado: um
    "openai/gpt-oss-120b" no config passava a pedir esse nome ao
    OpenRouter, onde não existe.
    """

    def test_sem_config_fica_o_de_origem(self):
        self.assertEqual(
            radar.modelo_do_fornecedor({}, "openrouter", "origem"), "origem")

    def test_o_config_antigo_so_vale_para_a_groq(self):
        cfg = {"modelo_pecas": "outro"}
        self.assertEqual(radar.modelo_do_fornecedor(cfg, "groq", "origem"),
                         "outro")
        self.assertEqual(radar.modelo_do_fornecedor(cfg, "nvidia", "origem"),
                         "origem")

    def test_o_mapa_por_fornecedor_manda(self):
        cfg = {"modelo_pecas": "antigo", "modelos_pecas": {"groq": "novo"}}
        self.assertEqual(radar.modelo_do_fornecedor(cfg, "groq", "origem"),
                         "novo")

    def test_valores_vazios_nao_contam(self):
        # um "" no config não é uma escolha -- é o campo por preencher
        cfg = {"modelo_pecas": "  ", "modelos_pecas": {"groq": ""}}
        self.assertEqual(radar.modelo_do_fornecedor(cfg, "groq", "origem"),
                         "origem")


class TestOrcamentoPorFornecedor(unittest.TestCase):
    """O tecto do dia é de cada fornecedor, não da cadeia."""

    def setUp(self):
        radar._ESGOTADOS.clear()

    tearDown = setUp

    def test_esgotado_e_por_dia(self):
        # à meia-noite a data muda e a memória limpa-se sozinha
        radar.marcar_esgotado("groq", "2026-08-27")
        self.assertTrue(radar.esta_esgotado("groq", "2026-08-27"))
        self.assertFalse(radar.esta_esgotado("groq", "2026-08-28"))

    def test_um_esgotado_nao_esgota_a_cadeia(self):
        # com "algum", bastava a Groq acabar para o painel dar o dia por
        # perdido com o NVIDIA ainda a responder ao lado
        cadeia = [("groq", "u", "m", "k", {}), ("nvidia", "u", "m", "k", {})]
        radar.marcar_esgotado("groq")
        self.assertFalse(radar.cadeia_esgotada(cadeia))

    def test_todos_esgotados_esgotam_a_cadeia(self):
        cadeia = [("groq", "u", "m", "k", {}), ("nvidia", "u", "m", "k", {})]
        radar.marcar_esgotado("groq")
        radar.marcar_esgotado("nvidia")
        self.assertTrue(radar.cadeia_esgotada(cadeia))

    def test_cadeia_vazia_nao_esta_esgotada(self):
        # sem chaves a mensagem certa é "falta a chave", não "acabou o dia"
        self.assertFalse(radar.cadeia_esgotada([]))


class TestJsonDaResposta(unittest.TestCase):
    """Os modelos gratuitos embrulham o JSON em cercas markdown.

    A Groq honra o response_format; os outros nem sempre. Sem desfazer
    a cerca, a cadeia descia para o fornecedor seguinte com a resposta
    boa na mão.
    """

    def test_json_simples(self):
        self.assertEqual(radar.json_da_resposta('{"a": 1}'), {"a": 1})

    def test_dentro_de_cerca_com_linguagem(self):
        self.assertEqual(
            radar.json_da_resposta('```json' + chr(10) + '{"a": 1}' +
                                   chr(10) + '```'), {"a": 1})

    def test_dentro_de_cerca_sem_linguagem(self):
        self.assertEqual(
            radar.json_da_resposta('```' + chr(10) + '{"a": 1}' +
                                   chr(10) + '```'), {"a": 1})

    def test_lixo_continua_a_ser_erro(self):
        # tem de continuar a falhar: é o ValueError que faz a cadeia
        # descer para o fornecedor seguinte
        with self.assertRaises(ValueError):
            radar.json_da_resposta("desculpe, não percebi")


class TestPerguntarDesceACadeia(unittest.TestCase):
    """A cadeia salta para o seguinte quando um fornecedor esgota.

    Era este o ponto: o tecto diário da Groq acabava a meio de uma
    releitura do acervo e a fila ficava parada até ao dia seguinte.
    """

    def setUp(self):
        radar._ESGOTADOS.clear()
        self.addCleanup(radar._ESGOTADOS.clear)
        # responder() troca o _um_pedido dentro do teste; o patch so
        # garante que volta ao verdadeiro no fim
        self.enterContext(unittest.mock.patch.object(
            radar, "_um_pedido", radar._um_pedido))
        self.chamados = []

    def responder(self, respostas):
        """respostas: {nome do modelo: (dados, aviso)}."""
        def falso(url, chave, modelo, instrucao, texto, extras=None):
            self.chamados.append(modelo)
            self.extras = extras
            return respostas.get(modelo, (None, "sem resposta"))
        radar._um_pedido = falso

    CADEIA = [("groq", "u", "m-groq", "k", {}),
              ("nvidia", "u", "m-nv", "k", {"reasoning_effort": "low"})]

    def test_o_primeiro_que_responde_ganha(self):
        self.responder({"m-groq": ({"objecto": "x"}, "")})
        dados, aviso, usado = radar._perguntar(self.CADEIA, "i", "t")
        self.assertEqual(dados, {"objecto": "x"})
        self.assertEqual(usado, "groq:m-groq")
        self.assertEqual(self.chamados, ["m-groq"])

    def test_esgotado_o_primeiro_desce_para_o_segundo(self):
        self.responder({"m-groq": (None, radar.SEM_ORCAMENTO_HOJE),
                        "m-nv": ({"objecto": "y"}, "")})
        dados, aviso, usado = radar._perguntar(self.CADEIA, "i", "t")
        self.assertEqual(dados, {"objecto": "y"})
        self.assertEqual(usado, "nvidia:m-nv")

    def test_o_tecto_do_dia_fica_marcado_e_nao_se_repete(self):
        # sem esta memória, cada uma das três perguntas de cada concurso
        # voltava a bater na mesma porta fechada -- a hora deitada fora
        # que o SEM_ORCAMENTO_HOJE veio evitar
        self.responder({"m-groq": (None, radar.SEM_ORCAMENTO_HOJE),
                        "m-nv": ({"objecto": "y"}, "")})
        radar._perguntar(self.CADEIA, "i", "t")
        radar._perguntar(self.CADEIA, "i", "t")
        self.assertTrue(radar.esta_esgotado("groq"))
        self.assertEqual(self.chamados.count("m-groq"), 1)

    def test_uma_falha_normal_nao_marca_esgotado(self):
        # um 500 passageiro não pode encerrar o fornecedor até amanhã
        self.responder({"m-groq": (None, "respondeu 500: ..."),
                        "m-nv": ({"objecto": "y"}, "")})
        radar._perguntar(self.CADEIA, "i", "t")
        self.assertFalse(radar.esta_esgotado("groq"))

    def test_falhando_todos_o_aviso_diz_quem_falhou(self):
        self.responder({})
        dados, aviso, usado = radar._perguntar(self.CADEIA, "i", "t")
        self.assertIsNone(dados)
        self.assertEqual(usado, "")
        self.assertIn("groq", aviso)
        self.assertIn("nvidia", aviso)


