class TestOsBotoesDaPlataformaNaFicha(BaseTemporaria):
    """29/09/2026, ele: na Vortal os dois botões («Abrir na Vortal» e
    «Peças na plataforma») davam no mesmo sítio, e na acingov o das
    peças descarregava um ZIP sem o dizer. No mesmo dia, a seguir: o das
    peças «só deve estar ao pé das peças», senão as pessoas começam por
    ali e não vão às peças do Mira Gov -- e descarregar de lá também as
    traz para o concurso."""

    ZIP = ("https://www.acingov.pt/acingovprod/2/zonaPublica/"
           "zona_publica_c/donwloadProcedurePiece/MTEzMTQxOA")

    def setUp(self):
        super().setUp()
        self.cliente = radar.app.test_client()
        self.pedidos = []
        self.enterContext(unittest.mock.patch.object(
            radar, "pedir_documentos", self.pedidos.append))

    def _ficha(self, plat, link, docs_estado=None):
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, entidade, data_pub,"
                      " prazo, estado, detalhe_lido, texto, url, plataforma,"
                      " link_pecas, docs_estado) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
                      ("70/2026", "Software", "IPL", "2026-09-01",
                       "2099-12-30", "novo", 1, "1 - Objecto",
                       "https://exemplo/70", plat, link, docs_estado))
        return self.cliente.get("/anuncio/70%2F2026").get_data(as_text=True)

    def test_o_das_pecas_nao_esta_no_topo_esta_no_bloco_das_pecas(self):
        h = self._ficha("acingov", self.ZIP)
        topo, _, resto = h.partition("id='pecas'")
        self.assertNotIn("Descarregar da plataforma", topo)
        self.assertNotIn("donwloadProcedurePiece", h)
        self.assertIn("Descarregar da plataforma (ZIP)", resto)
        self.assertIn("action='/pecas-da-plataforma/70/2026'", resto)

    def test_com_as_pecas_ca_nao_ha_botao_para_a_plataforma(self):
        with radar.liga() as c:
            c.execute("INSERT INTO documentos (ref,nome) VALUES "
                      "('70/2026','CE.pdf')")
        h = self._ficha("acingov", self.ZIP, docs_estado="ok")
        self.assertNotIn("/pecas-da-plataforma/", h)
        self.assertIn("Descarregar todas (ZIP", h)

    def test_descarregar_da_plataforma_traz_as_pecas_para_o_concurso(self):
        self._ficha("acingov", self.ZIP)
        r = self.cliente.post("/pecas-da-plataforma/70/2026")
        self.assertEqual(r.status_code, 302)
        self.assertEqual(r.headers["Location"], self.ZIP)
        self.assertEqual(self.pedidos, ["70/2026"])

    def test_sem_link_nao_sai_para_lado_nenhum(self):
        self._ficha("acingov", "")
        r = self.cliente.post("/pecas-da-plataforma/70/2026")
        self.assertIn("/anuncio/", r.headers["Location"])
        self.assertEqual(self.pedidos, [])

    def test_consulta_preliminar_da_vortal_tem_um_botao_so(self):
        # 29/09/2026: o anúncio de fonte='vortal' JÁ é a página do
        # procedimento, e «Ver na Vortal» e «Abrir na Vortal» davam no
        # mesmo sítio
        pagina = ("https://community.vortal.biz/Public/"
                  "contract-notice-view/PT1.NTC.9/")
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, entidade, data_pub,"
                      " prazo, estado, detalhe_lido, texto, url, plataforma,"
                      " link_pecas, fonte) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
                      ("PT1.NTC.9", "Consulta", "IPL", "2026-09-01",
                       "2099-12-30", "novo", 1, "1 - Objecto", pagina,
                       "vortal", pagina, "vortal"))
        h = self.cliente.get("/anuncio/PT1.NTC.9").get_data(as_text=True)
        self.assertIn("Ver na Vortal", h)
        self.assertNotIn("Abrir na Vortal", h)

    def test_vortal_tem_um_botao_so(self):
        h = self._ficha("vortal", "https://community.vortal.biz/Public/"
                                  "public-tender-documents/AbC")
        self.assertIn("Abrir na Vortal", h)
        self.assertNotIn("Peças na plataforma", h)
        self.assertNotIn("public-tender-documents/AbC", h)

    def test_acingov_abre_o_procedimento(self):
        h = self._ficha("acingov", self.ZIP)
        self.assertIn(html.escape(radar.ACINGOV_PROCEDIMENTO % "1131418",
                                  quote=True), h)


class TestInteresse(unittest.TestCase):
    """O interesse limita a lista de anúncios e NÃO entra em condicoes().

    O motor serve também os alertas e os filtros guardados: um recorte
    lá dentro fazia um alerta deixar de ver, em silêncio, o que vê hoje.
    """

    def test_desligado_nao_recorta(self):
        frag, vals = radar.condicao_do_interesse(
            args={}, cfg={"interesse_activo": False,
                          "interesse_cpv": "72000000"})
        self.assertEqual((frag, vals), ("", []))

    def test_ligado_sem_cpv_nao_esvazia_o_ecra(self):
        # ligado e por definir: um ecrã em branco lê-se como avaria
        frag, _ = radar.condicao_do_interesse(
            args={}, cfg={"interesse_activo": True, "interesse_cpv": ""})
        self.assertEqual(frag, "")

    def test_ligado_recorta_pelo_cpv(self):
        frag, vals = radar.condicao_do_interesse(
            args={}, cfg={"interesse_activo": True,
                          "interesse_cpv": "72000000"})
        self.assertIn("cpv LIKE ?", frag)
        self.assertEqual(vals, ["72%", "%, 72%"])

    def test_o_que_se_tira_entra_como_NOT(self):
        frag, vals = radar.condicao_do_interesse(
            args={}, cfg={"interesse_activo": True,
                          "interesse_cpv": "72000000",
                          "interesse_cpv_excl": "72212000"})
        self.assertIn("NOT (", frag)
        # o COALESCE não é decorativo: um anúncio ainda sem CPV lido não
        # é "CPV 72212", e o NOT (NULL LIKE x) é NULL
        self.assertIn("COALESCE(cpv,'')", frag)
        self.assertEqual(vals, ["72%", "%, 72%", "72212%", "%, 72212%"])

    def test_interesse_nao_na_url_levanta_o_recorte(self):
        frag, _ = radar.condicao_do_interesse(
            args={"interesse": "nao"},
            cfg={"interesse_activo": True, "interesse_cpv": "72000000"})
        self.assertEqual(frag, "")

    def test_o_motor_dos_filtros_nao_sabe_do_interesse(self):
        # a guarda que interessa: condicoes() serve os alertas
        onde, _ = radar.condicoes({"estado": ""})
        self.assertNotIn("cpv LIKE", onde)
        self.assertNotIn("interesse", onde)


class TestRecorteDaLista(unittest.TestCase):
    """A aba e o interesse são UM recorte só.

    Aplicado em quatro consultas da mesma página (lista, contagem de
    cada aba, selector das plataformas, total do filtro): um número que
    conte com outro recorte abre uma lista diferente da que promete.
    """

    def _com(self, cfg):
        antigo = radar.ler_config
        radar.ler_config = lambda: dict(radar.CONFIG_INICIAL, **cfg)
        try:
            with radar.app.test_request_context("/?estado=porver"):
                return radar.recorte_da_lista("submetido")
        finally:
            radar.ler_config = antigo

    def test_sem_interesse_e_so_a_aba(self):
        frag, vals = self._com({"interesse_activo": False})
        self.assertIn("EXISTS", frag)
        self.assertEqual(vals, ["submetido"])

    def test_com_interesse_junta_os_dois_com_E(self):
        frag, vals = self._com({"interesse_activo": True,
                                "interesse_cpv": "72000000"})
        self.assertIn("EXISTS", frag)
        self.assertIn("cpv LIKE ?", frag)
        self.assertIn(") AND (", frag)
        # a ordem dos valores tem de seguir a dos ? -- aba primeiro
        self.assertEqual(vals, ["submetido", "72%", "%, 72%"])


class TestMotivoDoAbandono(unittest.TestCase):
    """Abandonar sem dizer porquê deixa a aba dos abandonados inútil.

    Decisão do Afonso a 01/09/2026: âmbito fechado. O `required` do
    selector é conveniência do browser -- a guarda é no servidor.
    """

    def setUp(self):
        self.cliente = radar.app.test_client()

    def test_sem_motivo_o_servidor_recusa(self):
        r = self.cliente.post("/estado/1%2F2026/descartado", data={})
        self.assertEqual(r.status_code, 302)
        self.assertIn("aviso=", r.headers["Location"])
        self.assertIn("motivo", r.headers["Location"])

    def test_motivo_inventado_tambem_e_recusado(self):
        r = self.cliente.post("/estado/1%2F2026/descartado",
                              data={"motivo": "porque sim"})
        self.assertIn("aviso=", r.headers["Location"])

    def test_o_botao_nao_pergunta_nada_na_linha(self):
        # Decisão do Afonso a 01/09/2026: o motivo é pop-up e não um
        # selector ao lado do botão -- vinte linhas na lista eram vinte
        # perguntas antes de alguém as fazer.
        html_ = radar.forma_abandonar("1/2026", titulo="Um anúncio")
        self.assertNotIn("<select", html_)
        self.assertNotIn("<option", html_)
        self.assertIn("abandonar-js", html_)
        self.assertIn("action='/estado/1%2F2026/nao_fomos'", html_)
        self.assertIn("Um anúncio", html_)

    def test_sem_JS_o_pedido_segue_e_o_servidor_e_que_recusa(self):
        # o botão continua a ser submit de um <form> que faz POST: sem
        # JS o pedido segue e a recusa explica-se, em vez de o botão
        # ficar morto
        html_ = radar.forma_abandonar("1/2026")
        self.assertIn("<form", html_)
        self.assertIn("method='post'", html_)
        self.assertIn("type='submit'", html_)

    def test_a_caixa_traz_os_motivos_todos_e_nenhum_por_omissao(self):
        html_ = radar.caixa_do_motivo()
        for m in radar.MOTIVOS_ABANDONO:
            # escapado, que e como chega ao browser: "CV's" leva
            # apostrofo e o atributo e delimitado por ele
            self.assertIn(html.escape(m), html_)
        # nenhum vem escolhido e o campo é required: não se abandona a
        # carregar duas vezes sem olhar. Só a marcação -- o `checked` do
        # JS é o que LIMPA a escolha anterior, e um `assertNotIn` sobre
        # o texto todo apanhava-o e acusava o contrário do que se quer.
        marcacao = html_.split("<script")[0]
        self.assertNotIn("checked", marcacao)
        self.assertIn("<dialog", marcacao)
        # Os motivos são BOTÕES que gravam desde 26/09/2026 (D1-bis): um
        # clique, e não rádio mais «Gravar». O grupo escondido tem os
        # botões desligados (o JS), senão o Enter num campo gravava o
        # primeiro motivo do OUTRO estado. Quem recusa sem motivo
        # continua a ser o servidor -- teste próprio em
        # TestSelectorDaRanhura.
        self.assertIn("<button type='submit' name='motivo' value='%s'"
                      % html.escape(radar.MOTIVOS_ABANDONO[0], quote=True), marcacao)
        self.assertNotIn("type='radio'", marcacao)
        self.assertIn("b.disabled = !meu", html_)
        # e o «Gravar» esconde-se quando há motivos: são eles que gravam
        self.assertIn("dlg-motivo-gravar').hidden = comMotivo", html_)
        self.assertIn("data-para='perdido'", marcacao)
        self.assertIn("data-para='nao_fomos'", marcacao)

    def test_interessa_continua_a_nao_pedir_motivo(self):
        # a exigência é só de quem abandona
        self.assertNotIn("motivo", radar.accao("/estado/1/interessa", "x"))


class TestContrasteNosFundosReais(unittest.TestCase):
    """`--papel` não é o pior fundo.

    A regra da empresa dizia que os --t* passavam AA sobre --papel, "que é
    o pior fundo". As colunas do quadro são --linha2, mais escuro, e os
    três «pede o preço proposto» de 01/09/2026 estavam a 4,35:1 (medido
    na UX-Auditoria.md de 02/09/2026). O teste calcula os contrastes a
    partir do próprio CSS, para a próxima cor nova não passar sem ser
    medida.
    """

    # Desde 24/09/2026 (as pontes sairam com a fase 3) mede-se a paleta
    # que PINTA, a dos tokens do sistema, nos tres temas. As medidas de
    # antes liam as paletas antigas do `CSS` e do `CSS_NOVO`, que desde
    # 21/09 ja nao chegavam ao ecra: os tokens ganhavam-lhes.
    TEMAS = {":root, [data-theme=\"claro\"]": 4.5,
             "[data-theme=\"escuro\"]": 4.5,
             "[data-theme=\"contraste\"]": 7.0}
    TINTAS = ("--ink", "--ink-secondary", "--ink-muted", "--brand",
              "--success", "--warning", "--danger", "--seal")
    FUNDOS = ("--surface", "--surface-raised", "--surface-sunken")

    @staticmethod
    def _contraste(a, b):
        def lum(h):
            r, g, b_ = (int(h[i:i + 2], 16) / 255 for i in (1, 3, 5))
            f = lambda v: v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4
            return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b_)
        la, lb = lum(a), lum(b)
        return (max(la, lb) + 0.05) / (min(la, lb) + 0.05)

    def _temas(self):
        folha = radar.ler_estilo("miragov-tokens.css")
        temas = {}
        for sel, corpo in re.findall(r"([^{}]+)\{([^}]*)\}", folha):
            cores = dict(re.findall(r"(--[a-z-]+):(#[0-9a-fA-F]{6})", corpo))
            if "--ink" in cores:
                temas[sel.strip()] = cores
        return temas

    def _regra(self, selector):
        m = re.search(re.escape(selector) + r"\{([^}]*)\}", radar.CSS)
        self.assertIsNotNone(m, selector)
        return m.group(1)

    def test_o_pede_da_coluna_saiu_com_a_coluna(self):
        """A coluna do quadro saiu a 15/09/2026, e o `.coluna-pede` com
        ela. O que a regra guardava -- um texto de 10,5 px tem de passar
        AA sobre o fundo em que vive -- continua nas outras regras desta
        classe."""
        self.assertNotIn(".coluna-pede", radar.CSS)

    def test_toda_a_tinta_passa_sobre_todos_os_fundos_nos_tres_temas(self):
        """O `--papel` não era o pior fundo (a lição de 02/09/2026), e
        por isso mede-se sobre os TRÊS: a superfície, a levantada e a
        rebaixada, mais o fundo suave da própria cor (uma etiqueta
        `--warning` sobre `--warning-soft`). AA (4,5:1) no claro e no
        escuro, AAA (7:1) no contraste."""
        temas = self._temas()
        self.assertEqual(sorted(temas), sorted(self.TEMAS))
        for tema, minimo in self.TEMAS.items():
            cores = temas[tema]
            for tinta in self.TINTAS:
                fundos = self.FUNDOS + ((tinta + "-soft",)
                                        if tinta + "-soft" in cores else ())
                for fundo in fundos:
                    c = self._contraste(cores[tinta], cores[fundo])
                    self.assertGreaterEqual(
                        c, minimo, "%s sobre %s no tema %s dá %.2f"
                        % (tinta, fundo, tema, c))

    def test_as_iniciais_da_barra_leem_se_nos_tres_temas(self):
        """Varredura de 25/09/2026: o `.mg-topbar .mg-avatar` do sistema
        pinta as iniciais com `--surface-header` sobre o `--seal`: 1,38:1
        no claro. A nossa folha repõe o `--on-brand`, e é esse par que
        tem de passar — nos três temas, que o amarelo do escuro pede tinta
        escura e o castanho do claro pede branca."""
        folha = radar.ler_estilo("miragov-radar.css")
        self.assertIn(".mg-topbar .mg-avatar{color:var(--on-brand)}", folha)
        for tema, minimo in self.TEMAS.items():
            cores = self._temas()[tema]
            c = self._contraste(cores["--on-brand"], cores["--seal"])
            self.assertGreaterEqual(c, 4.5, "no tema %s dá %.2f" % (tema, c))


