class TestTrincoEntreProcessos(BaseTemporaria):
    """O P0 de 8/09/2026: às 17:00 o temporizador do systemd (um processo
    `--uma-vez`) e o relógio de dentro do painel correram os dois, sobre
    a mesma base, porque a guarda era um dicionário na memória de um só
    processo. O trinco passou a viver na tabela `estado`, com pid e hora.
    A condição («o outro está vivo e dentro do prazo») é injectável,
    para não depender de arrancar processos a sério."""

    def test_o_segundo_processo_desiste_enquanto_o_primeiro_vive(self):
        agora = datetime.datetime(2026, 9, 8, 17, 0, 0)
        tomou, _ = radar.tomar_trinco(agora=agora, pid=111, vivo=lambda p: True)
        self.assertTrue(tomou)
        tomou, porque = radar.tomar_trinco(agora=agora + datetime.timedelta(seconds=37),
                                           pid=222, vivo=lambda p: True)
        self.assertFalse(tomou)
        self.assertIn("pid 111", porque)
        self.assertIn("17:00", porque)
        # o dono volta a tomar o seu sem se bloquear a si proprio
        self.assertTrue(radar.tomar_trinco(agora=agora, pid=111, vivo=lambda p: True)[0])

    def test_um_trinco_de_processo_morto_ou_velho_nao_prende(self):
        agora = datetime.datetime(2026, 9, 8, 17, 0, 0)
        radar.tomar_trinco(agora=agora, pid=111, vivo=lambda p: True)
        # morto: o pid ja nao existe
        self.assertTrue(radar.tomar_trinco(agora=agora, pid=222,
                                           vivo=lambda p: False)[0])
        # velho: vivo mas ha mais de HORAS_DE_TRINCO (um processo preso)
        radar.tomar_trinco(agora=agora, pid=111, vivo=lambda p: True)
        tarde = agora + datetime.timedelta(hours=radar.HORAS_DE_TRINCO, minutes=1)
        self.assertTrue(radar.tomar_trinco(agora=tarde, pid=333,
                                           vivo=lambda p: True)[0])

    def test_so_o_dono_larga(self):
        agora = datetime.datetime(2026, 9, 8, 17, 0, 0)
        radar.tomar_trinco(agora=agora, pid=111, vivo=lambda p: True)
        radar.largar_trinco(pid=222)
        self.assertFalse(radar.tomar_trinco(agora=agora, pid=222,
                                            vivo=lambda p: True)[0])
        radar.largar_trinco(pid=111)
        self.assertTrue(radar.tomar_trinco(agora=agora, pid=222,
                                           vivo=lambda p: True)[0])
        radar.largar_trinco(pid=222)

    def test_o_painel_diz_que_e_noutro_processo(self):
        agora = datetime.datetime(2026, 9, 8, 17, 0, 0)
        self.assertEqual(radar.verificacao_noutro_processo(agora=agora), "")
        radar.tomar_trinco(agora=agora, pid=os.getpid() + 100000, vivo=lambda p: True)
        self.assertEqual(radar.verificacao_noutro_processo(
            agora=agora + datetime.timedelta(minutes=2), vivo=lambda p: True), "17:00")
        # o meu proprio trinco nao e "outro processo"
        radar.tomar_trinco(agora=agora, vivo=lambda p: True)
        self.assertEqual(radar.verificacao_noutro_processo(agora=agora), "")
        radar.largar_trinco()

    def test_comecar_verificacao_toma_e_larga_o_trinco(self):
        # a condicao verdadeira contra o recurso verdadeiro, uma vez: o
        # relogio do painel com o trinco de "outro processo" na base
        agora = datetime.datetime.now()
        radar.tomar_trinco(agora=agora, pid=os.getpid() + 100000, vivo=lambda p: True)
        antigo = radar.processo_vivo
        radar.processo_vivo = lambda p: True
        try:
            arrancou, porque = radar.comecar_verificacao()
            self.assertFalse(arrancou)
            self.assertIn("noutro processo", porque)
            self.assertFalse(radar._VERIFICACAO["a_correr"])
            self.assertIn("noutro processo", radar.verificacao_a_correr())
        finally:
            radar.processo_vivo = antigo
            radar.largar_trinco(pid=os.getpid() + 100000)

    def test_um_pid_que_nao_existe_esta_morto(self):
        self.assertTrue(radar.processo_vivo(os.getpid()))
        self.assertFalse(radar.processo_vivo(2 ** 22 - 1))



class TestVigilanciaDasPecas(BaseTemporaria):
    """03/09/2026: o reler_marcados() vigia o prazo e o preço base na
    página do DR, mas um esclarecimento ou uma errata não passam pelo DR —
    aparecem na lista de documentos da plataforma, e só se dava por eles
    abrindo a plataforma à mão.

    Os erros que estes testes travam, todos com custo real:

    - vigiar pela via do obter_documentos(), que apaga as linhas do
      anúncio: levava atrás o texto já extraído e os veredictos do OCR, e
      mandava as ~7 s por página de cada digitalização outra vez;
    - avisar a mesma peça a cada verificação — duas vezes por dia, para
      sempre — quando ela não se conseguiu trazer;
    - tomar uma lista vazia por «as peças desapareceram», que é a
      plataforma em baixo e não uma novidade (a mesma regra do
      diferencas_do_detalhe(): só se avisa o que tem valor dos dois lados);
    - contar o «Anúncio DR.pdf», que é o radar que o acrescenta e a
      plataforma não tem, como peça nova a cada volta."""

    def _anuncio(self, ref="30/2026", **campos):
        """Um anúncio JÁ na escada, que é o que a vigilância olha. Desde
        15/09/2026 isso é ter uma proposta e não `estado='interessa'`;
        passar `estado='novo'` deixa-o de fora, como antes."""
        valores = {"estado": "interessa", "docs_estado": "ok",
                   "link_pecas": "https://www.acingov.pt/x/donwloadProcedurePiece/A",
                   "plataforma": "acingov", "url": "https://x/anuncio-procedimento/k-30",
                   # com texto: senao a ficha vai ao DR reler o detalhe
                   # e escreve por cima do link das pecas
                   "texto": "Anúncio de procedimento", "detalhe_lido": 1,
                   "data_pub": datetime.date.today().isoformat(),
                   "prazo": (datetime.date.today() + datetime.timedelta(days=10)).isoformat(),
                   "titulo": "Aquisição de serviços", "entidade": "Câmara"}
        valores.update(campos)
        na_escada = valores.pop("estado") == "interessa"
        valores["estado"] = "novo"
        colunas = ",".join(valores)
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref,%s) VALUES (?%s)"
                      % (colunas, ",?" * len(valores)),
                      [ref] + list(valores.values()))
        if na_escada:
            radar.criar_proposta(ref)
        return ref

    def _peca(self, ref, nome, texto="texto da peça", estado="ok"):
        with radar.liga() as c:
            c.execute("INSERT INTO documentos (ref,nome,ficheiro,tamanho,"
                      "origem,obtido_em,texto,texto_estado)"
                      " VALUES (?,?,?,?,?,?,?,?)",
                      (ref, nome, nome, 10, "acingov", "2026-09-01 09:00",
                       texto, estado))

    def _disponiveis(self, *nomes):
        """A lista que a plataforma daria: o conteúdo só chega se pedido.

        Os bytes de propósito não são um PDF: assim o extrair_textos()
        diz «não é PDF» e cala-se, em vez de o pypdf gritar por um EOF
        que não existe — um teste que imprime avisos ensina a ignorá-los.
        """
        return [(n, (lambda n=n: b"conteudo de " + n.encode()))
                for n in nomes]

    def _alteracoes(self, ref):
        with radar.liga() as c:
            return [(r["campo"], r["depois"]) for r in c.execute(
                "SELECT campo, depois FROM alteracoes WHERE ref=?", (ref,))]

    def _docs(self, ref):
        with radar.liga() as c:
            return {r["nome"]: (r["texto_estado"], r["texto"]) for r in c.execute(
                "SELECT nome, texto_estado, texto FROM documentos WHERE ref=?",
                (ref,))}

    def test_peca_nova_avisa_e_nao_mexe_nas_que_ja_ca_estavam(self):
        ref = self._anuncio()
        self._peca(ref, "Caderno de Encargos.pdf", "texto por OCR", "ocr")
        self._peca(ref, "Anúncio DR.pdf")
        quantas = radar._guardar_pecas_novas(
            ref, "acingov",
            self._disponiveis("Caderno de Encargos.pdf", "Esclarecimento 1.pdf"))
        self.assertEqual(quantas, 1)
        self.assertEqual(self._alteracoes(ref),
                         [(radar.CAMPO_PECA_NOVA, "Esclarecimento 1.pdf")])
        docs = self._docs(ref)
        # o veredicto do OCR e o texto dele sobrevivem — que é
        # exactamente o que a via do obter_documentos() não faria
        self.assertEqual(docs["Caderno de Encargos.pdf"], ("ocr", "texto por OCR"))
        self.assertIn("Esclarecimento 1.pdf", docs)
        with radar.liga() as c:
            h = c.execute("SELECT detalhe FROM eventos WHERE ref=?",
                          (ref,)).fetchall()
        self.assertTrue(any("Esclarecimento 1.pdf" in x["detalhe"] for x in h), h)

    def test_a_segunda_volta_nao_volta_a_avisar(self):
        ref = self._anuncio()
        self._peca(ref, "Caderno de Encargos.pdf")
        pecas = self._disponiveis("Caderno de Encargos.pdf", "Errata.pdf")
        self.assertEqual(radar._guardar_pecas_novas(ref, "acingov", pecas), 1)
        self.assertEqual(radar._guardar_pecas_novas(ref, "acingov", pecas), 0)
        self.assertEqual(len(self._alteracoes(ref)), 1)

    def test_peca_que_nao_se_consegue_trazer_avisa_uma_vez_so(self):
        # ficheiro acima do tecto: o buscar() devolve None. Avisar é
        # preciso — ela existe; repetir o aviso duas vezes por dia para
        # sempre é que não.
        ref = self._anuncio()
        pecas = [("Anexo enorme.zip", lambda: None)]
        self.assertEqual(radar._guardar_pecas_novas(ref, "acingov", pecas), 1)
        self.assertEqual(self._alteracoes(ref),
                         [(radar.CAMPO_PECA_NOVA, "Anexo enorme.zip")])
        self.assertEqual(self._docs(ref), {})
        self.assertEqual(radar._guardar_pecas_novas(ref, "acingov", pecas), 0)

    def test_o_anuncio_dr_nao_conta_como_peca_nova(self):
        ref = self._anuncio()
        self.assertEqual(radar._guardar_pecas_novas(
            ref, "acingov", self._disponiveis("Anúncio DR.pdf")), 0)
        self.assertEqual(self._alteracoes(ref), [])

    def test_lista_vazia_nao_e_novidade_nem_desaparecimento(self):
        ref = self._anuncio()
        self._peca(ref, "Caderno de Encargos.pdf")
        antigo = radar.pecas_disponiveis
        radar.pecas_disponiveis = lambda sessao, link: ([], "")
        try:
            novas, aviso = radar.vigiar_pecas()
        finally:
            radar.pecas_disponiveis = antigo
        self.assertEqual((novas, aviso), (0, ""))
        self.assertEqual(self._alteracoes(ref), [])
        self.assertEqual(list(self._docs(ref)), ["Caderno de Encargos.pdf"])

    def test_so_os_marcados_com_prazo_aberto_pecas_trazidas_e_uma_razao(self):
        ontem = (datetime.date.today() - datetime.timedelta(days=1)).isoformat()
        # todos publicados ha 20 dias com prazo a 10: a data de
        # esclarecimentos (primeiro terco, 10 dias) ja passou
        pub = (datetime.date.today() - datetime.timedelta(days=20)).isoformat()
        self._anuncio("31/2026", estado="novo", data_pub=pub)           # por ver
        self._anuncio("32/2026", prazo=ontem, data_pub=pub)             # prazo fechado
        self._anuncio("33/2026", docs_estado="", data_pub=pub)          # sem base de comparação
        self._anuncio("34/2026", link_pecas="", data_pub=pub)           # sem link
        self._anuncio("35/2026", data_pub=pub)                          # só este conta
        self._anuncio("36/2026", data_pub=pub,                          # ja visto depois
                      pecas_vigiadas_em=datetime.date.today().isoformat() + " 09:00")
        escolhidos = radar.anuncios_a_vigiar()
        self.assertEqual([a["ref"] for a, _ in escolhidos], ["35/2026"])
        self.assertIn("esclarecimentos", escolhidos[0][1])
        vistos = []
        antigo = radar.pecas_disponiveis

        def espia(sessao, link):
            vistos.append(link)
            return [], ""
        radar.pecas_disponiveis = espia
        try:
            radar.vigiar_pecas()
        finally:
            radar.pecas_disponiveis = antigo
        self.assertEqual(len(vistos), 1, vistos)

    def test_a_razao_e_a_data_de_esclarecimentos_ou_uma_alteracao(self):
        hoje = datetime.date(2026, 9, 14)
        a = {"ref": "40/2026", "data_pub": "2026-09-01", "prazo": "2026-09-30",
             "pecas_vigiadas_em": ""}
        nunca = lambda ref, desde: False
        # esclarecimentos a 10/09 (primeiro terco de 29 dias): passou
        self.assertIn("esclarecimentos", radar.razao_para_vigiar(a, hoje, nunca))
        # ainda nao passou: sem razao
        self.assertEqual(radar.razao_para_vigiar(a, datetime.date(2026, 9, 5), nunca), "")
        # ja se olhou depois da data: sem razao
        visto = dict(a, pecas_vigiadas_em="2026-09-12 09:00")
        self.assertEqual(radar.razao_para_vigiar(visto, hoje, nunca), "")
        # mas uma alteracao desde entao volta a dar razao
        self.assertIn("mudaram", radar.razao_para_vigiar(
            visto, hoje, lambda ref, desde: desde == "2026-09-12 09:00"))
        # olhou-se no proprio dia da data: conta como antes dela
        no_dia = dict(a, pecas_vigiadas_em="2026-09-10 17:00")
        self.assertIn("esclarecimentos", radar.razao_para_vigiar(no_dia, hoje, nunca))
        # sem datas nao ha regra do primeiro terco
        self.assertEqual(radar.razao_para_vigiar(dict(a, prazo=""), hoje, nunca), "")

    def test_uma_alteracao_do_prazo_manda_ver_as_pecas(self):
        ref = self._anuncio(data_pub=datetime.date.today().isoformat())
        self.assertEqual(radar.anuncios_a_vigiar(), [])
        with radar.liga() as c:
            c.execute("UPDATE anuncios SET pecas_vigiadas_em='2026-09-01 09:00' WHERE ref=?",
                      (ref,))
        radar.registar_alteracoes(ref, [("prazo", "2026-09-20", "2026-09-30")])
        escolhidos = radar.anuncios_a_vigiar()
        self.assertEqual([a["ref"] for a, _ in escolhidos], [ref])
        self.assertIn("mudaram", escolhidos[0][1])

    def test_vigiar_um_anuncio_marca_quando_a_plataforma_responde(self):
        ref = self._anuncio()
        self._peca(ref, "Caderno de Encargos.pdf")
        with radar.liga() as c:
            a = c.execute("SELECT * FROM anuncios WHERE ref=?", (ref,)).fetchone()
        antigo = radar.pecas_disponiveis
        try:
            radar.pecas_disponiveis = lambda s, l: ([], "")     # a plataforma falhou
            self.assertEqual(radar.vigiar_anuncio(a)[0], 0)
            with radar.liga() as c:
                self.assertIsNone(c.execute("SELECT pecas_vigiadas_em FROM anuncios "
                                            "WHERE ref=?", (ref,)).fetchone()[0])
            radar.pecas_disponiveis = lambda s, l: (
                self._disponiveis("Caderno de Encargos.pdf", "Errata.pdf"), "")
            self.assertEqual(radar.vigiar_anuncio(a), (1, ""))
            with radar.liga() as c:
                self.assertTrue(c.execute("SELECT pecas_vigiadas_em FROM anuncios "
                                          "WHERE ref=?", (ref,)).fetchone()[0])
        finally:
            radar.pecas_disponiveis = antigo

    def test_com_peca_nova_rele_se_pelo_modelo_e_sem_ela_nao(self):
        ref = self._anuncio()
        self._peca(ref, "Caderno de Encargos.pdf")
        with radar.liga() as c:
            a = c.execute("SELECT * FROM anuncios WHERE ref=?", (ref,)).fetchone()
        relidos = []
        antigo = radar.pecas_disponiveis
        try:
            radar.pecas_disponiveis = lambda s, l: (
                self._disponiveis("Caderno de Encargos.pdf"), "")
            radar.vigiar_anuncio(a, reler=relidos.append)
            self.assertEqual(relidos, [])
            radar.pecas_disponiveis = lambda s, l: (
                self._disponiveis("Caderno de Encargos.pdf", "CE revisto.pdf"), "")
            radar.vigiar_anuncio(a, reler=relidos.append)
            self.assertEqual(relidos, [ref])
        finally:
            radar.pecas_disponiveis = antigo

    def test_a_verificacao_rele_em_linha_e_o_botao_pela_fila(self):
        # no --uma-vez a fila e uma thread daemon que morre com o
        # processo: a verificacao tem de ler em linha
        ref = self._anuncio()
        self._peca(ref, "Caderno de Encargos.pdf")
        lidos, na_fila = [], []
        antigos = (radar.pecas_disponiveis, radar.ler_pecas_e_registar,
                   radar.pedir_analise)
        try:
            radar.pecas_disponiveis = lambda s, l: (
                self._disponiveis("Caderno de Encargos.pdf", "Errata.pdf"), "")
            radar.ler_pecas_e_registar = lambda r, quem="": lidos.append((r, quem))
            radar.pedir_analise = lambda r, quem="": na_fila.append((r, quem))
            with radar.liga() as c:
                c.execute("UPDATE anuncios SET pecas_vigiadas_em='2026-09-01 09:00' "
                          "WHERE ref=?", (ref,))
            radar.registar_alteracoes(ref, [("prazo", "2026-09-20", "2026-09-30")])
            self.assertEqual(radar.vigiar_pecas()[0], 1)
            self.assertEqual(lidos, [(ref, "plataforma")])
            self.assertEqual(na_fila, [])
            radar.pecas_disponiveis = lambda s, l: (
                self._disponiveis("Caderno de Encargos.pdf", "Errata.pdf",
                                  "Esclarecimento 3.pdf"), "")
            r = radar.app.test_client().post("/pecas-novas/" + ref)
            self.assertIn("A reler pelo modelo", unquote_plus(r.headers["Location"]))
            self.assertEqual(len(na_fila), 1)
            self.assertEqual(na_fila[0][0], ref)
        finally:
            (radar.pecas_disponiveis, radar.ler_pecas_e_registar,
             radar.pedir_analise) = antigos

    def test_o_botao_da_ficha_diz_o_que_encontrou(self):
        ref = self._anuncio()
        self._peca(ref, "Caderno de Encargos.pdf")
        cliente = radar.app.test_client()
        html_ = cliente.get("/anuncio/" + ref).get_data(as_text=True)
        self.assertIn("Verificar peças novas", html_)
        self.assertIn("action='/pecas-novas/%s'" % ref, html_)
        antigo = radar.pecas_disponiveis
        try:
            radar.pecas_disponiveis = lambda s, l: (
                self._disponiveis("Caderno de Encargos.pdf", "Esclarecimento 2.pdf"), "")
            r = cliente.post("/pecas-novas/" + ref)
            self.assertIn("1 peça nova: Esclarecimento 2.pdf", unquote_plus(r.headers["Location"]))
            r = cliente.post("/pecas-novas/" + ref)
            self.assertIn("Nenhuma peça nova", unquote_plus(r.headers["Location"]))
            radar.pecas_disponiveis = lambda s, l: ([], "o ZIP das peças não veio")
            r = cliente.post("/pecas-novas/" + ref)
            self.assertIn("o ZIP das peças não veio", unquote_plus(r.headers["Location"]))
        finally:
            radar.pecas_disponiveis = antigo
        # sem pecas trazidas nao ha com que comparar
        outro = self._anuncio("50/2026", docs_estado="")
        r = cliente.post("/pecas-novas/" + outro)
        self.assertIn("Traz primeiro", unquote_plus(r.headers["Location"]))

    def test_o_aviso_da_peca_nova_le_se_no_resumo_e_no_html(self):
        # o `antes` é vazio: sem caso próprio saía " -> Errata 2.pdf"
        linha = {"ref": "30/2026", "campo": radar.CAMPO_PECA_NOVA, "antes": "",
                 "depois": "Errata 2.pdf", "titulo": "Aquisição de serviços",
                 "entidade": "Câmara", "id": 1}
        texto = radar.texto_do_resumo([], [linha])
        htm = radar.html_do_resumo([], [linha])
        self.assertIn("peça nova na plataforma: Errata 2.pdf", texto)
        self.assertIn("peça nova na plataforma: <b>Errata 2.pdf</b>", htm)
        self.assertNotIn("-> Errata 2.pdf", texto)



class TestNomeRadarGov(unittest.TestCase):
    """14/09/2026: «a aplicação diz RadarDR mas tem de dizer RadarGov e
    Gov tem de ser a azul». O nome esta em dois sitios (a barra e o ecra
    de entrar) e o azul da barra e um claro proprio: o --azul da paleta
    sobre a barra escura dava 2,3:1."""

    def test_o_nome_e_radargov_nos_dois_sitios_e_o_gov_e_azul(self):
        # o logotipo ganhou a classe do estado aceso e o title a
        # 16/09/2026, quando passou a ser o caminho para o Hoje
        # O nome passou ao LOCKUP do sistema de desenho na fase 2
        # (21/09/2026): «Radar G⬤v», com o disco da bandeira no lugar do
        # ó. O que este teste guarda continua a ser o mesmo -- o nome é
        # «Radar Gov» nos três moldes, o «Gov» distingue-se do «Radar»,
        # e em lado nenhum volta a dizer «RadarDR».
        # Desde 24/09/2026 o lockup é o do Mira Gov: o olho, «Mira» e
        # «Gov».
        marca = radar.logotipo(inverso=True)
        self.assertIn("mg-logo__mira", marca)
        self.assertIn("Mira", marca)
        self.assertIn("mg-logo__gov", marca)
        self.assertIn("mg-logo__eye", marca)           # o olho à frente
        self.assertIn("aria-label='Mira Gov'", marca)  # e lê-se assim
        self.assertIn('class="mg-topbar__brand" href="/"', radar.BASE)
        for molde in (radar.PAGINA_ENTRAR, radar.PAGINA_ERRO):
            self.assertIn("{{ logo }}", molde)
            self.assertIn("Mira Gov", molde)           # no <title>
        self.assertNotIn("Radar<span>DR", radar.BASE + radar.PAGINA_ENTRAR)
        # Desde 24/09/2026 o produto chama-se Mira Gov: o nome antigo
        # não fica em nenhum <title> nem nos textos do site
        for molde in (radar.BASE, radar.PAGINA_ENTRAR, radar.PAGINA_ERRO):
            self.assertNotIn("RadarGov", molde)
            self.assertNotIn("Radar de Concursos", molde)
        for pagina in ("index", "termos", "privacidade"):
            with open(os.path.join(radar.BASE_DIR, "site", pagina + ".html"),
                      encoding="utf-8") as f:
                self.assertNotIn("Radar Gov", f.read())
        # o «Gov» é a cor da marca, e o «Radar» a do texto -- é isso que
        # os distingue, e é o que a folha do sistema diz
        folha = radar.ler_estilo("miragov-componentes.css")
        self.assertIn(".mg-logo__gov{color:var(--brand)", folha)
        self.assertIn(".mg-logo__mira{color:var(--ink)", folha)
        # sobre a barra azul o olho e as duas palavras passam a branco
        self.assertIn("mg-logo--inverse", marca)


class TestAuditoriaDeSeguranca(BaseTemporaria):
    """A auditoria de 14/09/2026, a pedido do Afonso. O que ela apanhou e
    aqui se trava: nenhum cabeçalho de segurança; um pedido sem tecto de
    tamanho; as peças das plataformas servidas em linha fosse qual fosse
    o tipo (um .html corria no domínio do painel, com a sessão); o CSV
    a deixar passar fórmulas; redireccionamentos crus pelo Referer; e os
    ficheiros com segredos a 644/755."""

    def setUp(self):
        super().setUp()
        self.cliente = radar.app.test_client()

    def test_os_cabecalhos_vao_em_todas_as_respostas(self):
        for rota in ("/", "/entrar", "/quadro", "/configuracoes/conta"):
            with self.subTest(rota=rota):
                r = self.cliente.get(rota)
                self.assertEqual(r.headers["X-Content-Type-Options"], "nosniff")
                self.assertEqual(r.headers["X-Frame-Options"], "SAMEORIGIN")
                self.assertEqual(r.headers["Referrer-Policy"], "same-origin")
                csp = r.headers["Content-Security-Policy"]
                self.assertIn("frame-ancestors 'self'", csp)
                self.assertIn("form-action 'self'", csp)
                self.assertIn("object-src 'self'", csp)          # o <embed> das peças
                self.assertNotIn("https://", csp)    # nada de fora
                self.assertNotIn("Strict-Transport-Security", r.headers)   # http local
        r = self.cliente.get("/", base_url="https://localhost")
        self.assertIn("max-age=", r.headers.get("Strict-Transport-Security", ""))

    def test_um_pedido_tem_tecto(self):
        import io
        self.assertEqual(radar.app.config["MAX_CONTENT_LENGTH"], 20 * 1024 * 1024)
        r = self.cliente.post("/configuracoes/importar",
                              data={"ficheiro": (io.BytesIO(b"x" * (21 * 1024 * 1024)),
                                                 "modelo.xlsx")},
                              content_type="multipart/form-data")
        self.assertEqual(r.status_code, 413)

    def test_so_pdf_imagens_e_texto_abrem_no_browser(self):
        ref = "70/2026"
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, url, texto, detalhe_lido) "
                      "VALUES (?,?,?,?,1)", (ref, "t", "https://x/anuncio-procedimento/k", "x"))
        pasta = radar.pasta_do_anuncio(ref)
        os.makedirs(pasta)
        for nome, conteudo in (("ce.pdf", b"%PDF-1.4 x"), ("nota.txt", b"ola"),
                               ("Caderno de Encargos", b"%PDF-1.4 sem extensao"),
                               ("pagina.html", b"<script>alert(1)</script>"),
                               ("desenho.svg", b"<svg onload=alert(1)/>"),
                               ("macro.xlsm", b"PK")):
            with open(os.path.join(pasta, nome), "wb") as f:
                f.write(conteudo)
        for nome in ("ce.pdf", "nota.txt", "Caderno de Encargos"):
            r = self.cliente.get("/documento/%s/%s" % (quote(ref, safe=""), nome))
            self.assertEqual(r.status_code, 200)
            self.assertNotIn("attachment", r.headers.get("Content-Disposition", ""))
            self.assertNotEqual(r.headers.get("Content-Security-Policy"), "sandbox")
            self.assertNotEqual(r.mimetype, "application/octet-stream")
        r = self.cliente.get("/documento/%s/%s" % (quote(ref, safe=""), "Caderno de Encargos"))
        self.assertEqual(r.mimetype, "application/pdf")
        for nome in ("pagina.html", "desenho.svg", "macro.xlsm"):
            with self.subTest(nome=nome):
                r = self.cliente.get("/documento/%s/%s" % (quote(ref, safe=""), nome))
                self.assertEqual(r.status_code, 200)
                self.assertIn("attachment", r.headers["Content-Disposition"])
                self.assertEqual(r.mimetype, "application/octet-stream")
                self.assertEqual(r.headers["Content-Security-Policy"], "sandbox")
                self.assertEqual(r.headers["X-Content-Type-Options"], "nosniff")

    def test_o_csv_nao_deixa_passar_formulas(self):
        self.assertEqual(radar.celula_csv("=1+1"), "'=1+1")
        self.assertEqual(radar.celula_csv("+351"), "'+351")
        self.assertEqual(radar.celula_csv("-x"), "'-x")
        self.assertEqual(radar.celula_csv("@a"), "'@a")
        self.assertEqual(radar.celula_csv("Aquisição"), "Aquisição")
        self.assertEqual(radar.celula_csv(12.5), 12.5)
        self.assertEqual(radar.celula_csv(None), None)
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, entidade, url, data_pub, estado) "
                      "VALUES (?,?,?,?,?,?)",
                      ("71/2026", "=HYPERLINK(\"http://mau\")", "Câmara",
                       "https://x/anuncio-procedimento/k", "2026-09-01", "novo"))
        csv_ = self.cliente.get("/csv?estado=").get_data(as_text=True)
        self.assertIn("'=HYPERLINK", csv_)
        # e nao ha writerow a saltar a guarda
        self.assertEqual(radar_fonte().count("escritor.writerow("), 1)

    def test_o_referer_so_volta_para_esta_aplicacao(self):
        with radar.app.test_request_context("/", headers={"Referer": "https://mau.site/x"}):
            self.assertEqual(radar.volta_ao_referer("/quadro").headers["Location"], "/quadro")
        with radar.app.test_request_context("/", headers={"Referer": "http://localhost/lista?a=1"}):
            self.assertEqual(radar.volta_ao_referer("/quadro").headers["Location"], "/lista?a=1")
        with radar.app.test_request_context("/"):
            self.assertEqual(radar.volta_ao_referer("/quadro").headers["Location"], "/quadro")
        self.assertNotIn("redirect(request.referrer", radar_fonte())

    def test_os_ficheiros_com_segredos_ficam_so_do_dono(self):
        caminho = os.path.join(self.pasta, "segredo.txt")
        with open(caminho, "w") as f:
            f.write("x")
        os.chmod(caminho, 0o644)
        radar.so_o_dono(caminho)
        self.assertEqual(os.stat(caminho).st_mode & 0o777, 0o600)
        # a base fica assim ao ligar (uma vez por processo)
        radar._BASE_PROTEGIDA.discard(radar.DB)
        os.chmod(radar.DB, 0o644)
        with radar.liga() as c:
            c.execute("SELECT 1")
        self.assertEqual(os.stat(radar.DB).st_mode & 0o777, 0o600)


def radar_fonte():
    with open(radar.__file__, encoding="utf-8") as f:
        return f.read()


class TestInteresseNoMercado(BaseTemporaria):
    """14/09/2026: «no mercado, após definir o interesse, deve também só
    aparecer o CPV marcado, tal como nos anúncios». O recorte entra por
    filtros_dos_contratos() — a lista, o CSV e os gráficos filtram os
    três por lá — e nunca por condicoes_contratos(), que serve os
    alertas e a ficha da entidade."""

    def setUp(self):
        super().setUp()
        self.cfg = dict(radar.CONFIG_INICIAL, interesse_activo=True,
                        interesse_cpv="72000000", interesse_cpv_excl="")
        self.enterContext(unittest.mock.patch.object(
            radar, "ler_config", lambda: dict(self.cfg)))

    def test_prefixos_do_cpv_le_codigos_e_palavras(self):
        self.assertEqual(radar.prefixos_do_cpv("72000000|48700000"), ["72", "487"])
        self.assertEqual(radar.prefixos_do_cpv(""), [])
        self.assertEqual(radar.prefixos_do_cpv("72267100-0"), ["722671"])

    def test_a_condicao_usa_a_tabela_dos_cpv_e_o_nao_levanta(self):
        frag, vals = radar.condicao_do_interesse_contratos(args={}, cfg=self.cfg)
        self.assertIn("contrato_cpv", frag)
        self.assertIn("cpv8 GLOB ?", frag)
        self.assertEqual(vals, ["72*"])
        frag, vals = radar.condicao_do_interesse_contratos(
            args={}, cfg=dict(self.cfg, interesse_cpv_excl="72212000"))
        self.assertIn("NOT IN", frag)
        self.assertEqual(vals, ["72*", "72212*"])
        self.assertEqual(radar.condicao_do_interesse_contratos(
            args={"interesse": "nao"}, cfg=self.cfg), ("", []))
        self.assertEqual(radar.condicao_do_interesse_contratos(
            args={}, cfg=dict(self.cfg, interesse_activo=False)), ("", []))
        self.assertEqual(radar.condicao_do_interesse_contratos(
            args={}, cfg=dict(self.cfg, interesse_cpv="")), ("", []))

    def test_o_interesse_e_uma_pergunta(self):
        # 14/09/2026: «abre-se e nao se ve contrato nenhum» -- com
        # interesse definido o Mercado abre logo com os CPV da empresa
        from werkzeug.datastructures import MultiDict
        self.assertTrue(radar.pergunta_feita(MultiDict(), "contratos", self.cfg))
        self.assertTrue(radar.pergunta_feita(MultiDict({"ver": "fim"}), "renovacoes", self.cfg))
        # levantado, ou sem interesse, volta a ser preciso um filtro
        self.assertFalse(radar.pergunta_feita(MultiDict({"interesse": "nao"}), "contratos", self.cfg))
        self.assertFalse(radar.pergunta_feita(MultiDict(), "contratos",
                                              dict(self.cfg, interesse_activo=False)))
        self.assertTrue(radar.pergunta_feita(MultiDict({"q": "x"}), "contratos",
                                             dict(self.cfg, interesse_activo=False)))
        # o `op` sozinho nao e pergunta
        self.assertFalse(radar.pergunta_feita(MultiDict({"op": "ou"}), "contratos",
                                              dict(self.cfg, interesse_activo=False)))

    def test_entra_pelos_filtros_da_pagina_e_nao_pelo_motor(self):
        from werkzeug.datastructures import MultiDict
        args = MultiDict({"q": "software"})
        onde, vals = radar.filtros_dos_contratos(args, cfg=self.cfg)
        self.assertIn("contrato_cpv", onde)
        self.assertEqual(vals[-1], "72*")
        onde_livre, vals_livre = radar.filtros_dos_contratos(args, com_interesse=False,
                                                              cfg=self.cfg)
        self.assertNotIn("contrato_cpv", onde_livre)
        # o motor dos alertas e da ficha da entidade nao leva o interesse
        onde_motor, _ = radar.condicoes_contratos(args)
        self.assertNotIn("contrato_cpv", onde_motor)
        # e o ?interesse=nao levanta-o tambem aqui
        onde, _ = radar.filtros_dos_contratos(MultiDict({"q": "x", "interesse": "nao"}),
                                              cfg=self.cfg)
        self.assertNotIn("contrato_cpv", onde)


class TestPlataformasQueJaNaoExistem(BaseTemporaria):
    """14/09/2026: «as plataformas que hoje já não tens acesso é porque
    já não existem — juntamos todas como outras». Saphety, compraspublicas,
    gatewit, bizgov e construlink ficam na base, mas nos selectores são
    um balde só; o filtro por nome continua a aceitar qualquer uma."""

    def setUp(self):
        super().setUp()
        # sem o interesse do config.json verdadeiro: recortava a lista
        self.enterContext(unittest.mock.patch.object(
            radar, "ler_config", lambda: dict(radar.CONFIG_INICIAL)))

    def test_agrupa_as_mortas_e_deixa_as_activas_e_as_especiais(self):
        grupos = radar.agrupar_plataformas({
            "vortal": 50, "acingov": 40, "saphety": 9, "gatewit": 3,
            "anogov": 20, radar.SEM_PLATAFORMA: 7})
        self.assertEqual(grupos, [("vortal", 50), ("acingov", 40), ("anogov", 20),
                                  (radar.OUTRAS_PLATAFORMAS, 12),
                                  (radar.SEM_PLATAFORMA, 7)])
        # sem mortas nao ha balde
        self.assertEqual(radar.agrupar_plataformas({"vortal": 1}), [("vortal", 1)])
        self.assertEqual(radar.rotulo_da_plataforma(radar.OUTRAS_PLATAFORMAS),
                         "outras (já não existem)")
        for p in radar.PLATAFORMAS_ACTIVAS:
            self.assertIn(p, radar.PLATAFORMAS)

    def test_o_filtro_outras_apanha_o_que_nao_e_activo_nem_vazio(self):
        for ref, plat, lido in (("80/2026", "saphety", 1), ("81/2026", "vortal", 1),
                                ("82/2026", "", 1), ("83/2026", "gatewit", 1),
                                ("84/2026", "bizgov", 0)):
            with radar.liga() as c:
                c.execute("INSERT INTO anuncios (ref, titulo, url, plataforma, detalhe_lido,"
                          " estado, data_pub) VALUES (?,?,?,?,?,'novo','2026-09-01')",
                          (ref, "t", "https://x/anuncio-procedimento/" + ref, plat, lido))
        onde, vals = radar.condicoes({"plat": radar.OUTRAS_PLATAFORMAS, "estado": ""})
        with radar.liga() as c:
            refs = sorted(r["ref"] for r in c.execute("SELECT ref FROM anuncios" + onde, vals))
        self.assertEqual(refs, ["80/2026", "83/2026"])
        # e por nome continua a servir (um alerta antigo com plat=saphety)
        onde, vals = radar.condicoes({"plat": "saphety", "estado": ""})
        with radar.liga() as c:
            self.assertEqual([r["ref"] for r in c.execute("SELECT ref FROM anuncios" + onde, vals)],
                             ["80/2026"])
        # os dois selectores mostram "outras" e nao as mortas
        cliente = radar.app.test_client()
        lista = cliente.get(radar.LISTA + "?estado=").get_data(as_text=True)
        alertas = cliente.get("/configuracoes/alertas").get_data(as_text=True)
        for html_ in (lista, alertas):
            self.assertIn("value='(outras)'", html_)
            self.assertIn("outras (já não existem)", html_)
            self.assertNotIn("value='saphety'", html_)
            self.assertNotIn("value='gatewit'", html_)
            self.assertIn("value='vortal'", html_)
        self.assertIn("outras (já não existem) (2)", lista)


class TestFiltrosSimples(BaseTemporaria):
    """14/09/2026: «no campo de filtros dos anúncios só quero nome do
    anúncio ou objecto; entidade; filtro de plataformas, e data x a data
    y», a árvore de CPV por cima, e a entidade a sugerir-se enquanto se
    escreve («se estou a escrever SP… ele deve sugerir as SP»)."""

    def setUp(self):
        super().setUp()
        self.enterContext(unittest.mock.patch.object(
            radar, "ler_config", lambda: dict(radar.CONFIG_INICIAL)))
        with radar.liga() as c:
            for i, ent in enumerate(("SPMS — Serviços Partilhados do Ministério da Saúde",
                                     "SPMS — Serviços Partilhados do Ministério da Saúde",
                                     "Sociedade Portuguesa de Inovação", "Câmara Municipal de Espinho",
                                     "Hospital de Espinho")):
                c.execute("INSERT INTO anuncios (ref,titulo,url,entidade,entidade_norm,estado,"
                          "data_pub,detalhe_lido) VALUES (?,?,?,?,?,'novo','2026-09-01',1)",
                          ("9%d/2026" % i, "t", "https://x/anuncio-procedimento/%d" % i,
                           ent, radar.simplifica(ent)))

    def test_a_lista_tem_so_os_quatro_campos_e_a_arvore_em_cima(self):
        html_ = radar.app.test_client().get(radar.LISTA).get_data(as_text=True)
        # Desde 24/09/2026 (o `EcraConcursos`) os campos estão à vista e a
        # árvore dos CPV fica por baixo, recolhida
        self.assertLess(html_.index("class='mg-card filtros'"),
                        html_.index("details class='arvore'"))
        form = html_.split("class='mg-card filtros'")[1].split("</form>")[0]
        for campo in ("name='q'", "name='ent'", "name='plat'", "name='de'", "name='ate'"):
            self.assertIn(campo, form)
        for campo in ("name='q_excl'", "name='op'", "name='prazo'"):
            self.assertNotIn(campo, form)
        self.assertIn("type='hidden' id='filtro-cpv-excl'", form)
        # sem perfil o CPV é um botão de filtro (6/10/2026), com o campo
        # que a árvore enche dentro dele
        self.assertIn("id='filtro-cpv' name='cpv'", form)
        self.assertIn("data-abre-arvore", form)
        # o que vier pela URL passa escondido, para nao se perder
        html_ = radar.app.test_client().get(radar.LISTA + "?prazo=urgente&op=ou").get_data(as_text=True)
        self.assertIn("<input type='hidden' name='prazo' value='urgente'>", html_)
        self.assertIn("<input type='hidden' name='op' value='ou'>", html_)
        self.assertEqual(radar.campos_escondidos({"prazo": " "}, ("prazo",)), "")

    def test_as_entidades_sugerem_se_pelo_inicio_primeiro_e_agrupadas_por_nif(self):
        nomes = [e["nome"] for e in radar.sugestoes_de_entidade("sp")]
        self.assertEqual(nomes[0], "SPMS — Serviços Partilhados do Ministério da Saúde")
        self.assertIn("Hospital de Espinho", nomes)                  # "sp" no meio
        self.assertNotIn("Sociedade Portuguesa de Inovação", nomes)   # "s p" com espaco nao e "sp"
        self.assertEqual(radar.sugestoes_de_entidade("s"), [])         # menos de duas letras
        self.assertEqual(sorted(e["nome"] for e in radar.sugestoes_de_entidade("espinho")),
                         ["Câmara Municipal de Espinho", "Hospital de Espinho"])
        # sem acentos e sem maiusculas, como o filtro
        self.assertEqual(radar.sugestoes_de_entidade("SAÚDE")[0]["nome"],
                         "SPMS — Serviços Partilhados do Ministério da Saúde")
        # 14/09/2026: «as entidades nao estao agrupadas por NIF?» -- uma
        # linha por NIF, a grafia mais frequente, a soma de todas
        with radar.liga() as c:
            c.execute("UPDATE anuncios SET nif='509540716' WHERE entidade LIKE 'SPMS%'")
            for i, ent in enumerate(("Serviços Partilhados do Ministério da Saúde, EPE",
                                     "SPMS - Servicos Partilhados, E. P. E.")):
                c.execute("INSERT INTO anuncios (ref,titulo,url,entidade,entidade_norm,nif,"
                          "estado,data_pub,detalhe_lido) VALUES (?,?,?,?,?,?,'novo','2026-09-01',1)",
                          ("8%d/2026" % i, "t", "https://x/anuncio-procedimento/8%d" % i,
                           ent, radar.simplifica(ent), "509540716"))
        # e a mesma grafia sem NIF (a base veio assim em 24%) dobra-se no
        # grupo do NIF, em vez de sair uma segunda vez com o mesmo nome
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref,titulo,url,entidade,entidade_norm,nif,"
                      "estado,data_pub,detalhe_lido) VALUES (?,?,?,?,?,'','novo','2026-09-01',1)",
                      ("82/2026", "t", "https://x/anuncio-procedimento/82",
                       "SPMS — Serviços Partilhados do Ministério da Saúde",
                       radar.simplifica("SPMS — Serviços Partilhados do Ministério da Saúde")))
        sugeridas = radar.sugestoes_de_entidade("partilhados")
        spms = [e for e in sugeridas if e["nif"] == "509540716"]
        self.assertEqual(len(spms), 1)
        self.assertEqual(spms[0]["nome"], "SPMS — Serviços Partilhados do Ministério da Saúde")
        self.assertEqual(spms[0]["n"], 5)
        self.assertEqual(len([e for e in sugeridas if "SPMS" in e["nome"]]), 1)
        r = radar.app.test_client().get("/entidades.json?q=esp")
        self.assertEqual(r.mimetype, "application/json")
        self.assertEqual(sorted(e["nome"] for e in r.get_json()),
                         ["Câmara Municipal de Espinho", "Hospital de Espinho"])
        self.assertIn("data-sugere='anuncios'", radar.app.test_client().get(radar.LISTA).get_data(as_text=True))
        self.assertIn("/entidades.json", radar.ENTIDADES_JS)
        self.assertIn("dataset.chaveEm", radar.ENTIDADES_JS)

    def test_o_filtro_pelo_nif_apanha_todas_as_grafias_e_as_sem_nif(self):
        with radar.liga() as c:
            # a SPMS: duas com NIF, uma grafia sem NIF (24% da base veio assim)
            c.execute("UPDATE anuncios SET nif='509540716' WHERE ref='90/2026'")
            c.execute("INSERT INTO anuncios (ref,titulo,url,entidade,entidade_norm,nif,estado,"
                      "data_pub,detalhe_lido) VALUES (?,?,?,?,?,?,'novo','2026-09-01',1)",
                      ("85/2026", "t", "https://x/anuncio-procedimento/85",
                       "Serviços Partilhados do Ministério da Saúde, EPE",
                       radar.simplifica("Serviços Partilhados do Ministério da Saúde, EPE"),
                       "509540716"))
        onde, vals = radar.condicoes({"nif": "509540716", "ent": "SPMS — Serviços Partilhados",
                                      "estado": ""})
        with radar.liga() as c:
            refs = sorted(r["ref"] for r in c.execute("SELECT ref FROM anuncios" + onde, vals))
        # 90 e 85 pelo NIF; 91 tem a mesma grafia de 90 e nao tem NIF: entra
        self.assertEqual(refs, ["85/2026", "90/2026", "91/2026"])
        self.assertNotIn("entidade_norm LIKE", onde)     # o nome nao prende a uma grafia
        # sem NIF, o texto continua a filtrar como sempre
        onde, vals = radar.condicoes({"ent": "espinho", "estado": ""})
        self.assertIn("entidade_norm LIKE", onde)
        # e o NIF entra no resumo do filtro e nos formularios
        self.assertIn("NIF 509540716", radar.resumo_filtro("nif=509540716"))
        html_ = radar.app.test_client().get(radar.LISTA + "?nif=509540716").get_data(as_text=True)
        self.assertIn("<input type='hidden' name='nif' value='509540716'>", html_)
        html_ = radar.app.test_client().get("/configuracoes/alertas").get_data(as_text=True)
        self.assertIn("name='nif'", html_.split("action='/alertas/criar'")[1].split("</form>")[0])


class TestEntidadesNoMercado(BaseTemporaria):
    """14/09/2026: «nos contratos isto não está a aparecer, só aparece nos
    anúncios» — as sugestões de entidade também no Mercado, do corpus,
    e por chave (o NIF): escolhida a sugestão, a chave vai em
    entid/vencid e o texto deixa de prender a uma grafia. E o «excluir
    palavras» e o E/OU saem também do formulário dos contratos."""

    def setUp(self):
        super().setUp()
        self.enterContext(unittest.mock.patch.object(
            radar, "CORPUS", os.path.join(self.pasta, "contratos.db")))
        radar.iniciar_corpus()                      # o esquema do corpus, vazio
        with radar.liga_corpus() as c:
            # com as colunas nomeadas: um VALUES sem elas parte-se
            # quando a tabela ganha uma coluna, e foi o que aconteceu com
            # a `compra`/`ganha` do papel (16/09/2026)
            for chave, nome, variantes in (
                    ("509540716", "SPMS - Serviços Partilhados do Ministério "
                                  "da Saúde, E. P. E.", 15),
                    ("500000001", "Sport Lisboa e Benfica", 2),
                    ("500000002", "Hospital de Espinho", 1)):
                c.execute("INSERT INTO entidades (chave, nif, nome, variantes)"
                          " VALUES (?,?,?,?)", (chave, chave, nome, variantes))
            for norm, chave in (("spms", "509540716"),
                                ("servicos partilhados do ministerio da saude epe", "509540716"),
                                ("sport lisboa e benfica", "500000001"),
                                ("hospital de espinho", "500000002")):
                c.execute("INSERT INTO entidade_nomes VALUES (?,?)", (norm, chave))
        self.enterContext(unittest.mock.patch.object(radar, "ha_corpus", lambda: 1))

    def test_sugere_do_corpus_uma_por_chave_e_pelo_inicio_primeiro(self):
        nomes = radar.sugestoes_de_entidade_do_corpus("sp")
        self.assertEqual([e["nif"] for e in nomes][:1], ["509540716"])     # "spms" comeca por sp
        self.assertEqual(nomes[0]["nome"], "SPMS - Serviços Partilhados do Ministério da Saúde, E. P. E.")
        self.assertIn("Sport Lisboa e Benfica", [e["nome"] for e in nomes])
        self.assertIn("Hospital de Espinho", [e["nome"] for e in nomes])      # "espinho" tem "sp"
        # por qualquer dos nomes por que ja apareceu, nao so o canonico
        self.assertEqual([e["nif"] for e in radar.sugestoes_de_entidade_do_corpus("partilhados")],
                         ["509540716"])
        self.assertEqual(radar.sugestoes_de_entidade_do_corpus("s"), [])
        r = radar.app.test_client().get("/entidades.json?de=contratos&q=benfica")
        self.assertEqual([e["nif"] for e in r.get_json()], ["500000001"])

    def test_com_a_chave_o_texto_nao_prende_e_sem_ela_filtra(self):
        from werkzeug.datastructures import MultiDict
        onde, vals = radar.condicoes_contratos(MultiDict({"adj": "SPMS", "entid": "509540716"}))
        self.assertIn("c.adjudicante_chave = ?", onde)
        self.assertNotIn("adjudicante_norm", onde)
        onde, vals = radar.condicoes_contratos(MultiDict({"adj": "SPMS"}))
        self.assertIn("adjudicante_norm", onde)
        onde, vals = radar.condicoes_contratos(MultiDict({"ganhou": "MEO", "vencid": "500000009"}))
        self.assertIn("WHERE chave=?", onde)
        self.assertNotIn("nome_norm LIKE", onde)
        onde, vals = radar.condicoes_contratos(MultiDict({"ganhou": "MEO"}))
        self.assertIn("nome_norm LIKE", onde)

    def test_o_formulario_dos_contratos_sugere_e_perdeu_as_exclusoes(self):
        html_ = radar.app.test_client().get("/contratos").get_data(as_text=True)
        form = html_.split("action='/contratos'")[1].split("</form>")[0]
        self.assertIn("data-sugere='contratos' data-chave-em='entid'", form)
        self.assertIn("data-sugere='contratos' data-chave-em='vencid'", form)
        self.assertIn("name='entid'", form)
        self.assertIn("name='vencid'", form)
        for campo in ("name='q_excl'", "name='op'"):
            self.assertNotIn(campo, form)
        self.assertIn("type='hidden' id='filtro-cpv-excl'", form)
        self.assertIn("datalist id='entidades-contratos'", html_)
        self.assertIn("/entidades.json", html_)
        # o que vier na URL passa escondido
        html_ = radar.app.test_client().get("/contratos?q=x&op=ou").get_data(as_text=True)
        self.assertIn("<input type='hidden' name='op' value='ou'>", html_)


class TestPaginasDeErro(BaseTemporaria):
    """15/09/2026: um 404 dava a página nua do Werkzeug e um 500 dava
    «Internal Server Error» sem ficar registado em lado nenhum. Passam
    a ter a página da empresa, e o 500 fica na marca `painel_ultimo_erro`
    e na série `erros`, que a saúde dos Indicadores mostra."""

    def setUp(self):
        super().setUp()
        self.cliente = radar.app.test_client()

    def test_404_tem_a_pagina_da_empresa(self):
        r = self.cliente.get("/isto-nao-existe")
        self.assertEqual(r.status_code, 404)
        html_ = r.get_data(as_text=True)
        self.assertIn("Não há nada aqui", html_)
        self.assertIn("href=\"/\"", html_)
        self.assertNotIn("Werkzeug", html_)

    def test_500_fica_registado_e_tem_pagina(self):
        # a vista da lista a rebentar, só durante este pedido: o Flask
        # não deixa juntar rotas depois do primeiro pedido, e a lista é
        # a página que mais se abre
        regra = "/"
        endpoint = next(x.endpoint for x in radar.app.url_map.iter_rules()
                        if x.rule == regra and "GET" in x.methods)

        def rebenta(*a, **kw):
            raise ZeroDivisionError("de propósito")
        with unittest.mock.patch.dict(radar.app.view_functions, {endpoint: rebenta}), \
                unittest.mock.patch.dict(radar.app.config, {"PROPAGATE_EXCEPTIONS": False}):
            r = self.cliente.get(regra)
        self.assertEqual(r.status_code, 500)
        html_ = r.get_data(as_text=True)
        self.assertIn("Correu mal", html_)
        self.assertNotIn("Internal Server Error", html_)
        valor = radar.le_marca("painel_ultimo_erro")
        self.assertIn("ZeroDivisionError", valor)
        self.assertIn("GET /", valor)
        with radar.liga() as c:
            n = c.execute("SELECT COUNT(*) FROM erros WHERE tipo='painel'").fetchone()[0]
        self.assertEqual(n, 1)

    def test_a_saude_dos_indicadores_mostra_o_erro(self):
        radar.marca_erro("painel_ultimo_erro", "painel", "2026-09-15 10:00 em GET /x: KeyError")
        html_ = self.cliente.get("/configuracoes/indicadores").get_data(as_text=True)
        self.assertIn("Último erro do painel", html_)
        self.assertIn("KeyError", html_)


class TestRotaDeSaude(BaseTemporaria):
    """15/09/2026: não havia nada que alguém de fora pudesse vigiar. O
    `/saude` responde «ok» sem sessão (senão o monitor caía no /entrar,
    que dá sempre 200, e nunca via o painel cair), e 503 quando a base
    não responde. Não diz nada de dentro."""
    FORA = {"REMOTE_ADDR": "203.0.113.7"}

    def setUp(self):
        super().setUp()
        self.enterContext(unittest.mock.patch.object(
            radar, "CONFIG", os.path.join(self.pasta, "config.json")))
        self.cliente = radar.app.test_client()

    def test_responde_ok_sem_sessao_e_de_fora(self):
        r = self.cliente.get("/saude", environ_base=self.FORA)
        self.assertEqual(r.status_code, 200)
        self.assertEqual(r.get_data(as_text=True), "ok")
        self.assertEqual(r.headers.get("Cache-Control"), "no-store")
        self.assertIn("/saude", radar.ROTAS_ABERTAS)

    def test_nao_diz_nada_de_dentro(self):
        radar.marca("ultima_verificacao", "2026-09-15 09:00")
        texto = self.cliente.get("/saude", environ_base=self.FORA).get_data(as_text=True)
        self.assertNotIn("2026", texto)
        self.assertNotIn("anúncios", texto)

    def test_503_quando_a_base_nao_responde(self):
        def liga_partida():
            raise sqlite3.OperationalError("disco fora")
        with unittest.mock.patch.object(radar, "liga", liga_partida):
            r = self.cliente.get("/saude", environ_base=self.FORA)
        self.assertEqual(r.status_code, 503)


class TestEnsaioDeRestauro(BaseTemporaria):
    """15/09/2026: a cópia diária fazia-se há semanas e ninguém tinha
    provado que se restaurava. `--ensaiar-copia` abre a última cópia só
    de leitura, passa-lhe o integrity_check e conta contra a base viva;
    a marca `ultimo_ensaio_copia` fica na saúde dos Indicadores e na
    secção Cópias. Uma cópia vazia ou corrompida diz «FALHOU»."""

    def setUp(self):
        super().setUp()
        self.copias = os.path.join(self.pasta, "copias")
        self.enterContext(unittest.mock.patch.object(radar, "COPIAS", self.copias))
        with radar.liga() as c:
            for i in range(3):
                c.execute("INSERT INTO anuncios (ref, titulo, estado) VALUES (?,?,?)",
                          ("R%d" % i, "t%d" % i, "interessa" if i == 0 else "novo"))

    def test_sem_copia_nenhuma_diz_isso(self):
        with self.assertRaises(FileNotFoundError):
            radar.ensaiar_copia()

    def test_a_ultima_copia_serve_e_conta_contra_a_viva(self):
        os.makedirs(self.copias)
        velha = os.path.join(self.copias, "radar-2026-09-01.db")
        open(velha, "wb").close()          # a mais velha nunca é escolhida
        destino = radar.copia_de_seguranca(guardar=0)
        self.assertEqual(radar.ultima_copia(), destino)
        r = radar.ensaiar_copia()
        self.assertTrue(r["serve"])
        self.assertEqual(r["integridade"], "ok")
        self.assertEqual(r["contagens"]["anuncios"], (3, 3))
        self.assertEqual(r["contagens"]["triagem"], (1, 1))
        self.assertTrue(radar.le_marca("ultimo_ensaio_copia").startswith("ok: "))
        # nunca escreve na cópia: nem um -journal ao lado
        self.assertFalse(os.path.exists(destino + "-journal"))
        html_ = radar.app.test_client().get("/configuracoes/copias").get_data(as_text=True)
        self.assertIn("Ensaio de restauro: ok:", html_)
        html_ = radar.app.test_client().get("/configuracoes/indicadores").get_data(as_text=True)
        self.assertIn("Ensaio de restauro", html_)

    def test_uma_copia_vazia_nao_serve(self):
        os.makedirs(self.copias)
        vazia = os.path.join(self.copias, "radar-2026-09-10.db")
        c = sqlite3.connect(vazia)
        c.execute("CREATE TABLE anuncios (ref TEXT, estado TEXT)")
        c.execute("CREATE TABLE estado (chave TEXT, valor TEXT)")
        c.commit()
        c.close()
        r = radar.ensaiar_copia(vazia)
        self.assertFalse(r["serve"])
        self.assertEqual(r["contagens"]["anuncios"], (0, 3))
        self.assertTrue(radar.le_marca("ultimo_ensaio_copia").startswith("FALHOU"))


class TestAEmpresaNoSeuFicheiro(BaseTemporaria):
    """A F1 do plano multi-empresa (23/09/2026): o que é de uma empresa
    vive em `empresas/<id>/empresa.db`, ligado por ATTACH, e o `radar.db`
    fica com o que é da plataforma. O erro a não repetir tem duas caras:
    uma tabela nos dois ficheiros (o nome sem prefixo resolve-se no
    `radar.db` primeiro, e a da empresa fica a apodrecer ao lado), e uma
    separação que apaga antes de ter a certeza de que copiou."""

    def setUp(self):
        super().setUp()
        self.copias = os.path.join(self.pasta, "copias")
        self.enterContext(unittest.mock.patch.object(radar, "COPIAS", self.copias))

    def _tabelas(self, esquema):
        with radar.liga() as c:
            return {r[0] for r in c.execute(
                "SELECT name FROM %s.sqlite_master WHERE type='table' "
                "AND name NOT LIKE 'sqlite_%%'" % esquema)}

    def _base_antiga(self, propostas=2):
        """Uma base de antes da F1: as tabelas da empresa dentro do
        radar.db, com linhas e a marca do resumo, e sem ficheiro da
        empresa nenhum."""
        emp = radar.db_da_empresa()
        for f in (emp, emp + "-wal", emp + "-shm"):
            if os.path.exists(f):
                os.remove(f)
        radar.iniciar_empresa(radar.DB)
        c = sqlite3.connect(radar.DB)
        for i in range(propostas):
            c.execute("INSERT INTO propostas (ref, estado) VALUES (?, 'analisar')",
                      ("%d/2026" % (i + 1),))
        c.execute("INSERT INTO historico (ref, accao) VALUES ('1/2026', 'x')")
        c.execute("INSERT OR REPLACE INTO estado VALUES ('ultimo_resumo', '2026-09-22')")
        c.commit()
        c.close()

    def test_nenhuma_tabela_mora_nos_dois_ficheiros(self):
        da_plataforma, da_empresa = self._tabelas("main"), self._tabelas("emp")
        self.assertEqual(da_plataforma & da_empresa, set())
        self.assertLessEqual(set(radar.TABELAS_DA_EMPRESA), da_empresa)
        self.assertIn("anuncios", da_plataforma)

    def test_sem_ficheiro_da_empresa_a_propostas_nem_existe(self):
        with unittest.mock.patch.object(radar, "EMPRESA_ACTIVA", 2):
            with radar.liga() as c:
                with self.assertRaises(sqlite3.OperationalError):
                    c.execute("SELECT COUNT(*) FROM propostas")
                # e a plataforma continua a responder
                c.execute("SELECT COUNT(*) FROM anuncios")

    def test_separar_leva_as_linhas_e_so_depois_apaga(self):
        self._base_antiga()
        radar.iniciar_db()
        self.assertNotIn("propostas", self._tabelas("main"))
        with radar.liga() as c:
            self.assertEqual(c.execute("SELECT COUNT(*) FROM emp.propostas")
                             .fetchone()[0], 2)
            self.assertEqual(c.execute("SELECT COUNT(*) FROM emp.historico")
                             .fetchone()[0], 1)
            self.assertIsNone(c.execute("SELECT 1 FROM estado WHERE chave="
                                        "'ultimo_resumo'").fetchone())
        self.assertEqual(radar.le_marca_da_empresa("ultimo_resumo"), "2026-09-22")
        # a cópia de antes tem as linhas, no radar.db como estavam
        antes = [f for f in os.listdir(self.copias) if "antes-da-empresa" in f]
        self.assertEqual(len(antes), 1)
        c = sqlite3.connect(os.path.join(self.copias, antes[0]))
        self.assertEqual(c.execute("SELECT COUNT(*) FROM propostas").fetchone()[0], 2)
        c.close()
        # e a segunda volta não faz nada
        self.assertIsNone(radar.separar_empresa())

    def test_separar_nao_apaga_nada_se_as_contagens_nao_batem(self):
        self._base_antiga(propostas=2)
        radar.iniciar_empresa()
        with sqlite3.connect(radar.db_da_empresa()) as c:
            c.execute("INSERT INTO propostas (ref) VALUES ('9/2026')")
        with self.assertRaises(RuntimeError):
            radar.separar_empresa()
        self.assertIn("propostas", self._tabelas("main"))

    def test_a_copia_diaria_leva_o_ficheiro_da_empresa(self):
        with radar.liga() as c:            # sem anúncios a cópia não serve
            c.execute("INSERT INTO anuncios (ref, titulo) VALUES ('1/2026', 't')")
        radar.criar_proposta("1/2026")
        destino = radar.copia_de_seguranca(guardar=0)
        da_empresa = radar.copia_da_empresa(destino)
        self.assertTrue(os.path.exists(da_empresa))
        r = radar.ensaiar_copia()
        self.assertTrue(r["serve"])
        self.assertEqual(r["contagens"]["propostas"], (1, 1))

class TestDuasEmpresas(BaseTemporaria):
    """A F2 do plano multi-empresa (23/09/2026): a recolha corre uma vez,
    e o que é de cada empresa corre em cada uma. Os erros que isto fecha
    eram todos silenciosos com uma empresa só: a fila das alterações
    tinha um `avisado_em` para todas (a primeira a mandar o resumo
    apagava as das outras, e a B recebia as da A); os trabalhos da
    plataforma liam a escada da empresa activa (os concursos da segunda
    nunca eram relidos); e o que o DR fez ficava no histórico de quem
    estivesse activo quando a verificação passou."""

    CORPO = TestAlteracoesDoDR.CORPO
    _texto = TestAlteracoesDoDR._texto
    _poe = TestAlteracoesDoDR._poe
    _chega = TestAlteracoesDoDR._chega

    def setUp(self):
        super().setUp()
        radar.iniciar_empresa(radar.db_da_empresa(2))

    def _propostas(self, id_):
        with radar.com_empresa(id_):
            with radar.liga() as c:
                return [p["ref"] for p in c.execute(
                    "SELECT ref FROM propostas ORDER BY id")]

    def _alteracao(self, ref, quando):
        with radar.liga() as c:
            return c.execute(
                "INSERT INTO alteracoes (ref, campo, antes, depois, detectado_em)"
                " VALUES (?, 'prazo', '2026-08-13', '2026-09-11', ?)",
                (ref, quando)).lastrowid

    def _por_avisar(self, id_):
        with radar.com_empresa(id_):
            return [x["id"] for x in radar.alteracoes_por_avisar()]

    def test_cada_empresa_ve_so_as_suas_propostas(self):
        radar.criar_proposta("1/2026")
        with radar.com_empresa(2):
            radar.criar_proposta("2/2026")
        self.assertEqual(radar.empresas_existentes(), [1, 2])
        self.assertEqual(self._propostas(1), ["1/2026"])
        self.assertEqual(self._propostas(2), ["2/2026"])
        # e fora do `with` volta a de omissão
        self.assertEqual(radar.empresa_activa(), radar.EMPRESA_ACTIVA)

    def test_os_trabalhos_da_plataforma_veem_a_escada_de_todas(self):
        radar.criar_proposta("1/2026")
        with radar.com_empresa(2):
            radar.criar_proposta("2/2026")
        with radar.liga() as c:
            radar.marcar_os_da_escada(c)
            refs = {r[0] for r in c.execute("SELECT ref FROM temp.na_escada")}
        self.assertEqual(refs, {"1/2026", "2/2026"})

    def test_a_alteracao_passa_a_proposta_de_todas_as_empresas(self):
        self._poe("100/2026", "2026-07-17", self._texto())
        self._poe("200/2026", "2026-08-14")
        radar.criar_proposta("200/2026")
        with radar.com_empresa(2):
            radar.criar_proposta("200/2026")
        self._chega("200/2026", self._texto(prazo="11-09-2026",
                                            altera="100/2026"))
        self.assertEqual(self._propostas(1), ["100/2026"])
        self.assertEqual(self._propostas(2), ["100/2026"])
        # o que o DR fez está uma vez, na plataforma, e cada empresa vê-o
        # na cronologia ao lado do que ela própria fez
        with radar.liga() as c:
            self.assertEqual(c.execute(
                "SELECT COUNT(*) FROM eventos WHERE ref='200/2026' "
                "AND accao='alteração'").fetchone()[0], 1)
            accoes = [p["accao"] for p in radar.passos_do_anuncio(c, "100/2026", 20)]
        self.assertIn("alterou", accoes)
        self.assertIn("estado", accoes)

    def test_a_alteracao_so_chega_a_quem_tem_o_concurso_e_uma_vez_a_cada(self):
        self._poe("100/2026", "2026-07-17", self._texto())
        radar.criar_proposta("100/2026")
        primeira = self._alteracao("100/2026", "2099-01-01 09:00")
        self.assertEqual(self._por_avisar(1), [primeira])
        self.assertEqual(self._por_avisar(2), [])       # não é concurso dela
        radar.marcar_alteracoes_avisadas([{"id": primeira}])
        self.assertEqual(self._por_avisar(1), [])
        # a B pega no concurso DEPOIS: a alteração velha não é notícia
        with radar.com_empresa(2):
            radar.criar_proposta("100/2026")
            with radar.liga() as c:
                c.execute("UPDATE propostas SET criada_em='2099-01-02 09:00'")
        self.assertEqual(self._por_avisar(2), [])
        # a seguinte chega às duas, e o aviso de uma não apaga o da outra
        segunda = self._alteracao("100/2026", "2099-01-03 09:00")
        with radar.com_empresa(2):
            radar.marcar_alteracoes_avisadas([{"id": segunda}])
        self.assertEqual(self._por_avisar(1), [segunda])
        self.assertEqual(self._por_avisar(2), [])

    def test_os_eventos_saem_do_historico_uma_vez_so(self):
        for id_ in (1, 2):
            with radar.com_empresa(id_):
                with radar.liga() as c:
                    c.executemany(
                        "INSERT INTO historico (ref, quem, accao, detalhe, quando)"
                        " VALUES ('9/2026', ?, ?, ?, ?)",
                        [("DR", "alterou", "prazo: a → b", "2026-09-01 09:00"),
                         ("Afonso", "estado", "Ganho", "2026-09-01 10:00")])
        radar.iniciar_db()
        radar.iniciar_db()                              # idempotente
        with radar.liga() as c:
            self.assertEqual(c.execute("SELECT COUNT(*) FROM eventos "
                                       "WHERE ref='9/2026'").fetchone()[0], 1)
        for id_ in (1, 2):
            with radar.com_empresa(id_):
                with radar.liga() as c:
                    self.assertEqual([r[0] for r in c.execute(
                        "SELECT accao FROM historico WHERE ref='9/2026'")],
                        ["estado"])

    def test_a_verificacao_corre_o_trabalho_de_cada_empresa(self):
        vistas = []
        cfg = dict(radar.CONFIG_INICIAL, copia_de_seguranca=False,
                   vortal_preliminares=False)
        with unittest.mock.patch.object(radar, "recolher",
                                        return_value=(False, "sem rede", [])), \
             unittest.mock.patch.object(radar, "vigiar_pecas", return_value=(0, "")), \
             unittest.mock.patch.object(radar, "reler_incompletas", return_value=(0, "")), \
             unittest.mock.patch.object(radar, "exportar_triagem"), \
             unittest.mock.patch.object(
                 radar, "trabalho_da_empresa",
                 side_effect=lambda *a: vistas.append(radar.empresa_activa()) or 0):
            radar.verificar(cfg)
        self.assertEqual(vistas, [1, 2])

    def test_a_copia_diaria_leva_todas_as_empresas(self):
        self.enterContext(unittest.mock.patch.object(
            radar, "COPIAS", os.path.join(self.pasta, "copias")))
        destino = radar.copia_de_seguranca(guardar=0)
        dia = os.path.basename(destino)[len("radar-"):]
        self.assertEqual(sorted(f for f in os.listdir(radar.COPIAS)
                                if f.startswith("empresa-")),
                         ["empresa-1-" + dia, "empresa-2-" + dia])


class TestConfigPorEmpresa(BaseTemporaria):
    """A F3 do plano multi-empresa (23/09/2026): o que no config.json é
    de uma empresa — quem ela é, o interesse, os alertas, o destino e a
    hora do resumo, a janela do urgente — vive no `config.json` dela; o
    resto é da plataforma. O erro que isto fecha é o da herança: uma
    segunda empresa a ler o config da pasta mandava o resumo para o
    e-mail da primeira e comparava o Portal BASE com o NIF dela."""

    def _global(self):
        with open(radar.CONFIG, encoding="utf-8") as f:
            return json.load(f)

    def test_as_chaves_da_empresa_mudam_de_ficheiro_e_o_resto_fica(self):
        cfg = dict(nome_da_empresa="LATD", nif_da_empresa="516241362",
                   interesse_activo=True, interesse_cpv="72",
                   horas_verificacao=["09:00"],
                   email={"para": "a@x.pt", "de": "radar@x.pt",
                          "servidor": "smtp.x.pt", "porta": 587,
                          "hora_resumo": "18:00"})
        with open(radar.CONFIG, "w", encoding="utf-8") as f:
            json.dump(cfg, f)
        radar.iniciar_db()
        global_ = self._global()
        for chave in radar.CONFIG_DA_EMPRESA:
            self.assertNotIn(chave, global_)
        self.assertEqual(global_["horas_verificacao"], ["09:00"])
        self.assertEqual(global_["email"], {"de": "radar@x.pt",
                                            "servidor": "smtp.x.pt", "porta": 587})
        lido = radar.ler_config()
        self.assertEqual((lido["nif_da_empresa"], lido["interesse_cpv"]),
                         ("516241362", "72"))
        self.assertEqual(lido["email"]["para"], "a@x.pt")
        self.assertEqual(lido["email"]["servidor"], "smtp.x.pt")
        self.assertEqual(radar.separar_config_da_empresa(), {})   # uma vez só

    def test_outra_empresa_nao_herda_o_que_e_da_primeira(self):
        radar.gravar_config({"nif_da_empresa": "516241362",
                             "email": {"para": "a@x.pt", "servidor": "smtp.x.pt"}})
        radar.iniciar_empresa(radar.db_da_empresa(2))
        with radar.com_empresa(2):
            cfg = radar.ler_config()
        self.assertEqual(cfg["nif_da_empresa"], "")
        self.assertEqual(cfg["email"]["para"], "")
        self.assertEqual(cfg["email"]["servidor"], "smtp.x.pt")  # a conta que envia é de todas

    def test_gravar_leva_cada_chave_para_o_ficheiro_dela(self):
        radar.gravar_config({"email": {"para": "a@x.pt"}})
        radar.iniciar_empresa(radar.db_da_empresa(2))
        with radar.com_empresa(2):
            radar.gravar_config({"email": {"para": "b@x.pt"}, "dias_catchup": 20})
            self.assertEqual(radar.ler_config()["email"]["para"], "b@x.pt")
        self.assertEqual(radar.ler_config()["email"]["para"], "a@x.pt")
        self.assertEqual(radar.ler_config()["dias_catchup"], 20)
        self.assertEqual(self._global()["dias_catchup"], 20)

    def test_a_verificacao_manda_o_resumo_de_cada_empresa_para_o_destino_dela(self):
        radar.gravar_config({"email": {"para": "a@x.pt", "hora_resumo": "00:00"}})
        radar.iniciar_empresa(radar.db_da_empresa(2))
        with radar.com_empresa(2):
            radar.gravar_config({"email": {"para": "b@x.pt", "hora_resumo": "00:00"}})
        destinos = []
        cfg = radar.ler_config()
        with unittest.mock.patch.object(radar, "registar_alertas", return_value=0), \
             unittest.mock.patch.object(radar, "registar_seguidas"), \
             unittest.mock.patch.object(radar, "sincronizar_tarefas"), \
             unittest.mock.patch.object(
                 radar, "enviar_resumo",
                 side_effect=lambda c: destinos.append(c["email"]["para"])):
            for id_ in (1, 2):
                with radar.com_empresa(id_):
                    radar.trabalho_da_empresa(cfg, True, lambda _: None)
        self.assertEqual(destinos, ["a@x.pt", "b@x.pt"])

    def test_a_releitura_das_incompletas_deixa_rasto(self):
        """O achado de 23/09/2026: a leitura completada pela verificação
        das 11:01 ficou gravada na `analise` e não deixou linha em lado
        nenhum — o `reler_incompletas()` chamava o `analisar_pecas()` sem
        o `registar` que o `ler_pecas_e_registar()` tem."""
        with unittest.mock.patch.object(radar, "cadeia_de_fornecedores",
                                        return_value=["groq"]), \
             unittest.mock.patch.object(radar, "cadeia_esgotada", return_value=False), \
             unittest.mock.patch.object(radar, "refs_com_leitura_incompleta",
                                        return_value=["5/2026"]), \
             unittest.mock.patch.object(radar, "analisar_pecas",
                                        return_value=(True, "")):
            self.assertEqual(radar.reler_incompletas(), (1, ""))
        with radar.liga() as c:
            linhas = c.execute("SELECT accao, detalhe, quem FROM eventos "
                               "WHERE ref='5/2026'").fetchall()
        self.assertEqual([tuple(l) for l in linhas],
                         [("leitura", "peças lidas", "radar")])


class TestOEmailDoConviteFicaNaConta(BaseTemporaria):
    """O ensaio do percurso do cliente (1/10/2026): o convite foi para
    `x+teste@gmail.com`, a pessoa escolheu o utilizador «teste.claude», e
    a conta ficou sem o e-mail -- o «esqueci-me», que só procurava pela
    coluna `email`, respondia o mesmo de sempre e não criava ligação
    nenhuma. Qualquer cliente cujo utilizador não fosse o e-mail ficava
    sem «esqueci-me». E do mesmo ensaio: apagar a empresa deixava o
    plano dela órfão na tabela `planos`."""

    FORA = {"REMOTE_ADDR": "203.0.113.7"}
    EMAIL = "x+teste@gmail.com"

    def setUp(self):
        super().setUp()
        self.mandados = []

        def enviar(assunto, corpo, cfg=None, html_corpo=None):
            self.mandados.append((cfg or {}).get("email", {}).get("para"))
            return True, "enviado"
        self.enterContext(unittest.mock.patch.object(radar, "enviar_email", enviar))
        self.enterContext(unittest.mock.patch.object(
            radar.threading, "Thread", TestPesquisaGeralERepor._JaCorre))

    def test_o_nome_escrito_no_convite_fica_na_conta(self):
        """6/10/2026: sem o nome, a conta ficava «joana», do e-mail."""
        with radar.liga() as c:
            codigo = radar.contas.criar_convite(c, 1, "joana@nova.pt", "admin")
            token, _ = radar.contas.usar_convite(
                c, codigo, "joana@nova.pt", "senha-comprida-boa",
                nome="Joana Matos")
            self.assertTrue(token)
            self.assertEqual(c.execute("SELECT nome FROM utilizadores WHERE "
                                       "email='joana@nova.pt'").fetchone()[0],
                             "Joana Matos")
        self.assertIn('name="nome"', radar.MOLDES_JINJA.loader.get_source(
            radar.MOLDES_JINJA, "convite.html")[0])

    def _pelo_convite(self, utilizador, email=EMAIL, papel="admin"):
        with radar.liga() as c:
            codigo = radar.contas.criar_convite(c, 1, email, papel)
            token, porque = radar.contas.usar_convite(c, codigo, utilizador,
                                                      "senha-comprida-boa")
        self.assertTrue(token, porque)

    def _contacto(self, utilizador):
        with radar.liga() as c:
            return c.execute("SELECT contacto FROM utilizadores WHERE email=?",
                             (utilizador,)).fetchone()[0]

    def esqueci(self, email):
        return radar.app.test_client().post("/esqueci-me", data={"email": email},
                                            environ_base=self.FORA)

    def _reposicoes(self):
        with radar.liga() as c:
            return c.execute("SELECT COUNT(*) FROM reposicoes").fetchone()[0]

    def test_a_conta_do_convite_guarda_o_email_mesmo_com_outro_utilizador(self):
        self._pelo_convite("teste.claude@gmail.com")
        self.assertEqual(self._contacto("teste.claude@gmail.com"), self.EMAIL)

    def test_o_esqueci_me_pelo_email_do_convite_cria_a_ligacao(self):
        self._pelo_convite("teste.claude@gmail.com")
        self.assertEqual(self.esqueci("X+Teste@gmail.com").status_code, 200)
        self.assertEqual(self._reposicoes(), 1)
        # vai para o e-mail, e não para «teste.claude», que não é endereço
        self.assertEqual(self.mandados, [self.EMAIL])

    def test_duas_contas_com_o_mesmo_endereco_nao_recebem_nada(self):
        """O convite não pendura o endereço de outra conta -- e se, por
        qualquer caminho, dois casarem com ele, não se escolhe um."""
        with radar.liga() as c:
            radar.contas.criar_utilizador(c, self.EMAIL, "senha-comprida-boa",
                                          papel="tester")
        self._pelo_convite("outro.nome@gmail.com")
        self.assertEqual(self._contacto("outro.nome@gmail.com"), "")
        with radar.liga() as c:
            c.execute("UPDATE utilizadores SET contacto=? WHERE email='outro.nome@gmail.com'",
                      (self.EMAIL,))
        self.assertEqual(self.esqueci(self.EMAIL).status_code, 200)
        self.assertEqual((self._reposicoes(), self.mandados), (0, []))

    def test_o_dono_continua_sem_ligacao_pelo_contacto(self):
        with radar.liga() as c:
            uid = radar.contas.criar_utilizador(c, "afonso", "senha-comprida-boa",
                                                pela_consola=True)
            radar.contas.gravar_contacto(c, uid, "dono@miragov.pt")
        self.assertEqual(self.esqueci("dono@miragov.pt").status_code, 200)
        self.assertEqual((self._reposicoes(), self.mandados), (0, []))

    def test_a_migracao_enche_a_conta_antiga_a_partir_do_convite(self):
        """Uma base de antes da coluna: a conta que nasceu do convite
        fica com o e-mail dele; a que nasceu pela consola na mesma
        empresa e papel, horas antes, fica sem -- não é inequívoca."""
        c = sqlite3.connect(":memory:")
        c.row_factory = sqlite3.Row
        radar.contas.iniciar_tabelas(c)
        c.execute("ALTER TABLE utilizadores DROP COLUMN contacto")
        for email, criado in (("teste.claude", "2026-10-01 10:00:01"),
                              ("antiga", "2026-10-01 07:00:00")):
            c.execute("INSERT INTO utilizadores (email, hash, criado_em, papel, "
                      "empresa_id) VALUES (?, 'x', ?, 'admin', 6)", (email, criado))
        c.execute("INSERT INTO convites (resumo, empresa_id, email, papel, "
                  "criado_em, expira, usado_em) VALUES ('r', 6, ?, 'admin', "
                  "'2026-10-01 09:00:00', '2026-10-08 09:00:00', "
                  "'2026-10-01 10:00:00')", (self.EMAIL,))
        radar.contas.iniciar_tabelas(c)
        self.assertEqual(dict(c.execute("SELECT email, contacto FROM utilizadores")),
                         {"teste.claude": self.EMAIL, "antiga": ""})

    def test_muda_o_contacto_na_conta_so_com_a_palavra_passe_actual(self):
        self._pelo_convite("teste.claude@gmail.com")
        cliente = radar.app.test_client()
        cliente.post("/entrar", data={"email": "teste.claude@gmail.com",
                                      "senha": "senha-comprida-boa"},
                     environ_base=self.FORA)
        self.assertIn(self.EMAIL, cliente.get(
            "/configuracoes/conta", environ_base=self.FORA).get_data(as_text=True))
        token = re.search(r"<meta name=\"csrf\" content=\"([0-9a-f]+)\"",
                          cliente.get("/configuracoes/conta", environ_base=self.FORA)
                          .get_data(as_text=True)).group(1)
        for actual, esperado in (("errada", self.EMAIL),
                                 ("senha-comprida-boa", "novo@empresa.pt")):
            cliente.post("/configuracoes/conta", data={
                "csrf": token, "actual": actual, "contacto": "novo@empresa.pt"},
                environ_base=self.FORA)
            self.assertEqual(self._contacto("teste.claude@gmail.com"), esperado)
        # e a palavra-passe ficou a mesma
        with radar.liga() as c:
            self.assertTrue(radar.contas.entrar(c, "teste.claude@gmail.com",
                                                "senha-comprida-boa")[0])

    def test_apagar_a_empresa_tira_o_plano_e_o_arranque_os_orfaos(self):
        gama = radar.criar_empresa("Gama")
        with radar.liga() as c:
            radar.contas.gravar_plano(c, gama, "duo")
            radar.contas.gravar_plano(c, 99, "solo")    # o órfão de antes
        _, _, saiu = radar.apagar_empresa(gama)
        self.assertEqual(saiu["plano"], 1)
        radar.iniciar_db()
        with radar.liga() as c:
            self.assertEqual(c.execute("SELECT COUNT(*) FROM planos").fetchone()[0], 0)


class TestPesquisaGeralERepor(BaseTemporaria):
    """Três trabalhos de 1/10/2026 («Faz todos», decisão dele):

    - a pesquisa geral (J1 da auditoria das sete leis, o 2R-D8 do
      BACKLOG): uma caixa na barra, com Ctrl+K e «/», que acha concurso,
      proposta, entidade e NIF -- por um índice de texto (`trigram`),
      porque sem ele cada tecla varria os 210 mil anúncios;
    - o «esqueci-me» por e-mail (J7): a pessoa pede a ligação de repor
      sem passar pelo gestor. É uma rota aberta, e por isso cada guarda
      tem aqui o seu teste;
    - o CSS morto (o 18 da auditoria dos ícones e dos pesos): regras que
      nenhum HTML gerado pode usar."""

    FORA = {"REMOTE_ADDR": "203.0.113.7"}

    # ------------------------------------------------------------ o CSS

    @staticmethod
    def _classes_das_regras(css):
        """{classe: [selector]} de todas as regras da folha."""
        css = re.sub(r"/\*.*?\*/", "", css, flags=re.S)
        saida = {}
        for cabeca in re.findall(r"([^{}]+)\{", css):
            for selector in cabeca.split(","):
                if selector.strip().startswith("@"):
                    continue
                for classe in re.findall(r"\.(-?[A-Za-z_][\w-]*)",
                                         re.sub(r"\[[^\]]*\]", "", selector)):
                    saida.setdefault(classe, []).append(" ".join(selector.split()))
        return saida

    def test_nenhuma_regra_do_css_pede_uma_classe_que_o_codigo_nao_gera(self):
        """O 18 da auditoria dos pesos (1/10/2026): o `CSS` e o `CSS_NOVO`
        guardavam regras de ecrãs que já não existem -- o `.kpi` dos
        indicadores antigos, o `h1.tit` e o `p.subtit` da faixa de antes
        do sistema de desenho, o cartão `.item-*` dos Concursos, o
        `.hj-l` e o `.hj-p` da abertura agrupada por proposta, os
        `.sit-n` e os `.delta` da Situação. Pesos soltos (620, 680, 700)
        que ninguém via e que confundiam quem lia a folha.

        A regra: cada classe que uma regra destas duas folhas pede
        aparece numa cadeia do `radar.py` (ou do `icones.py`) fora das
        próprias folhas e das docstrings. É uma prova por baixo -- uma
        palavra que apareça noutro sentido conta como usada --, e por
        isso as duas que só existiam assim (`.cx`, que só aparece como
        atributo de um `<circle>`, e `.abas`, que só é a marca do molde)
        vão à parte, pelo nome."""
        arvore = ast.parse(radar_fonte())
        docs = {id(no.body[0].value) for no in ast.walk(arvore)
                if isinstance(no, (ast.Module, ast.FunctionDef, ast.ClassDef))
                and no.body and isinstance(no.body[0], ast.Expr)
                and isinstance(no.body[0].value, ast.Constant)}
        folhas = {id(no.value) for no in ast.walk(arvore)
                  if isinstance(no, ast.Assign) and len(no.targets) == 1
                  and isinstance(no.targets[0], ast.Name)
                  and no.targets[0].id in ("CSS", "CSS_NOVO")}
        cadeias = [no.value for no in ast.walk(arvore)
                   if isinstance(no, ast.Constant) and isinstance(no.value, str)
                   and id(no) not in docs and id(no) not in folhas]
        with open(os.path.join(os.path.dirname(radar.__file__), "icones.py"),
                  encoding="utf-8") as f:
            cadeias.append(f.read())
        # e os moldes (D1): o HTML que sai do radar.py leva as classes
        pasta = os.path.join(os.path.dirname(radar.__file__), "moldes")
        for nome in os.listdir(pasta):
            with open(os.path.join(pasta, nome), encoding="utf-8") as f:
                cadeias.append(f.read())
        palavras = set(re.findall(r"[A-Za-z_][\w-]*", "\n".join(cadeias)))
        for nome in ("CSS", "CSS_NOVO"):
            classes = self._classes_das_regras(getattr(radar, nome))
            mortas = {c: s[:2] for c, s in classes.items()
                      if c not in palavras or c in ("cx", "abas")}
            self.assertEqual(mortas, {}, nome)

    # ------------------------------------------------- a pesquisa geral

    # fora da ordem da data, de propósito: o índice enche-se pela data, e
    # é isso que deixa a pesquisa dar os mais recentes primeiro
    ANUNCIOS = (("102/2026", "Vigilância humana", "Hospital do Norte",
                 "2026-09-22", "503000003"),
                ("100/2026", "Sistema de videovigilância", "Município de Évora",
                 "2026-09-20", "501000001"),
                ("101/2026", "Limpeza de edifícios", "Câmara de Lagos",
                 "2026-09-21", "502000002"))

    def _semear_anuncios(self, indice=True):
        with radar.liga() as c:
            for ref, titulo, entidade, data, nif in self.ANUNCIOS:
                c.execute("INSERT INTO anuncios (ref, titulo, entidade, data_pub, "
                          "estado, nif, titulo_norm, entidade_norm) VALUES "
                          "(?,?,?,?,'novo',?,simplifica(?),simplifica(?))",
                          (ref, titulo, entidade, data, nif, titulo, entidade))
            radar.contas.criar_utilizador(c, "admin", "senha-comprida",
                                          pela_consola=True)
        if indice:
            self.assertTrue(radar.construir_indice_da_pesquisa(avisar=lambda *_: None))

    def _entrar(self, quem="admin"):
        cliente = radar.app.test_client()
        r = cliente.post("/entrar", data={"email": quem, "senha": "senha-comprida"},
                         environ_base=self.FORA)
        self.assertEqual(r.status_code, 302)
        return cliente

    def procurar(self, cliente, q):
        r = cliente.get("/pesquisa?" + urlencode({"q": q}), environ_base=self.FORA,
                        headers={"Accept": "application/json"})
        self.assertEqual(r.status_code, 200, q)
        # cada resposta diz quanto levou (o objectivo: < 0,3 s a quente)
        self.assertIn("total;dur=", r.headers.get("Server-Timing", ""))
        return r.get_json()

    @staticmethod
    def _refs(resultado):
        return sorted(c["ref"] for c in resultado["concursos"])

    def test_a_pesquisa_acha_o_concurso_por_pedaco_de_palavra_entidade_ref_e_nif(self):
        """O `trigram` responde ao pedaço de palavra, como o `LIKE` de
        sempre: «vigilância» acha a «videovigilância» -- a troca que o
        BACKLOG temia com um índice por palavras não se faz."""
        self._semear_anuncios()
        cliente = self._entrar()
        self.assertEqual(self._refs(self.procurar(cliente, "Vigilância")),
                         ["100/2026", "102/2026"])
        self.assertEqual(self._refs(self.procurar(cliente, "evora")), ["100/2026"])
        self.assertEqual(self._refs(self.procurar(cliente, "101/2026")), ["101/2026"])
        self.assertEqual(self._refs(self.procurar(cliente, "503000003")), ["102/2026"])
        # as palavras têm de estar todas, como na caixa dos Concursos
        self.assertEqual(self._refs(self.procurar(cliente, "vigilancia norte")),
                         ["102/2026"])
        # o mais recente primeiro
        self.assertEqual([c["ref"] for c in self.procurar(cliente, "vigil")["concursos"]],
                         ["102/2026", "100/2026"])
        # e a página, sem JavaScript, escapa o que se escreveu
        corpo = cliente.get("/pesquisa?q=%3Cscript%3Evigil",
                            environ_base=self.FORA).get_data(as_text=True)
        self.assertNotIn("<script>vigil", corpo)
        corpo = cliente.get("/pesquisa?q=vigil", environ_base=self.FORA).get_data(as_text=True)
        self.assertIn("/anuncio/100/2026", corpo)

    def test_a_sintaxe_do_fts5_que_vem_do_pedido_e_texto_literal(self):
        """Revisão de segurança do PR #187 (1/10/2026): o que se escreve na
        caixa vai para um `MATCH`, e o FTS5 tem sintaxe sua -- aspas,
        `OR`, `NEAR`, `*`, `coluna:`. Cada palavra entra como uma frase
        entre aspas, com as aspas de dentro dobradas, e por isso nada
        disto é operador: não rebenta (sem as aspas, `"evil`, `*ola*` e
        `col:evil` são erros de sintaxe, e `col:` pede uma coluna que não
        existe) e não acha o que não diz literalmente."""
        self._semear_anuncios()
        with radar.liga() as c:      # entra pelo gatilho do índice
            c.execute("INSERT INTO anuncios (ref, titulo, entidade, data_pub, "
                      "estado, titulo_norm, entidade_norm) VALUES ('104/2026', "
                      "'Obra teste evil ola', 'Escola', '2026-09-24', 'novo', "
                      "'obra teste evil ola', 'escola')")
        cliente = self._entrar()
        self.assertTrue(radar.indice_da_pesquisa_pronto())
        for q in ('"evil', 'a" OR 1=1--', '*ola*', 'col:evil', 'a NEAR b',
                  '"""', "obra'teste", 'ob;ra'):
            with self.subTest(q=q):
                resultado = self.procurar(cliente, q)
                self.assertEqual(resultado["concursos"], [], q)
                self.assertEqual(resultado["propostas"], [], q)
                r = cliente.get("/pesquisa?" + urlencode({"q": q}),
                                environ_base=self.FORA)
                self.assertEqual(r.status_code, 200, q)
        # e o mesmo termo, sem a sintaxe à volta, acha-o: a prova de que o
        # vazio de cima é o literal, e não um índice que não responde
        self.assertEqual(self._refs(self.procurar(cliente, "evil ola")), ["104/2026"])
        with radar.liga() as c:
            self.assertEqual(c.execute("SELECT COUNT(*) FROM erros").fetchone()[0], 0)

    def test_o_indice_acompanha_as_escritas(self):
        self._semear_anuncios()
        cliente = self._entrar()
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, entidade, data_pub, "
                      "estado, titulo_norm, entidade_norm) VALUES ('103/2026', "
                      "'Refeições escolares', 'Escola', '2026-09-23', 'novo', "
                      "'refeicoes escolares', 'escola')")
        self.assertEqual(self._refs(self.procurar(cliente, "refeic")), ["103/2026"])
        with radar.liga() as c:
            c.execute("UPDATE anuncios SET entidade_norm='agrupamento de escolas',"
                      " nif='600000001' WHERE ref='103/2026'")
        self.assertEqual(self._refs(self.procurar(cliente, "agrupamento")), ["103/2026"])
        self.assertEqual(self._refs(self.procurar(cliente, "600000001")), ["103/2026"])
        self.assertEqual(self._refs(self.procurar(cliente, "escola escolares")),
                         ["103/2026"])
        with radar.liga() as c:
            c.execute("DELETE FROM anuncios WHERE ref='103/2026'")
        self.assertEqual(self._refs(self.procurar(cliente, "refeic")), [])

    def test_sem_o_indice_a_pesquisa_responde_na_mesma(self):
        """O índice constrói-se em fundo no primeiro arranque (~1 min na
        base de tamanho real): até lá, a pesquisa vai pelo `LIKE`."""
        self._semear_anuncios(indice=False)
        cliente = self._entrar()
        self.assertFalse(radar.indice_da_pesquisa_pronto())
        self.assertEqual(self._refs(self.procurar(cliente, "vigilancia")),
                         ["100/2026", "102/2026"])

    def test_a_empresa_so_ve_as_propostas_dela(self):
        self._semear_anuncios()
        criada = radar.criar_proposta(titulo="Manutenção de elevadores da A",
                                      entidade="Município de Évora",
                                      porque_sem_ref="consulta prévia")
        b = radar.criar_empresa("Empresa B")
        with radar.com_empresa(b):
            radar.criar_proposta(titulo="Projecto secreto da B",
                                 entidade="Câmara de Lagos",
                                 porque_sem_ref="consulta prévia")
        with radar.liga() as c:
            radar.contas.criar_utilizador(c, "gestora-b", "senha-comprida",
                                          papel="admin", empresa_id=b)
        a = self._entrar()
        self.assertEqual(self.procurar(a, "secreto")["propostas"], [])
        self.assertEqual([p["id"] for p in self.procurar(a, "elevadores")["propostas"]],
                         [criada])
        corpo = a.get("/pesquisa?q=secreto", environ_base=self.FORA).get_data(as_text=True)
        self.assertNotIn("Projecto secreto", corpo)
        b_ = self._entrar("gestora-b")
        achadas = self.procurar(b_, "secreto")["propostas"]
        self.assertEqual([p["titulo"] for p in achadas], ["Projecto secreto da B"])
        self.assertEqual(self.procurar(b_, "elevadores")["propostas"], [])
        # os concursos são da plataforma: os dois veem-nos
        self.assertEqual(self._refs(self.procurar(b_, "lagos")), ["101/2026"])

    def test_a_pesquisa_acha_a_entidade_pelo_nome_e_pelo_nif(self):
        semear_corpus()
        self._semear_anuncios()
        cliente = self._entrar()
        # pela pergunta inteira: o «3» sozinho não chega ao índice dos
        # concursos, mas a entidade procura-se por todas as grafias
        nomes = [e["nome"] for e in self.procurar(cliente, "empresa 3")["entidades"]]
        self.assertEqual(nomes, ["Empresa 3, Lda"])
        achadas = self.procurar(cliente, "506000003")["entidades"]
        self.assertEqual([e["chave"] for e in achadas], ["506000003"])
        corpo = cliente.get("/pesquisa?q=506000003",
                            environ_base=self.FORA).get_data(as_text=True)
        self.assertIn("/entidade/506000003", corpo)

    def test_a_barra_tem_a_caixa_com_ctrl_k_e_a_barra(self):
        self._semear_anuncios()
        corpo = self._entrar().get("/concursos", environ_base=self.FORA).get_data(as_text=True)
        caixa = re.search(r"<form[^>]*role='search'[^>]*>.*?</form>", corpo, re.S)
        self.assertTrue(caixa, "a caixa da pesquisa na barra")
        self.assertIn("action='/pesquisa'", caixa.group(0))
        self.assertIn("name='q'", caixa.group(0))
        self.assertIn("aria-keyshortcuts='Control+K /'", caixa.group(0))
        # o atalho: Ctrl+K (ou Cmd+K) em qualquer sitio, e «/» fora de um campo
        self.assertIn("e.key === '/'", corpo)
        self.assertIn("(e.ctrlKey || e.metaKey) && (e.key === 'k'", corpo)
        # e o dono sem empresa também procura (os concursos são da plataforma)
        self.assertTrue(radar.dono_le("/pesquisa"))

    # ---------------------------------------------- o «esqueci-me»

    class _JaCorre:
        """Uma thread que corre logo, no `start()`: o e-mail sai em fundo
        (o servidor de correio espera até 30 s), e o teste quer saber o
        que saiu sem depender do escalonador."""

        def __init__(self, target=None, args=(), kwargs=None, **_):
            self.alvo, self.args, self.kwargs = target, args, kwargs or {}

        def start(self):
            self.alvo(*self.args, **self.kwargs)

    def _prepara_o_correio(self):
        self.mandados = []

        def enviar(assunto, corpo, cfg=None, html_corpo=None):
            self.mandados.append({"assunto": assunto, "texto": corpo,
                                  "para": (cfg or {}).get("email", {}).get("para"),
                                  "html": html_corpo or ""})
            return True, "enviado"
        self.enterContext(unittest.mock.patch.object(radar, "enviar_email", enviar))
        self.enterContext(unittest.mock.patch.object(
            radar.threading, "Thread", self._JaCorre))
        with radar.liga() as c:
            radar.contas.criar_utilizador(c, "dono@miragov.pt", "senha-comprida",
                                          pela_consola=True)
            radar.contas.criar_utilizador(c, "ana@empresa.pt", "senha-comprida",
                                          "Ana", papel="tester")
            radar.contas.criar_utilizador(c, "rui", "senha-comprida", papel="tester")

    def esqueci(self, email, ambiente=None, **cabecalhos):
        return radar.app.test_client().post(
            "/esqueci-me", data={"email": email},
            environ_base=ambiente or self.FORA, headers=cabecalhos)

    def _codigo_do_email(self):
        self.assertEqual(len(self.mandados), 1)
        return re.search(r"/repor/([\w-]+)", self.mandados[0]["texto"]).group(1)

    def test_o_esqueci_me_manda_uma_ligacao_de_uma_hora_e_uso_unico(self):
        self._prepara_o_correio()
        ana = radar.app.test_client()       # uma sessão da Ana, já aberta
        self.assertEqual(ana.post("/entrar", data={
            "email": "ana@empresa.pt", "senha": "senha-comprida"},
            environ_base=self.FORA).status_code, 302)
        r = self.esqueci("  Ana@Empresa.pt ")
        self.assertEqual(r.status_code, 200)
        codigo = self._codigo_do_email()
        self.assertEqual(self.mandados[0]["para"], "ana@empresa.pt")
        # o e-mail é o da casa: em HTML, com o botão, e diz o prazo
        self.assertIn("/repor/" + codigo, self.mandados[0]["html"])
        self.assertIn("Escolher a palavra-passe nova", self.mandados[0]["html"])
        # só o resumo na base, e vale uma hora
        with radar.liga() as c:
            linha = c.execute("SELECT * FROM reposicoes").fetchone()
        self.assertNotEqual(linha["resumo"], codigo)
        criado = datetime.datetime.strptime(linha["criado_em"], "%Y-%m-%d %H:%M:%S")
        expira = datetime.datetime.strptime(linha["expira"], "%Y-%m-%d %H:%M:%S")
        self.assertEqual(expira - criado, datetime.timedelta(hours=1))
        fora = radar.app.test_client()
        r = fora.post("/repor/" + codigo, data={"senha": "outra-chave-boa",
                                                "outra": "outra-chave-boa"},
                      environ_base=self.FORA)
        self.assertEqual(r.status_code, 302)
        # a sessão que estava aberta caiu; e a ligação gastou-se
        self.assertEqual(ana.get("/concursos", environ_base=self.FORA).status_code, 302)
        r = radar.app.test_client().post(
            "/repor/" + codigo, data={"senha": "terceira-chave-boa",
                                      "outra": "terceira-chave-boa"},
            environ_base=self.FORA)
        self.assertEqual(r.status_code, 410)

    def test_a_resposta_e_a_mesma_exista_ou_nao_a_conta(self):
        """Não se enumera: o estado, o texto e os cabeçalhos que contam
        são iguais para uma conta que existe, uma que não existe, uma
        que entra por nome de utilizador e a do dono."""
        self._prepara_o_correio()
        respostas = {}
        for email in ("ana@empresa.pt", "ninguem@empresa.pt", "rui@x.pt",
                      "dono@miragov.pt"):
            r = self.esqueci(email, ambiente={"REMOTE_ADDR": "198.51.100.%d"
                                              % len(respostas)})
            corpo = r.get_data(as_text=True).replace(html.escape(email), "EMAIL")
            respostas[email] = (r.status_code, corpo,
                                r.headers.get("Set-Cookie"))
        self.assertEqual(len(set(respostas.values())), 1, respostas.keys())
        self.assertEqual(respostas["rui@x.pt"][0], 200)
        # e só a da Ana recebeu
        self.assertEqual([m["para"] for m in self.mandados], ["ana@empresa.pt"])

    def test_a_conta_do_dono_nao_se_repoe_por_aqui(self):
        """O dono tem o segundo factor e repõe-se pela consola: uma
        ligação por e-mail para a conta mais poderosa era a porta do
        lado. Nada se cria, nada sai -- e fica escrito que alguém
        pediu."""
        self._prepara_o_correio()
        self.assertEqual(self.esqueci("dono@miragov.pt").status_code, 200)
        self.assertEqual(self.mandados, [])
        with radar.liga() as c:
            self.assertEqual(c.execute("SELECT COUNT(*) FROM reposicoes").fetchone()[0], 0)
            eventos = [r[0] for r in c.execute("SELECT detalhe FROM eventos")]
        self.assertTrue(any("dono" in e for e in eventos), eventos)

    def test_um_post_de_outro_sitio_e_recusado(self):
        self._prepara_o_correio()
        r = self.esqueci("ana@empresa.pt", Origin="https://mal.exemplo")
        self.assertEqual(r.status_code, 403)
        self.assertEqual(self.mandados, [])
        # e do próprio sítio passa
        r = self.esqueci("ana@empresa.pt", Origin="http://localhost")
        self.assertEqual(r.status_code, 200)
        self.assertEqual(len(self.mandados), 1)

    def test_o_tecto_e_por_ip_e_por_conta_e_nao_fecha_o_entrar(self):
        self._prepara_o_correio()
        n = radar.contas.FALHAS_ATE_TRINCO
        # o mesmo IP, endereços diferentes: o IP fecha
        for i in range(n):
            self.assertEqual(self.esqueci("x%d@empresa.pt" % i).status_code, 200)
        r = self.esqueci("ana@empresa.pt")
        self.assertEqual(r.status_code, 429)
        self.assertIn("demasiadas tentativas", r.get_data(as_text=True).lower())
        self.assertEqual(self.mandados, [])
        # IPs diferentes, a mesma conta: a conta fecha (não se enche a
        # caixa de ninguém por muitos IP)
        for i in range(n):
            self.esqueci("ana@empresa.pt", ambiente={"REMOTE_ADDR": "198.51.100.%d" % i})
        self.assertEqual(len(self.mandados), n)
        r = self.esqueci("ana@empresa.pt", ambiente={"REMOTE_ADDR": "198.51.100.99"})
        self.assertEqual(r.status_code, 429)
        self.assertEqual(len(self.mandados), n)
        # e nada disto conta no trinco do /entrar, do IP nem da conta
        r = radar.app.test_client().post("/entrar", data={
            "email": "ana@empresa.pt", "senha": "senha-comprida"},
            environ_base=self.FORA)
        self.assertEqual(r.status_code, 302)

    def test_o_codigo_nao_fica_em_registo_nenhum(self):
        """Nem nos eventos, nem nas falhas, nem nos erros -- e um 500 na
        ligação de repor não escreve o caminho com o código."""
        self._prepara_o_correio()
        self.esqueci("ana@empresa.pt")
        codigo = self._codigo_do_email()
        with unittest.mock.patch.object(radar.contas, "reposicao_valida",
                                        side_effect=RuntimeError("avaria")):
            r = radar.app.test_client().get("/repor/" + codigo, environ_base=self.FORA)
        self.assertEqual(r.status_code, 500)
        with radar.liga() as c:
            tabelas = [r[0] for r in c.execute(
                "SELECT name FROM sqlite_master WHERE type='table' "
                "AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '%fts%'")]
            for tabela in tabelas:
                for linha in c.execute("SELECT * FROM %s" % tabela):
                    self.assertNotIn(codigo, " ".join(str(v) for v in linha), tabela)
            self.assertTrue(c.execute("SELECT 1 FROM erros").fetchone())

    def test_a_entrada_leva_ao_esqueci_me(self):
        cliente = radar.app.test_client()
        corpo = cliente.get("/entrar", environ_base=self.FORA).get_data(as_text=True)
        self.assertIn("href=\"/esqueci-me\"", corpo)
        r = cliente.get("/esqueci-me", environ_base=self.FORA)
        self.assertEqual(r.status_code, 200)
        self.assertIn("name=\"email\"", r.get_data(as_text=True))


class TestNenhumaEmpresaVeAOutra(BaseTemporaria):
    """O teste central da F4 do plano multi-empresa (23/09/2026): com a
    sessão da empresa A, percorre TODAS as páginas — as sem parâmetros,
    tiradas do `url_map` como no `TestNenhumEcraDa500`, e as do concurso,
    da proposta e da entidade que a B trabalha — e exige que nenhum dado
    da B apareça. Cada dado da B leva uma marca que não existe em mais
    lado nenhum; se uma aparecer, o erro diz qual e em que página.

    E as portas: quem não é dono não abre o que é do sistema, e um admin
    não vê nem tira as contas de outra empresa."""

    FORA = {"REMOTE_ADDR": "203.0.113.7"}
    MARCAS_DA_B = ("TITULO-B-SEGREDO", "NOTA-B-SEGREDO", "CONTACTO-B-SEGREDO",
                   "contacto-b@segredo.pt", "TAREFA-B-SEGREDO", "HIST-B-SEGREDO",
                   "PESSOA-B-SEGREDO", "ALERTA-B-SEGREDO", "ETIQ-B-SEGREDO",
                   "b-resumo@segredo.pt", "EMPRESA-B-SEGREDO", "conta-b-segredo")
    LENTAS = ("/contratos/resumo",)

    def setUp(self):
        super().setUp()
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, entidade, data_pub, "
                      "estado) VALUES ('900/2026', 'Software', 'Município', "
                      "'2026-09-01', 'novo')")
            radar.contas.criar_utilizador(c, "admin", "senha-comprida",
                pela_consola=True)      # A, dono
            radar.contas.criar_utilizador(c, "teste", "senha-comprida", papel="tester")
        self.b = radar.criar_empresa("EMPRESA-B-SEGREDO")
        with radar.com_empresa(self.b):
            self.proposta_b = radar.criar_proposta(
                "900/2026", titulo="TITULO-B-SEGREDO", estado="proposta",
                quem="PESSOA-B-SEGREDO")
            with radar.liga() as c:
                c.execute("UPDATE propostas SET responsavel='PESSOA-B-SEGREDO'")
                # as notas são linhas datadas desde 26/09/2026 (D3)
                c.execute("INSERT INTO notas_da_proposta (proposta_id, texto) "
                          "SELECT id, 'NOTA-B-SEGREDO' FROM propostas")
                c.execute("INSERT INTO contactos (entidade_chave, entidade, nome, "
                          "email) VALUES ('n:municipio', 'Município', "
                          "'CONTACTO-B-SEGREDO', 'contacto-b@segredo.pt')")
                c.execute("INSERT INTO tarefas (ref, o_que, quem, quando) VALUES "
                          "('900/2026', 'TAREFA-B-SEGREDO', 'PESSOA-B-SEGREDO', "
                          "'2026-09-30')")
                c.execute("INSERT INTO historico (ref, quem, accao, detalhe, quando) "
                          "VALUES ('900/2026', 'PESSOA-B-SEGREDO', 'estado', "
                          "'HIST-B-SEGREDO', '2026-09-02 10:00')")
                c.execute("INSERT OR IGNORE INTO pessoas (nome) VALUES ('PESSOA-B-SEGREDO')")
                c.execute("INSERT INTO filtros_guardados (nome, consulta, alerta) "
                          "VALUES ('ALERTA-B-SEGREDO', 'q=software', 1)")
                c.execute("INSERT INTO etiquetas (nome, cor) VALUES "
                          "('ETIQ-B-SEGREDO', '#c0392b')")
            radar.gravar_config({"email": {"para": "b-resumo@segredo.pt"}})
            # uma leitura pedida por alguém da B: o evento é da plataforma,
            # mas o nome de quem a pediu é da B
            radar.registar_evento("900/2026", "leitura", "peças lidas",
                                  quem="conta-b-segredo")
        with radar.liga() as c:
            radar.contas.criar_utilizador(c, "conta-b-segredo", "senha-comprida",
                                          papel="admin", empresa_id=self.b)

    def entrar(self, quem):
        cliente = radar.app.test_client()
        r = cliente.post("/entrar", data={"email": quem, "senha": "senha-comprida"},
                         environ_base=self.FORA)
        self.assertEqual(r.status_code, 302)
        return cliente

    def _caminhos(self):
        simples = sorted({r.rule for r in radar.app.url_map.iter_rules()
                          if "GET" in (r.methods or ()) and "<" not in r.rule
                          and r.rule not in self.LENTAS})
        return simples + ["/anuncio/900/2026", "/proposta/%d" % self.proposta_b,
                          "/entidade/n:municipio", radar.LISTA + "?estado=proposta",
                          "/configuracoes/conta", "/configuracoes/alertas"]

    def test_a_empresa_a_nao_ve_nada_da_b_em_pagina_nenhuma(self):
        for quem in ("admin", "teste"):
            cliente = self.entrar(quem)
            fugas = []
            for caminho in self._caminhos():
                corpo = cliente.get(caminho, environ_base=self.FORA).get_data()
                corpo = corpo.decode("utf-8", "replace")    # ha fontes e icones
                fugas += [(quem, caminho, m) for m in self.MARCAS_DA_B if m in corpo
                          # a lista das empresas da administracao da
                          # plataforma diz que a B existe, e como se chama:
                          # o dono tem de o saber. O trabalho dela, nao.
                          and not (quem == "admin" and caminho == "/plataforma"
                                   and m == "EMPRESA-B-SEGREDO")
                          # e as contas, com o repor (D17, 26/09/2026): o
                          # dono repõe a palavra-passe de qualquer uma
                          and not (quem == "admin" and caminho == "/plataforma"
                                   and m == "conta-b-segredo")]
            self.assertEqual(fugas, [])
            self.assertGreater(len(self._caminhos()), 20)

    def test_a_b_ve_o_que_e_dela(self):
        """O teste de cima só vale se as marcas aparecerem a quem as tem:
        senão passava igual com uma página que não mostrasse nada."""
        cliente = self.entrar("conta-b-segredo")
        corpo = cliente.get("/anuncio/900/2026", environ_base=self.FORA).get_data(as_text=True)
        self.assertIn("NOTA-B-SEGREDO", corpo)
        corpo = cliente.get("/configuracoes/conta", environ_base=self.FORA).get_data(as_text=True)
        self.assertIn("conta-b-segredo", corpo)

    def test_o_admin_da_b_nao_abre_o_que_e_do_sistema(self):
        cliente = self.entrar("conta-b-segredo")
        for rota in radar.ROTAS_SO_DONO:
            self.assertEqual(cliente.get(rota, environ_base=self.FORA).status_code,
                             403, rota)
        dono = self.entrar("admin")
        self.assertIn(dono.get("/configuracoes/recolha",
                               environ_base=self.FORA).status_code, (200, 302))

    def test_um_admin_nao_tira_contas_de_outra_empresa(self):
        with radar.liga() as c:
            id_b = c.execute("SELECT id FROM utilizadores WHERE email="
                             "'conta-b-segredo'").fetchone()[0]
            self.assertFalse(radar.contas.apagar_utilizador(c, id_b, empresa_id=1))
            self.assertTrue(c.execute("SELECT 1 FROM utilizadores WHERE id=?",
                                      (id_b,)).fetchone())

    def test_a_entrada_da_b_fica_no_historico_da_b(self):
        """Ate 23/09/2026 o /entrar, que e rota aberta e corre antes de a
        porta pôr a empresa, escrevia o «entrou» da B no historico da 1."""
        self.entrar("conta-b-segredo")
        with radar.liga() as c:
            self.assertFalse(c.execute("SELECT 1 FROM historico WHERE "
                                       "accao='entrou'").fetchone())
        with radar.com_empresa(self.b), radar.liga() as c:
            self.assertTrue(c.execute("SELECT 1 FROM historico WHERE "
                                      "accao='entrou'").fetchone())

    def test_a_empresa_da_sessao_nao_fica_pendurada_depois_do_pedido(self):
        """No cliente dos testes os pedidos correm todos na mesma thread:
        sem o `teardown_request`, a empresa da B ficava activa para o
        pedido seguinte, de outra pessoa."""
        self.entrar("conta-b-segredo").get("/", environ_base=self.FORA)
        self.assertEqual(radar.empresa_activa(), radar.EMPRESA_ACTIVA)


class TestConectorMCP(BaseTemporaria):
    """O Mira Gov como conector MCP (10/10/2026). O que se guarda, por
    ordem do desenho: uma empresa nunca vê outra pelo conector (e o teste
    prova que apanharia a fuga), o OAuth recusa o código reutilizado, o
    verifier errado, o redirect diferente e o resource alheio, o /mcp só
    aceita o bearer (nunca o cookie do painel), os tokens caem com a
    conta, e o tecto e as páginas das peças."""

    FORA = {"REMOTE_ADDR": "203.0.113.7"}
    CLAUDE = "https://claude.ai/api/mcp/auth_callback"
    VERIFIER = "v" * 50

    def setUp(self):
        super().setUp()
        import contas, mcp_servidor
        self.contas, self.mcp = contas, mcp_servidor
        self.enterContext(unittest.mock.patch.dict(mcp_servidor._FALHAS_DO_TOKEN))
        self.cliente = radar.app.test_client()
        self.base = radar.endereco_do_painel()
        paginas = "\n\f\n".join("texto da pagina %d" % n for n in range(1, 31))
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, titulo_norm, entidade, "
                      "data_pub, prazo, estado, distrito, preco_base, cpv, texto) "
                      "VALUES ('900/2026', 'Limpeza de escolas', 'limpeza de escolas', "
                      "'Município de Lisboa', '2026-10-05', '2099-01-01', 'novo', "
                      "'|Lisboa|', '100.000,00 EUR', '90910000-9', "
                      "'<b>Anúncio</b> com\x07 lixo')")
            c.execute("INSERT INTO documentos (ref, nome, texto, texto_estado) "
                      "VALUES ('900/2026', 'Programa.pdf', ?, 'ok')", (paginas,))
            self.dono = self.contas.criar_utilizador(c, "dono@mira.pt", "senha-comprida",
                                                     pela_consola=True)
            self.ana = self.contas.criar_utilizador(c, "ana@a.pt", "senha-comprida",
                                                    papel="tester")
        self.proposta_a = radar.criar_proposta("900/2026", titulo="TITULO-A",
                                               estado="proposta")
        radar.gravar_nota(self.proposta_a, "NOTA-A-SEGREDO")
        self.b = radar.criar_empresa("EMPRESA-B")
        with radar.com_empresa(self.b):
            # cada empresa conta as propostas no seu ficheiro: sem esta, a
            # da B era a n.º 1, como a da A, e pedir a «da B» devolvia a
            # da A -- o teste passava sem provar nada
            radar.criar_proposta("", titulo="outra da B", estado="analisar")
            self.proposta_b = radar.criar_proposta("900/2026", titulo="TITULO-B-SEGREDO",
                                                   estado="ganho")
        self.assertNotEqual(self.proposta_a, self.proposta_b)
        with radar.liga() as c:
            self.bruno = self.contas.criar_utilizador(c, "bruno@b.pt", "senha-comprida",
                                                      papel="admin", empresa_id=self.b)

    # -- o caminho do OAuth, sem o ecrã (que é HTML e fica para o D1)

    @classmethod
    def desafio(cls, verifier=None):
        import base64, hashlib
        return base64.urlsafe_b64encode(hashlib.sha256(
            (verifier or cls.VERIFIER).encode()).digest()).decode().rstrip("=")

    def registar(self, redirects=None):
        r = self.cliente.post("/oauth/register", json={
            "client_name": "Claude", "redirect_uris": redirects or [self.CLAUDE]},
            environ_base=self.FORA)
        return r

    def codigo(self, utilizador_id, client_id=None, **mais):
        client_id = client_id or self.registar().get_json()["client_id"]
        with radar.liga() as c:
            u = dict(c.execute("SELECT * FROM utilizadores WHERE id=?",
                               (utilizador_id,)).fetchone())
            args = dict({"response_type": "code", "client_id": client_id,
                         "redirect_uri": self.CLAUDE, "code_challenge": self.desafio(),
                         "code_challenge_method": "S256", "state": "xyz",
                         "resource": self.base + "/mcp"}, **mais)
            pedido, erro = self.mcp.validar_autorizacao(c, args, u, self.base)
            self.assertIsNone(erro)
            volta = self.mcp.emitir_codigo(c, pedido, u, self.base)
        q = dict(parse_qsl(urlparse(volta).query))
        self.assertEqual((q["state"], q["iss"]), ("xyz", self.base))
        return q["code"], client_id

    def trocar(self, codigo, client_id, **mais):
        return self.cliente.post("/oauth/token", data=dict({
            "grant_type": "authorization_code", "code": codigo,
            "client_id": client_id, "redirect_uri": self.CLAUDE,
            "code_verifier": self.VERIFIER, "resource": self.base + "/mcp"}, **mais),
            environ_base=self.FORA)

    def tokens(self, utilizador_id):
        r = self.trocar(*self.codigo(utilizador_id))
        self.assertEqual(r.status_code, 200, r.get_data(as_text=True))
        return r.get_json()

    def mcp_pede(self, token, metodo="initialize", params=None, **kw):
        cabecalhos = kw.pop("headers", {})
        if token:
            cabecalhos["Authorization"] = "Bearer " + token
        return (kw.pop("cliente", None) or self.cliente).post(
            "/mcp", json={"jsonrpc": "2.0", "id": 1, "method": metodo,
                          "params": params or {}},
            headers=cabecalhos, environ_base=kw.pop("environ_base", self.FORA))

    def chamar(self, token, nome, **argumentos):
        r = self.mcp_pede(token, "tools/call", {"name": nome, "arguments": argumentos})
        self.assertEqual(r.status_code, 200, r.get_data(as_text=True))
        return r.get_json()["result"]

    # -- os metadados e o 401

    def test_os_metadados_dizem_o_recurso_e_o_s256(self):
        r = self.cliente.get("/.well-known/oauth-protected-resource", environ_base=self.FORA)
        self.assertEqual(r.get_json()["resource"], self.base + "/mcp")
        self.assertEqual(r.get_json()["authorization_servers"], [self.base])
        m = self.cliente.get("/.well-known/oauth-authorization-server",
                             environ_base=self.FORA).get_json()
        self.assertEqual(m["code_challenge_methods_supported"], ["S256"])
        self.assertEqual(m["token_endpoint_auth_methods_supported"], ["none"])
        self.assertEqual(m["registration_endpoint"], self.base + "/oauth/register")

    def test_o_mcp_sem_bearer_da_401_com_o_cabecalho_certo(self):
        r = self.mcp_pede(None)
        self.assertEqual(r.status_code, 401)
        self.assertEqual(r.headers["WWW-Authenticate"],
                         'Bearer resource_metadata="%s/.well-known/oauth-protected-'
                         'resource"' % self.base)
        r = self.mcp_pede("inventado")
        self.assertEqual(r.status_code, 401)
        self.assertIn('error="invalid_token"', r.headers["WWW-Authenticate"])

    def test_o_cookie_do_painel_e_o_acesso_livre_nao_servem(self):
        painel = radar.app.test_client()
        r = painel.post("/entrar", data={"email": "ana@a.pt", "senha": "senha-comprida"},
                        environ_base=self.FORA)
        self.assertEqual(r.status_code, 302)
        self.assertEqual(self.mcp_pede(None, cliente=painel).status_code, 401)
        # o computador do Afonso entra sem palavra-passe no painel; no
        # conector, não
        self.assertEqual(self.mcp_pede(None, environ_base={"REMOTE_ADDR": "127.0.0.1"})
                         .status_code, 401)

    def test_get_e_delete_dao_405_e_um_origin_alheio_403(self):
        t = self.tokens(self.ana)["access_token"]
        for metodo in ("get", "delete"):
            r = getattr(self.cliente, metodo)("/mcp", environ_base=self.FORA,
                                              headers={"Authorization": "Bearer " + t})
            self.assertEqual(r.status_code, 405, metodo)
        r = self.mcp_pede(t, headers={"Origin": "https://mal.example"})
        self.assertEqual(r.status_code, 403)

    def test_initialize_e_as_nove_ferramentas_so_de_leitura(self):
        t = self.tokens(self.ana)["access_token"]
        r = self.mcp_pede(t, params={"protocolVersion": "2025-06-18"})
        self.assertEqual(r.get_json()["result"]["protocolVersion"], "2025-06-18")
        ferramentas = self.mcp_pede(t, "tools/list").get_json()["result"]["tools"]
        self.assertEqual({f["name"] for f in ferramentas}, set(self.mcp.EXECUTORES))
        self.assertEqual(len(ferramentas), 9)
        for f in ferramentas:
            self.assertTrue(f["annotations"]["readOnlyHint"], f["name"])
            self.assertFalse(f["inputSchema"]["additionalProperties"])
            # nenhuma recebe o número da empresa
            self.assertFalse([p for p in f["inputSchema"]["properties"]
                              if "empresa" in p], f["name"])
        # e um «empresa» enfiado no pedido não chega a lado nenhum
        r = self.chamar(t, "listar_propostas", empresa=self.b)
        self.assertTrue(r["isError"])
        # uma notificação não tem resposta
        r = self.cliente.post("/mcp", json={"jsonrpc": "2.0",
                                            "method": "notifications/initialized"},
                              headers={"Authorization": "Bearer " + t},
                              environ_base=self.FORA)
        self.assertEqual(r.status_code, 202)

    # -- uma empresa nunca vê outra

    def test_a_empresa_a_nao_ve_a_proposta_da_b(self):
        t = self.tokens(self.ana)["access_token"]
        r = self.chamar(t, "ver_proposta", id=self.proposta_b)
        self.assertTrue(r["isError"])
        self.assertNotIn("TITULO-B-SEGREDO", json.dumps(r))
        for nome, args in (("listar_propostas", {}), ("pesquisar", {"q": "TITULO"}),
                           ("ver_concurso", {"ref": "900/2026"}),
                           ("situacao", {"periodo": "tudo"})):
            corpo = json.dumps(self.chamar(t, nome, **args), ensure_ascii=False)
            self.assertNotIn("TITULO-B-SEGREDO", corpo, nome)
        self.assertIn("TITULO-A", json.dumps(self.chamar(t, "listar_propostas")))
        # e ao contrário: a A é a empresa de omissão, e um `com_empresa()`
        # esquecido só se vê do lado da B
        t = self.tokens(self.bruno)["access_token"]
        corpo = json.dumps(self.chamar(t, "listar_propostas"), ensure_ascii=False)
        self.assertIn("TITULO-B-SEGREDO", corpo)
        self.assertNotIn("TITULO-A", corpo)
        # o n.º 1 da B existe e é outra proposta: a da A não aparece
        self.assertNotIn("TITULO-A", json.dumps(
            self.chamar(t, "ver_proposta", id=self.proposta_a), ensure_ascii=False))

    def test_com_a_empresa_forcada_a_b_o_teste_apanha_a_fuga(self):
        """O teste de cima só vale se falhar quando se estraga de
        propósito: com o token e a conta postos na B, a mesma pergunta vê
        a proposta da B -- a empresa vem mesmo do token. Com só o token
        forçado (a conta ficou na A), a conta reconfirmada recusa-o."""
        t = self.tokens(self.ana)["access_token"]
        with radar.liga() as c:
            c.execute("UPDATE tokens_mcp SET empresa_id=?", (self.b,))
        self.assertEqual(self.mcp_pede(t).status_code, 401)
        t = self.tokens(self.ana)["access_token"]
        with radar.liga() as c:
            c.execute("UPDATE tokens_mcp SET empresa_id=? WHERE revogado_em IS NULL",
                      (self.b,))
            c.execute("UPDATE utilizadores SET empresa_id=? WHERE id=?",
                      (self.b, self.ana))
        r = self.chamar(t, "ver_proposta", id=self.proposta_b)
        self.assertIn("TITULO-B-SEGREDO", json.dumps(r, ensure_ascii=False))

