class TestOsPedidosDizemOTempo(BaseTemporaria):
    """Lote 4 (26/09/2026): sem um relogio no servidor, o teste de
    desempenho teve de adivinhar pela forma dos numeros onde se gastava
    o tempo. O `Server-Timing` separa a base do resto."""

    def test_o_cabecalho_vem_com_a_base_e_o_total(self):
        r = radar.app.test_client().get("/concursos")
        st = r.headers.get("Server-Timing", "")
        self.assertRegex(st, r"^base;dur=\d+\.\d, total;dur=\d+\.\d$")
        base, total = [float(x) for x in re.findall(r"dur=([\d.]+)", st)]
        self.assertGreater(base, 0)
        self.assertLessEqual(base, total)


class TestOClienteNaoDescarregaODesnecessario(BaseTemporaria):
    """Lote 4 (26/09/2026), do teste de desempenho: o `/cpv.json`
    voltava a descarregar 143 KB em cada visita, as fontes do texto nao
    vinham pre-carregadas (o Hoje saltava 31 px), e as paginas de uma
    peca nao tinham tamanho (o `loading=lazy` trazia as 42 de uma vez)."""

    def test_o_cpv_json_responde_304_com_a_mesma_etiqueta(self):
        cliente = radar.app.test_client()
        r = cliente.get("/cpv.json?de=anuncios")
        self.assertEqual(r.status_code, 200)
        etiqueta = r.headers.get("ETag")
        self.assertTrue(etiqueta)
        self.assertIn("private", r.headers.get("Cache-Control", ""))
        r2 = cliente.get("/cpv.json?de=anuncios",
                         headers={"If-None-Match": etiqueta})
        self.assertEqual(r2.status_code, 304)
        self.assertEqual(r2.get_data(), b"")
        # um anuncio novo lido muda a etiqueta
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, detalhe_lido, cpv)"
                      " VALUES ('1/2026', 'x', 1, '72000000-5')")
        r3 = cliente.get("/cpv.json?de=anuncios",
                         headers={"If-None-Match": etiqueta})
        self.assertEqual(r3.status_code, 200)
        self.assertNotEqual(r3.headers.get("ETag"), etiqueta)

    def test_as_fontes_do_texto_vem_pre_carregadas(self):
        corpo = radar.app.test_client().get("/concursos").get_data(as_text=True)
        for nome in radar.FONTES_PRE_CARREGADAS:
            self.assertIn(nome, radar.TIPOS)
            self.assertIn('<link rel="preload" href="/tipo/%s" as="font" '
                          'type="font/woff2" crossorigin>' % nome, corpo)
        # e a folha ja nao declara letras que nada usa
        for morta in ("Inter", "Plex Sans", "Plex Mono"):
            self.assertNotIn("font-family:'%s'" % morta, radar.CSS_TUDO)

    def test_as_paginas_da_peca_levam_largura_e_altura(self):
        libs = os.path.join(os.path.dirname(os.path.abspath(radar.__file__)),
                            "libs")
        if os.path.isdir(libs) and libs not in sys.path:
            sys.path.append(libs)
        try:
            import pymupdf
        except ImportError:
            self.skipTest("sem pymupdf no Python dos testes")
        caminho = os.path.join(self.pasta, "ensaio.pdf")
        doc = pymupdf.open()
        doc.new_page(width=595, height=842)
        doc.new_page(width=842, height=595)       # uma ao alto, outra deitada
        doc.save(caminho)
        doc.close()
        self.assertEqual(radar.tamanhos_das_paginas(caminho),
                         [(1190, 1684), (1684, 1190)])
        self.assertEqual(radar.tamanhos_das_paginas("nao-existe.pdf"), [])
        with radar.app.test_request_context("/"):
            _, corpo = radar.visualizador_de_peca(
                "1/2026", "ensaio.pdf", caminho, "/documento/x", "", "/")
        self.assertIn("loading='lazy' width='1190' height='1684'", corpo)
        self.assertIn("width='1684' height='1190'", corpo)
        self.assertIn("height:auto",
                      radar.CSS_TUDO.split(".peca-pag{")[1][:80])

    def test_sexta_ronda_a_peca_no_telemovel_corre_com_a_pagina(self):
        """6.ª ronda (5/10/2026, perfil 9): no Android a folha tinha 254 px
        numa caixa a rolar dentro da página. Abaixo de 600 px a caixa e as
        margens saem, e dentro da ficha há a ligação para a peça inteira."""
        try:
            import pymupdf
        except ImportError:
            self.skipTest("sem pymupdf no Python dos testes")
        caminho = os.path.join(self.pasta, "ensaio.pdf")
        doc = pymupdf.open()
        doc.new_page(width=595, height=842)
        doc.save(caminho)
        doc.close()
        with radar.app.test_request_context("/"):
            _, na_ficha = radar.visualizador_de_peca(
                "1/2026", "ensaio.pdf", caminho, "/documento/x", "",
                "/anuncio/1%2F2026", ocultos={"peca": "ensaio.pdf"})
            _, na_propria = radar.visualizador_de_peca(
                "1/2026", "ensaio.pdf", caminho, "/documento/x", "", "/peca/1/2026/x")
        self.assertIn("<a class='peca-inteira' href='/peca/1/2026/ensaio.pdf'>", na_ficha)
        self.assertNotIn("peca-inteira", na_propria)
        movel = radar.CSS_TUDO.split(".peca-inteira{display:none}", 1)[1][:200]
        self.assertIn(".leitor .peca-folhas{max-height:none;overflow:visible", movel)



class TestAEmpresaActivaNaBarra(BaseTemporaria):
    """D7 da segunda ronda (26/09/2026, decisão dele): com mais de uma
    empresa na plataforma, a barra não dizia em qual se estava. O perigo
    é triar ou gravar na empresa errada sem dar por isso -- e o único
    sinal era o conteúdo das listas."""

    FORA = {"REMOTE_ADDR": "203.0.113.7"}

    def _barra(self):
        with radar.liga() as c:
            radar.contas.criar_utilizador(c, "admin", "senha-comprida",
                pela_consola=True)   # o dono
            radar.contas.criar_utilizador(c, "ana", "senha-comprida",
                                          papel="admin", empresa_id=1)
        cliente = radar.app.test_client()
        cliente.post("/entrar", data={"email": "ana", "senha": "senha-comprida"},
                     environ_base=self.FORA)
        return (cliente.get("/", environ_base=self.FORA)
                .get_data(as_text=True).split("</header>")[0])

    def test_o_nome_da_empresa_esta_ao_lado_de_quem_entrou(self):
        radar.gravar_config({"nome_da_empresa": "Construções <Exemplo>"})
        barra = self._barra()
        self.assertIn("class='sou-empresa'", barra)
        self.assertIn("Construções &lt;Exemplo&gt;", barra)   # escapado

    def test_sem_nome_diz_o_numero(self):
        self.assertIn(">Empresa 1</small>", self._barra())

    def test_o_dono_sem_empresa_nao_tem_empresa_na_barra(self):
        with radar.com_empresa(radar.SEM_EMPRESA):
            self.assertEqual(radar.nome_da_empresa_activa(), "")


class TestPorAEmpresaATrabalhar(BaseTemporaria):
    """D13 da segunda ronda (26/09/2026, decisão dele): a empresa nova
    entrava a ver 1 383 anúncios por decidir, sem perfil, sem alerta e
    sem ninguém a dizer por onde começar. O cartão do Hoje tem quatro
    passos riscados PELOS DADOS -- um passo desfeito volta a aparecer --,
    e sai quando estão todos feitos ou quando o admin o dispensa."""

    def hoje(self):
        return radar.app.test_client().get("/").get_data(as_text=True)

    def test_os_quatro_passos_riscam_se_pelos_dados(self):
        corpo = self.hoje()
        self.assertIn("Pôr a empresa a trabalhar", corpo)
        self.assertIn("0 de 4 feitos", corpo)
        for alvo in ("/configuracoes/interesse", "/configuracoes/conta#empresa",
                     "/configuracoes/alertas#do-perfil",
                     "/configuracoes/conta#convidar"):
            self.assertIn("href='%s'" % alvo, corpo)
        radar.gravar_config({"interesse_activo": True,
                             "interesse_cpv": "45000000"})
        corpo = self.hoje()
        self.assertIn("<s>Perfil da empresa</s>", corpo)
        self.assertIn("1 de 4 feitos", corpo)
        # só o nome não chega: o NIF é o que liga os contratos
        radar.gravar_config({"nome_da_empresa": "Exemplo"})
        self.assertIn("1 de 4 feitos", self.hoje())
        radar.gravar_config({"nif_da_empresa": "503504564"})
        # com metade feita, o cartão encurta: só os que faltam, uma linha
        # cada (ronda em PC, V3 P4) -- o feito já não se desenha
        corpo = self.hoje()
        self.assertIn("2 de 4 feitos; faltam 2", corpo)
        self.assertIn("arranque-curto", corpo)
        self.assertNotIn("href='/configuracoes/conta#empresa'", corpo)
        self.assertIn("href='/configuracoes/alertas#do-perfil'", corpo)
        radar.app.test_client().post("/alertas/do-perfil")
        corpo = self.hoje()
        self.assertIn("3 de 4 feitos; falta 1", corpo)
        self.assertNotIn("href='/configuracoes/alertas#do-perfil'", corpo)
        # o convite do pedido de acesso (o do próprio admin) não conta
        with radar.liga() as c:
            radar.contas.criar_convite(c, 1, "eu@x.pt", "admin", pedido_id=7)
        self.assertIn("3 de 4 feitos", self.hoje())
        with radar.liga() as c:
            radar.contas.criar_convite(c, 1, "colega@x.pt", "tester")
        self.assertNotIn("Pôr a empresa a trabalhar", self.hoje())
        # e um passo desfeito volta a pôr o cartão
        radar.gravar_config({"interesse_activo": False, "interesse_cpv": ""})
        self.assertIn("3 de 4 feitos", self.hoje())

    def test_dispensa_se(self):
        r = radar.app.test_client().post("/arranque/dispensar")
        self.assertEqual(r.status_code, 302)
        self.assertNotIn("Pôr a empresa a trabalhar", self.hoje())

    def test_o_tester_nao_o_ve_nem_o_dispensa(self):
        fora = {"REMOTE_ADDR": "203.0.113.7"}
        with radar.liga() as c:
            radar.contas.criar_utilizador(c, "admin", "senha-comprida")
            radar.contas.criar_utilizador(c, "rui", "senha-comprida",
                                          papel="tester", empresa_id=1)
        cliente = radar.app.test_client()
        cliente.post("/entrar", data={"email": "rui", "senha": "senha-comprida"},
                     environ_base=fora)
        corpo = cliente.get("/", environ_base=fora).get_data(as_text=True)
        self.assertNotIn("Pôr a empresa a trabalhar", corpo)
        token = re.search(r"<meta name=\"csrf\" content=\"([0-9a-f]+)\"", corpo).group(1)
        r = cliente.post("/arranque/dispensar", data={"csrf": token},
                         environ_base=fora)
        self.assertEqual(r.status_code, 403)

    def test_o_alerta_do_perfil_leva_o_perfil_inteiro(self):
        radar.gravar_config({"interesse_activo": True,
                             "interesse_cpv": "45000000|71000000",
                             "interesse_cpv_excl": "45100000",
                             "interesse_distritos": "Porto|Braga",
                             "interesse_pbmin": "20 000"})
        r = radar.app.test_client().post("/alertas/do-perfil")
        self.assertIn("criado", unquote(r.headers["Location"]))
        with radar.liga() as c:
            f = c.execute("SELECT nome, consulta, alerta FROM filtros_guardados"
                          ).fetchall()
        self.assertEqual(len(f), 1)
        self.assertEqual((f[0]["nome"], f[0]["alerta"]),
                         (radar.NOME_DO_ALERTA_DO_PERFIL, 1))
        consulta = dict(parse_qsl(f[0]["consulta"]))
        self.assertEqual(consulta, {"cpv": "45000000|71000000",
                                    "cpv_excl": "45100000",
                                    "dist": "Porto|Braga", "pbmin": "20 000"})
        # e o motor dos anúncios lê todos: nenhum cai em silêncio
        self.assertEqual(radar.filtro_para(f[0]["consulta"], "anuncios")[1], [])
        # outra vez actualiza, não duplica
        radar.app.test_client().post("/alertas/do-perfil")
        with radar.liga() as c:
            self.assertEqual(c.execute("SELECT COUNT(*) FROM filtros_guardados"
                                       ).fetchone()[0], 1)

    def test_sem_perfil_nao_cria_alerta_nenhum(self):
        r = radar.app.test_client().post("/alertas/do-perfil")
        q = dict(parse_qsl(urlparse(r.headers["Location"]).query))
        self.assertEqual(q.get("tom"), "erro")
        with radar.liga() as c:
            self.assertEqual(c.execute("SELECT COUNT(*) FROM filtros_guardados"
                                       ).fetchone()[0], 0)
        corpo = radar.app.test_client().get("/configuracoes/alertas").get_data(as_text=True)
        self.assertIn("id='do-perfil'", corpo)
        self.assertNotIn("/alertas/do-perfil", corpo)      # sem perfil, sem botão


class TestODonoPreparaOPerfilAoAceitar(BaseTemporaria):
    """D13 (iii), 26/09/2026: o site promete «configuramos o perfil
    consigo», e o «aceitar» criava a empresa sem perfil nenhum. Passou a
    ser um passo com o perfil pré-preenchido do sector e da mensagem,
    que o dono afina antes de aceitar. O POST sem perfil continua a
    servir (os testes da F5, em TestConvites)."""

    FORA = {"REMOTE_ADDR": "203.0.113.7"}

    def setUp(self):
        super().setUp()
        with radar.liga() as c:
            radar.contas.criar_utilizador(c, "admin", "senha-comprida",
                pela_consola=True)   # o dono
            c.execute("INSERT INTO pedidos_acesso (criado_em, nome, empresa, "
                      "email, sector, mensagem) VALUES ('2026-09-26 10:00', 'Ana', "
                      "'Obras do Norte', 'ana@exemplo.pt', "
                      "'Obras públicas e construção', "
                      "'Fazemos obra no Porto e em Braga, e fiscalização 71520000.')")
            self.pedido = c.execute("SELECT MAX(id) FROM pedidos_acesso").fetchone()[0]
        self.enterContext(unittest.mock.patch.object(
            radar, "enviar_email", return_value=(True, "enviado")))
        self.cliente = radar.app.test_client()
        self.cliente.post("/entrar", data={"email": "admin", "senha": "senha-comprida"},
                          environ_base=self.FORA)
        self.url = "/pedidos-de-acesso/%d/aceitar" % self.pedido

    def token(self):
        corpo = self.cliente.get(self.url, environ_base=self.FORA).get_data(as_text=True)
        return re.search(r"<meta name=\"csrf\" content=\"([0-9a-f]+)\"", corpo).group(1)

    def test_o_formulario_vem_pre_preenchido_do_sector_e_da_mensagem(self):
        self.assertEqual(radar.perfil_do_pedido(
            {"sector": "Obras públicas e construção",
             "mensagem": "Fazemos obra no Porto e em Braga, e fiscalização 71520000."}),
            ("45000000|71520000", "Braga|Porto"))
        corpo = self.cliente.get(self.url, environ_base=self.FORA).get_data(as_text=True)
        self.assertIn("value='45000000|71520000'", corpo)
        self.assertIn("value='Porto' checked", corpo)
        self.assertNotIn("value='Lisboa' checked", corpo)
        # abrir o formulário não cria nada
        self.assertEqual(radar.empresas_existentes(), [1])
        # e a lista dos pedidos leva a ele, e não a um POST às cegas
        lista = self.cliente.get("/pedidos-de-acesso", environ_base=self.FORA).get_data(as_text=True)
        self.assertIn("href='%s'" % self.url, lista)

    def test_aceitar_grava_o_perfil_na_empresa_nova(self):
        r = self.cliente.post(self.url, data={
            "csrf": self.token(), "cpv": "45000000 | 7152", "dist": ["Porto", "Marte"],
            "pbmin": "20 000"}, environ_base=self.FORA)
        self.assertEqual(r.status_code, 200)
        self.assertIn("Perfil da empresa:", r.get_data(as_text=True))
        with radar.com_empresa(2):
            cfg = radar.ler_config()
        self.assertEqual((cfg["interesse_activo"], cfg["interesse_cpv"],
                          cfg["interesse_distritos"], cfg["interesse_pbmin"]),
                         (True, "45000000|71520000", "Porto", "20 000"))
        self.assertEqual(cfg["email"]["para"], "ana@exemplo.pt")

    def test_o_formulario_tem_a_arvore_e_grava_o_que_ela_tira(self):
        """8/10/2026: sem a árvore, só se acrescentava um CPV sabendo-o de
        cor. A árvore escreve na caixa (`filtro-cpv`) e nos excluídos."""
        corpo = self.cliente.get(self.url, environ_base=self.FORA).get_data(as_text=True)
        self.assertIn("<details class='arvore'", corpo)
        self.assertIn("id='filtro-cpv'", corpo)
        self.assertIn("id='filtro-cpv-excl' name='cpv_excl'", corpo)
        self.assertIn("function arvoreCarregar", corpo)
        self.cliente.post(self.url, data={
            "csrf": self.token(), "cpv": "45000000", "cpv_excl": "45200000"},
            environ_base=self.FORA)
        with radar.com_empresa(2):
            cfg = radar.ler_config()
        self.assertEqual((cfg["interesse_cpv"], cfg["interesse_cpv_excl"]),
                         ("45000000", "45200000"))

    def test_um_cpv_estragado_volta_ao_formulario_sem_criar_nada(self):
        r = self.cliente.post(self.url, data={"csrf": self.token(), "cpv": "obras"},
                              environ_base=self.FORA)
        corpo = r.get_data(as_text=True)
        self.assertIn("não é um código CPV", corpo)
        self.assertIn("value='obras'", corpo)             # volta o que se escreveu
        self.assertEqual(radar.empresas_existentes(), [1])


class TestTriagemSemRecarregar(BaseTemporaria):
    """D1-bis da segunda ronda (26/09/2026, decisão dele): triar vinte
    anúncios eram vinte páginas inteiras, e o «Abandonar» pedia o motivo
    e mais um «Gravar». No «Por ver» o `fetch` grava pela MESMA rota --
    só a resposta vem em JSON --, e sem JS tudo continua como era. O JS
    em si viu-se no browser (painel de ensaio, 26/09/2026); aqui fica o
    que o servidor promete ao JS."""

    JSON = {"Accept": "application/json"}

    def setUp(self):
        super().setUp()
        self.enterContext(unittest.mock.patch.object(
            radar, "pedir_documentos", lambda ref: None))
        with radar.liga() as c:
            for n in (1, 2):
                c.execute("INSERT INTO anuncios (ref, titulo, entidade, data_pub,"
                          " tipo, url, estado) VALUES (?,?,?,?,?,?,'novo')",
                          ("%d/2026" % n, "Obra %d" % n, "CML", "2026-09-2%d" % n,
                           "Anúncio de procedimento", "https://dr/%d" % n))
        self.cliente = radar.app.test_client()

    def post(self, caminho, **dados):
        r = self.cliente.post(caminho, data=dados, headers=self.JSON)
        self.assertEqual(r.mimetype, "application/json", caminho)
        return r.get_json()

    def test_o_interessa_responde_em_json_com_o_desfazer(self):
        j = self.post("/estado/1%2F2026/analisar")
        self.assertTrue(j["ok"])
        self.assertIn("«Obra 1»", j["aviso"])
        self.assertEqual(j["desfazer"], "/estado/1/2026/porver?de=analisar")
        self.assertEqual(radar.propostas_de("1/2026")[0]["estado"], "analisar")
        # e o desfazer pelo mesmo caminho repõe
        self.assertTrue(self.post(j["desfazer"])["ok"])
        self.assertEqual(radar.propostas_de("1/2026"), [])

    def test_o_abandonar_sem_motivo_e_recusado_em_json(self):
        j = self.post("/estado/1%2F2026/nao_fomos")
        self.assertFalse(j["ok"])
        self.assertIn("motivo", j["aviso"])
        self.assertEqual(radar.propostas_de("1/2026"), [])
        motivo = radar.MOTIVOS_ABANDONO[0]
        j = self.post("/estado/1%2F2026/nao_fomos", motivo=motivo)
        self.assertTrue(j["ok"])
        self.assertIn(motivo, j["aviso"])
        p = radar.propostas_de("1/2026")[0]
        self.assertEqual((p["estado"], p["motivo"]), ("nao_fomos", motivo))

    def test_sem_json_e_o_post_de_sempre(self):
        r = self.cliente.post("/estado/2%2F2026/analisar",
                              headers={"Referer": "http://localhost/concursos"})
        self.assertEqual(r.status_code, 302)
        self.assertIn("aviso=", r.headers["Location"])

    def test_so_o_por_ver_liga_a_triagem_e_os_numeros_tem_onde_mexer(self):
        corpo = self.cliente.get("/concursos?estado=porver").get_data(as_text=True)
        self.assertIn("data-triagem='1'", corpo)
        self.assertIn("class='n-lista'", corpo)
        self.assertIn("mg-tab__count", corpo)
        self.assertIn("'Accept': 'application/json'", corpo)
        # o diálogo do motivo vem DEPOIS do script da lista: procurado ao
        # carregar, era null, e o «Abandonar» fazia o POST de sempre sem
        # ninguém dar por isso (visto no browser, 26/09/2026)
        self.assertGreater(corpo.index("id='dlg-motivo'"),
                           corpo.index("var linhaDoDialogo"))
        self.assertIn("f.id === 'form-motivo'", corpo)
        self.assertNotIn("var fdlg = document.getElementById", corpo)
        todos = self.cliente.get("/concursos?estado=").get_data(as_text=True)
        self.assertNotIn("data-triagem='1'", todos)

    def test_o_fetch_leva_o_csrf_como_o_post(self):
        """A guarda é a mesma: com sessão, um POST sem o token é recusado,
        venha em JSON ou não."""
        fora = {"REMOTE_ADDR": "203.0.113.7"}
        with radar.liga() as c:
            radar.contas.criar_utilizador(c, "admin", "senha-comprida")
            radar.contas.criar_utilizador(c, "ana", "senha-comprida",
                                          papel="admin", empresa_id=1)
        cliente = radar.app.test_client()
        cliente.post("/entrar", data={"email": "ana", "senha": "senha-comprida"},
                     environ_base=fora)
        r = cliente.post("/estado/1%2F2026/analisar", headers=self.JSON,
                         environ_base=fora)
        self.assertEqual(r.status_code, 403)
        corpo = cliente.get("/concursos", environ_base=fora).get_data(as_text=True)
        token = re.search(r"<meta name=\"csrf\" content=\"([0-9a-f]+)\"", corpo).group(1)
        r = cliente.post("/estado/1%2F2026/analisar",
                         headers=dict(self.JSON, **{"X-CSRF": token}),
                         environ_base=fora)
        self.assertTrue(r.get_json()["ok"])


class TestCalendarioDeTresFiltros(CicloDasTarefas):
    """D12 da segunda ronda (26/09/2026, decisão dele): o calendário tinha
    as onze abas da escada, e um calendário não pergunta «em que
    ranhura». São três filtros — «As nossas» (a omissão), «Por ver» e
    «Tudo» —, as tarefas aparecem no dia delas, e os endereços antigos
    com `?estado=` redireccionam para o filtro que diz o mesmo."""

    def _grade(self, url):
        corpo = self.cliente.get(url).get_data(as_text=True)
        return corpo, corpo.split("<div class='cal-rolo'>")[1].split(
            "<ol class='cal-agenda'")[0]

    def _tarefa(self, o_que, dia, quem=None, feita=None):
        with radar.liga() as c:
            c.execute("INSERT INTO tarefas (o_que, quando, quem, feita_em, "
                      "origem) VALUES (?,?,?,?,?)",
                      (o_que, self._dia(dia), quem,
                       self._dia(feita) if feita is not None else None, "mão"))

    def test_os_enderecos_antigos_redireccionam_para_o_filtro(self):
        for antigo, novo in (("estado=analisar", "ver=nossas"),
                             ("estado=", "ver=nossas"),
                             ("estado=interessa", "ver=nossas"),
                             ("estado=porver&semana=2", "ver=porver&semana=2"),
                             ("estado=expirou&interesse=nao",
                              "ver=tudo&interesse=nao")):
            r = self.cliente.get("/calendario?" + antigo)
            self.assertEqual(r.status_code, 301, antigo)
            self.assertTrue(r.headers["Location"].endswith("/calendario?" + novo),
                            (antigo, r.headers["Location"]))

    def test_as_onze_abas_sairam(self):
        corpo, _ = self._grade("/calendario")
        self.assertNotIn("<nav class='mg-tabs abas-escada'", corpo)
        filtros = corpo.split("<nav class='mg-tabs cal-filtros'")[1].split("</nav>")[0]
        self.assertEqual(re.findall(r">([^<>]+) <span class='mg-tab__count'>", filtros),
                         ["As nossas", "Por ver", "Tudo"])
        self.assertIn("aria-current='page' href='/calendario'>As nossas", filtros)

    def test_as_tarefas_aparecem_no_dia_delas(self):
        self._tarefa("Ligar ao júri", 3, quem="Ana")
        self._tarefa("Já feita", 4, feita=0)
        _, grade = self._grade("/calendario")
        self.assertIn("<b>Ligar ao júri</b><i>Tarefa · Ana</i>", grade)
        self.assertNotIn("Já feita", grade)
        # e não são do «Por ver», que são os concursos por decidir
        _, grade = self._grade("/calendario?ver=porver")
        self.assertNotIn("Ligar ao júri", grade)

    def test_a_proposta_nao_se_repete_debaixo_da_sua_tarefa(self):
        """A «entregar a proposta» nasce do prazo, no mesmo dia: desenhar
        também a proposta punha o mesmo concurso duas vezes na célula."""
        ref = self._anuncio(prazo=10)
        radar.criar_proposta(ref, estado="proposta")
        radar.sincronizar_tarefas()
        _, grade = self._grade("/calendario")
        self.assertIn("<b>entregar a proposta</b>", grade)
        self.assertNotIn("<b>Software de gestão</b>", grade)

    def test_os_numeros_dos_filtros_sao_o_que_cada_um_desenha(self):
        """A regra da casa: o número de cada filtro abre exactamente o
        que promete — o que ele desenha nestas seis semanas."""
        self._anuncio("1/2026", prazo=5)               # por ver
        self._anuncio("2/2026", prazo=6)
        ref = self._anuncio("3/2026", prazo=7)
        radar.criar_proposta(ref, estado="relatorio")  # nossa, sem tarefas do DR
        self._tarefa("Rever o caderno", 2)
        corpo, _ = self._grade("/calendario")
        numeros = dict(re.findall(
            r">([^<>]+) <span class='mg-tab__count'>(\d+)</span>", corpo))
        for ver, rotulo in radar.FILTROS_DO_CALENDARIO:
            _, grade = self._grade("/calendario?ver=" + ver)
            self.assertEqual(int(numeros[rotulo]), grade.count("class='cal-it"),
                             ver)
        self.assertEqual(numeros, {"As nossas": "2", "Por ver": "2", "Tudo": "4"})

    def test_no_telemovel_e_uma_agenda_so_com_os_dias_com_coisas(self):
        self._anuncio("1/2026", prazo=3)
        self._anuncio("2/2026", prazo=3)
        self._anuncio("3/2026", prazo=9)
        corpo = self.cliente.get("/calendario?ver=porver").get_data(as_text=True)
        agenda = corpo.split("<ol class='cal-agenda'")[1].split("</ol>")[0]
        self.assertEqual(agenda.count("<li class='ag-dia"), 2)
        self.assertEqual(agenda.count("class='cal-it"), 3)
        folha = TestODesenhoSegueOSistema._nosso_css()
        self.assertIn(".cal-agenda{display:none", folha)
        telemovel = folha.split("/* O CALENDÁRIO (D12")[1]
        self.assertRegex(telemovel,
                         r"@media \(max-width:600px\)\{\s*\.cal-rolo\{display:none\}")


class TestBarraDeBaixoNoTelemovel(BaseTemporaria):
    """D9 da segunda ronda (26/09/2026, decisão dele: a opção (c)). No
    telemóvel a navegação vai para baixo, fixa, ao alcance do polegar:
    quatro destinos e um «Mais», com ícone e nome, alvos de 48 px ou
    mais, e o `aria-current` no aceso. O foco não pode ficar debaixo
    dela (WCAG 2.4.11), e o iPhone tem a sua área segura."""

    def _barra(self, url):
        corpo = radar.app.test_client().get(url).get_data(as_text=True)
        return corpo.split("<nav class='barra-baixo'")[1].split("</nav>")[0]

    def test_quatro_destinos_e_um_mais(self):
        # desde 6/10/2026 o Calendário é vista das Propostas: o Mercado
        # sobe a destino, e o Calendário acende as Propostas
        barra = self._barra("/calendario")
        principais = barra.split("<details")[0]
        self.assertEqual(re.findall(r"<span>([^<]+)</span></a>", principais),
                         ["Concursos", "Propostas", "Situação", "Mercado"])
        self.assertIn("href='/propostas' aria-current='page'", principais)
        self.assertEqual(principais.count("aria-current"), 1)
        mais = barra.split("<details")[1]
        # as Configurações ligam já à Conta (3.ª ronda, G85): o
        # `/configuracoes` só redirecciona, e é uma viagem a mais
        for destino in ("/configuracoes/conta", "/ajuda"):
            self.assertIn("href='%s'" % destino, mais)
        self.assertIn("<span>Mais</span>", mais)

    def test_o_mais_acende_quando_a_pagina_vive_la(self):
        # o Mercado é destino desde 6/10/2026; no «Mais» vivem as
        # Configurações
        barra = self._barra("/configuracoes/conta")
        self.assertIn("<summary class='bb-item aceso'>", barra)
        self.assertNotIn("bb-item aceso", self._barra("/propostas"))
        self.assertNotIn("bb-item aceso", self._barra("/contratos"))

    def test_a_folha_tira_a_barra_de_cima_e_guarda_o_espaco(self):
        folha = TestODesenhoSegueOSistema._nosso_css()
        bloco = folha.split("/* A BARRA DE BAIXO")[1].split("/* O CALENDÁRIO")[0]
        self.assertIn(".barra-baixo{display:none}", bloco)
        telemovel = bloco.split("@media (max-width:600px){")[1]
        for regra in (".mg-topbar__nav{display:none}",
                      "env(safe-area-inset-bottom",
                      "body{padding-bottom:var(--baixo-h)}",
                      "scroll-padding-bottom:calc(var(--baixo-h)",
                      "min-height:48px"):
            self.assertIn(regra, telemovel)
        self.assertIn("viewport-fit=cover", radar.BASE)


class TestAspectoDeAltoContraste(BaseTemporaria):
    """D14 da segunda ronda (26/09/2026, decisão dele): o alto contraste
    escolhe-se na conta, por pessoa, e o molde carimba-o. Na conta e não
    no browser: quem precisa dele precisa em todos os aparelhos. O escuro
    não se oferece (o subtítulo fica a 1,4:1 nele)."""

    FORA = {"REMOTE_ADDR": "203.0.113.7"}

    def setUp(self):
        super().setUp()
        self.enterContext(unittest.mock.patch.object(
            radar, "ler_config",
            lambda: dict(radar.CONFIG_INICIAL, acesso_livre_local=False)))
        with radar.liga() as c:
            radar.contas.criar_utilizador(c, "ana", "senha-comprida")
            radar.contas.criar_utilizador(c, "rui", "senha-comprida",
                                          papel="tester", empresa_id=1)

    def _entra(self, quem):
        cliente = radar.app.test_client()
        cliente.post("/entrar", data={"email": quem, "senha": "senha-comprida"},
                     environ_base=self.FORA)
        return cliente

    def _pagina(self, cliente, url="/configuracoes/conta"):
        return cliente.get(url, environ_base=self.FORA).get_data(as_text=True)

    def _token(self, cliente):
        return re.search(r'<meta name="csrf" content="([0-9a-f]+)"',
                         self._pagina(cliente)).group(1)

    def test_cada_um_escolhe_o_seu_e_o_molde_carimba_o(self):
        ana, rui = self._entra("ana"), self._entra("rui")
        conta = self._pagina(ana)
        self.assertIn('data-theme="claro"', conta)
        # os quatro desde a 3.ª ronda (D1): o escuro e o «como o sistema»
        for valor in ("normal", "escuro", "sistema", "contraste"):
            self.assertIn("value='%s'" % valor, conta)
        r = ana.post("/configuracoes/conta/aspecto",
                     data={"csrf": self._token(ana), "aspecto": "contraste"},
                     environ_base=self.FORA)
        self.assertEqual(r.status_code, 302)
        for url in ("/", "/calendario", "/configuracoes/conta"):
            self.assertIn('data-theme="contraste"', self._pagina(ana, url), url)
        self.assertIn("value='contraste' checked", self._pagina(ana))
        # o do rui não mudou: é por pessoa -- e um tester também escolhe o seu
        self.assertIn('data-theme="claro"', self._pagina(rui, "/"))
        rui.post("/configuracoes/conta/aspecto",
                 data={"csrf": self._token(rui), "aspecto": "contraste"},
                 environ_base=self.FORA)
        self.assertIn('data-theme="contraste"', self._pagina(rui, "/"))

    def test_o_escuro_e_o_do_sistema(self):
        """3.ª ronda, D1 (decisão dele): o escuro oferece-se, e o «como o
        sistema» carimba `sistema`, que o guião do <head> troca pelo claro
        ou pelo escuro do computador antes de a página se pintar."""
        ana = self._entra("ana")
        for aspecto, tema in (("escuro", "escuro"), ("sistema", "sistema")):
            ana.post("/configuracoes/conta/aspecto",
                     data={"csrf": self._token(ana), "aspecto": aspecto},
                     environ_base=self.FORA)
            pagina = self._pagina(ana, "/")
            self.assertIn('data-theme="%s"' % tema, pagina)
            # o guião vem antes da folha, para não pintar claro primeiro
            self.assertLess(pagina.index("prefers-color-scheme: dark"),
                            pagina.index('rel="stylesheet"'))
        # sem sessão, o «Entrar» segue o computador
        pagina = radar.app.test_client().get(
            "/entrar", environ_base=self.FORA).get_data(as_text=True)
        self.assertIn('data-theme="sistema"', pagina)
        self.assertIn("prefers-color-scheme: dark", pagina)

    def test_um_valor_de_fora_nao_chega_ao_html(self):
        ana = self._entra("ana")
        ana.post("/configuracoes/conta/aspecto",
                 data={"csrf": self._token(ana), "aspecto": 'escuro"><script>'},
                 environ_base=self.FORA)
        self.assertIn('data-theme="claro"', self._pagina(ana, "/"))
        with self.assertRaises(ValueError):
            with radar.liga() as c:
                radar.contas.gravar_aspecto(c, 1, "roxo")


