    def test_segunda_leva_a_triagem_nao_mostra_um_periodo_que_nao_aplica(self):
        h = self.ver(self.entrar("chefe"), "/situacao?ver=triagem").get_data(as_text=True)
        self.assertIn("o período não se aplica aqui", h)
