        self.assertIn("name='versao'", h.split("action='/tarefa/%d/gravar'" % t)[1][:200])
        with radar.liga() as c:
            versao = radar.versao_da_tarefa(c.execute(
                "SELECT * FROM tarefas WHERE id=?", (t,)).fetchone())
        conta("tecnico-b", "Técnico B")
