@contextlib.contextmanager
def consultas_do_radar(ligacao="liga"):
    """Junta à lista o SQL que o radar corre no bloco, já com os valores
    (o `set_trace_callback` do sqlite3). É o que deixa um teste perguntar
    ao SQLite o PLANO de uma consulta que a página monta lá dentro."""
    feitas = []
    if ligacao == "liga":
        orig = radar._abre

        def abre(caminho):
            c = orig(caminho)
            c.set_trace_callback(feitas.append)
            return c
        with unittest.mock.patch.object(radar, "_abre", abre):
            yield feitas
    else:
        orig = radar.liga_corpus

        def liga_corpus():
            c = orig()
            c.set_trace_callback(feitas.append)
            return c
        with unittest.mock.patch.object(radar, "liga_corpus", liga_corpus):
            yield feitas


def plano(c, sql):
    return [r[3] for r in c.execute("EXPLAIN QUERY PLAN " + sql)]


class TestOResumoDoMercadoGuardaSe(BaseTemporaria):
    """3.ª ronda, G78 (29/09/2026): o `/contratos/resumo` levava 9 a 18 s
    em CADA visita ao Mercado, de cada pessoa, e era todo base de dados.
    Duas causas: as sete agregações iam, cada uma, buscar as linhas do
    recorte à tabela larga (no perfil «45, 50, 71 ou 909», centenas de
    milhares de buscas ao acaso, sete vezes), e nada se guardava -- num
    corpus que só muda com a importação de segunda-feira. Medido numa
    cópia das bases: 70 a 100 s -> 5 s na primeira visita e 0,05 s nas
    seguintes. Estes testes guardam as propriedades, não o relógio."""

    def setUp(self):
        super().setUp()
        semear_corpus()
        radar._MEMORIA_DO_CORPUS.clear()
        self.addCleanup(radar._MEMORIA_DO_CORPUS.clear)

    def _resumo(self, args=None):
        with radar.app.test_request_context("/contratos/resumo"):
            return radar.resumo_contratos(args or {})

    def test_os_numeros_sao_os_das_contas_sobre_o_corpus(self):
        """A tabela TEMP não muda nenhum número: confere-se contra as
        mesmas contas feitas directamente sobre os `contratos`."""
        ganha, compra, proc, trim, escal, desc = self._resumo()
        with radar.liga_corpus() as c:
            n, v = c.execute("SELECT COUNT(*), SUM(preco_contratual) "
                             "FROM contratos").fetchone()
            por_entidade = c.execute(
                "SELECT adjudicante_chave, SUM(preco_contratual) v FROM "
                "contratos GROUP BY 1 ORDER BY v DESC LIMIT 10").fetchall()
        self.assertEqual(sum(p["k"] for p in proc), n)
        self.assertAlmostEqual(sum(p["v"] for p in proc), v)
        self.assertEqual(sum(e["k"] for e in escal), n)
        self.assertEqual([(x["ch"], round(x["v"], 2)) for x in compra],
                         [(r[0], round(r[1], 2)) for r in por_entidade])
        self.assertAlmostEqual(ganha[0]["total"], v)
        self.assertEqual(sum(t["k"] for t in trim), n)
        self.assertTrue(desc)

    def test_a_segunda_visita_nao_vai_a_base(self):
        with unittest.mock.patch.object(
                radar, "_resumo_contratos",
                wraps=radar._resumo_contratos) as conta:
            primeira = self._resumo()
            segunda = self._resumo()
        self.assertEqual(conta.call_count, 1)
        self.assertEqual(primeira, segunda)

    def test_uma_importacao_nova_desfaz_a_memoria(self):
        antes = self._resumo()
        with radar.liga_corpus() as c:
            c.execute("INSERT INTO contratos (ano, tipo_procedimento, "
                      "data_celebracao, preco_contratual, n_adj, "
                      "adjudicante_chave) VALUES (2026, 'Ajuste directo', "
                      "'2026-01-02', 1000, 1, '500000000')")
        depois = self._resumo()
        self.assertEqual(sum(p["k"] for p in depois[2]),
                         sum(p["k"] for p in antes[2]) + 1)

    def test_tem_tecto(self):
        with unittest.mock.patch.object(radar, "TECTO_DA_MEMORIA", 3):
            for palavra in ("manutencao 1", "manutencao 2", "manutencao 3",
                            "manutencao 4", "manutencao 5"):
                self._resumo({"q": palavra})
                self.assertLessEqual(len(radar._MEMORIA_DO_CORPUS), 3)

    def test_o_corpus_e_lido_uma_vez(self):
        """As agregações correm sobre a tabela TEMP: só o `CREATE TEMP
        TABLE` lê os `contratos`."""
        with consultas_do_radar("corpus") as feitas:
            self._resumo()
        a_tabela = [q for q in feitas if re.search(r"FROM contratos c\b", q)]
        self.assertEqual(len(a_tabela), 1, a_tabela)
        self.assertIn("CREATE TEMP TABLE recorte", a_tabela[0])


class TestAPaginaDoMercadoAndaPelaOrdem(BaseTemporaria):
    """3.ª ronda, G79 (29/09/2026): as 20 linhas do Mercado com o perfil
    «45, 50, 71 ou 909» iam buscar à tabela as 400 mil do recorte, para
    as ordenar: 1,8 s a quente. Com um filtro denso, o `IN` desliga-se do
    índice e o SQLite anda pela ordem até ter vinte (0,49 s); com um raro
    fica como estava (0,000 s contra 0,19)."""

    ONDE = (" WHERE 1=1 AND (c.id IN (SELECT contrato_id FROM contrato_cpv "
            "WHERE cpv8 GLOB ?)) AND c.id NOT IN (SELECT contrato_id FROM "
            "contrato_cpv WHERE cpv8 GLOB ?)")

    def test_denso_anda_pela_ordem_raro_nao(self):
        denso = radar.onde_da_pagina(self.ONDE, radar.DENSO_PARA_A_ORDEM)
        self.assertIn("(+c.id IN (SELECT", denso)
        self.assertIn("c.id NOT IN (SELECT", denso)      # o NOT fica
        self.assertEqual(radar.onde_da_pagina(self.ONDE, 12), self.ONDE)

    def test_as_duas_formas_dao_as_mesmas_linhas_e_a_densa_usa_a_ordem(self):
        semear_corpus()
        sql = ("SELECT c.id FROM contratos c%s ORDER BY c.data_celebracao "
               "DESC, c.id DESC LIMIT 20")
        vals = ["72*", "9*"]
        with radar.liga_corpus() as c:
            raro = [r[0] for r in c.execute(sql % self.ONDE, vals)]
            denso_sql = sql % radar.onde_da_pagina(self.ONDE, 10 ** 6)
            denso = [r[0] for r in c.execute(denso_sql, vals)]
            self.assertTrue(any(
                passo.startswith("SCAN c USING") and "ix_ctr_data" in passo
                for passo in plano(c, denso_sql.replace("?", "'x'"))))
        self.assertEqual(raro, denso)
        self.assertEqual(len(raro), 20)


class TestUmaPesquisaSemResultadosNaoLeATabela(BaseTemporaria):
    """3.ª ronda, G81 (29/09/2026): «uma pesquisa sem resultados custa 1 s
    de base, mais do dobro de uma com resultados, e teve picos de 10 a
    20 s a frio». Com a ordem da lista, o SQLite andava pelo índice da
    data e conferia o filtro na tabela larga -- o `texto` de 210 mil
    anúncios -- até ter vinte; sem nenhum que batesse, lia-os todos.
    Medido numa cópia: 17-23 s -> 0,04 s."""

    def _semear(self):
        with radar.liga() as c:
            for i in range(30):
                c.execute("INSERT INTO anuncios (ref, titulo, titulo_norm, "
                          "estado, data_pub, prazo, cpv) VALUES "
                          "(?,?,?,'novo',?,?,?)",
                          ("%d/2026" % (i + 1), "Limpeza %d" % i,
                           "limpeza %d" % i if i % 10 else "vigilancia %d" % i,
                           "2026-09-%02d" % (i % 28 + 1),
                           "2026-10-%02d" % (28 - i % 28), "90910000"))

    def test_poucos_escolhem_se_pelo_indice_de_cobertura(self):
        self._semear()
        cliente = radar.app.test_client()
        with consultas_do_radar() as feitas:
            for q in ("xyzzy", "vigilancia"):
                self.assertEqual(cliente.get(radar.LISTA + "?estado=&q=" + q)
                                 .status_code, 200)
        linhas = [q for q in feitas if q.startswith("SELECT * FROM anuncios")
                  and "LIMIT" in q]
        self.assertEqual(len(linhas), 2)
        with radar.liga() as c:
            for sql in linhas:
                passos = plano(c, sql)
                self.assertIn("SCAN anuncios USING COVERING INDEX "
                              "ix_anuncios_cobre", passos, sql)
                self.assertNotIn("SCAN anuncios USING INDEX ix_anuncios_data",
                                 passos)

    def test_as_duas_formas_dao_a_mesma_pagina(self):
        self._semear()
        onde = " WHERE titulo_norm LIKE ? AND estado != 'alteracao'"
        with radar.liga() as c:
            for ordem in (radar.ordem_da_lista({}),
                          radar.ordem_da_lista({"ordem": "prazo"})):
                for pagina in (0, 20):
                    vals = ["%limpeza%", 20, pagina]
                    muitos = [r["ref"] for r in c.execute(
                        radar.consulta_da_pagina(onde, 10 ** 6, ordem), vals)]
                    poucos = [r["ref"] for r in c.execute(
                        radar.consulta_da_pagina(onde, 3, ordem), vals)]
                    self.assertEqual(muitos, poucos)
            self.assertEqual(len(muitos), 7)       # 27 limpezas, 2.ª página


class TestOCalendarioNaoVarreOsAnuncios(BaseTemporaria):
    """3.ª ronda, G80 (29/09/2026): o Calendário passou de 50 para 410 ms
    (e 4,5 s numa cópia com o perfil de CPV). O `Server-Timing` dizia
    «310 ms fora da base», mas era a base: o `execute` só conta o
    primeiro passo, e o resto do varrimento corre no `fetchall`. Pedidos
    com o título e a entidade -- que nenhum índice tem --, os anúncios
    das seis semanas obrigavam a ler a tabela larga toda."""

    def test_os_anuncios_da_janela_vem_do_indice_de_cobertura(self):
        cliente = radar.app.test_client()
        with consultas_do_radar() as feitas:
            for ver in ("tudo", "porver"):
                self.assertEqual(cliente.get("/calendario?ver=" + ver)
                                 .status_code, 200)
        janela = [q for q in feitas if "prazo BETWEEN" in q
                  and q.startswith("SELECT ref, titulo")]
        self.assertEqual(len(janela), 2 * 2)   # os dois filtros, e o número do outro
        with radar.liga() as c:
            for sql in janela:
                passos = plano(c, sql)
                # nenhum passo lê a tabela inteira: a subconsulta vai
                # por um índice, e o título só se busca pela `ref`
                self.assertNotIn("SCAN anuncios", passos, sql)
                self.assertIn("SEARCH anuncios USING INDEX "
                              "sqlite_autoindex_anuncios_1 (ref=?)", passos)


class TestAFichaDaEntidadeSemVarrer(BaseTemporaria):
    """3.ª ronda, G82 (29/09/2026): a ficha de uma entidade sem NIF levava
    2,9 a 5,6 s. O nome dela procurava-se em Python, a conferir a chave
    dos 50 mil anúncios sem NIF um a um (1,6 s); os nomes de uma entidade
    varriam as 257 mil linhas da `entidade_nomes`; e o «No nosso CPV»
    cruzava os 400 mil contratos do perfil com os dela."""

    def test_o_nome_de_uma_chave_sem_nif_acha_se_pelas_palavras(self):
        with radar.liga() as c:
            for ref, ent in (("1/2026", "Fundação Salesianos"),
                             ("2/2026", "Silva & Filhos, Lda."),
                             ("3/2026", "Salesianos de Évora")):
                c.execute("INSERT INTO anuncios (ref, entidade, entidade_norm, "
                          "estado, data_pub) VALUES (?,?,?,'novo','2026-09-01')",
                          (ref, ent, radar.simplifica(ent)))
        self.assertEqual(radar.nome_da_entidade("n:fundacao salesianos"),
                         "Fundação Salesianos")
        # o «e» da chave era um «&»: não entra no filtro, e acha-se na mesma
        self.assertEqual(radar.nome_da_entidade("n:silva e filhos lda"),
                         "Silva & Filhos, Lda.")
        # uma que não existe cai no fim, sem rebentar
        self.assertEqual(radar.nome_da_entidade("n:ninguem"), "ninguem")

    def test_contar_por_entidade_nao_le_a_tabela(self):
        """O «anúncios dela» da ficha conta pelo filtro `ent` do motor, e
        o `entidade_norm LIKE` com o `estado` ao lado lia a tabela larga:
        4,3 s numa cópia com a cache fria, 0,05 s pelo índice do nome."""
        onde, valores = radar.condicoes({"ent": "salesianos", "estado": ""})
        with radar.liga() as c:
            passos = plano(c, ("SELECT COUNT(*) FROM anuncios" + onde)
                           .replace("?", "'x'"))
        self.assertNotIn("SCAN anuncios", passos)
        self.assertIn("SCAN anuncios USING COVERING INDEX "
                      "ix_anuncios_entidade_norm", passos)

    def test_os_nomes_de_uma_entidade_tem_indice(self):
        radar.iniciar_corpus()
        with radar.liga_corpus() as c:
            self.assertIn("SEARCH entidade_nomes USING COVERING INDEX "
                          "ix_nomes_chave (chave=?)", plano(
                c, "SELECT nome_norm FROM entidade_nomes WHERE chave='1' "
                   "ORDER BY nome_norm LIMIT 40"))

    def test_o_interesse_preso_a_uma_entidade_vai_por_exists(self):
        semear_corpus()
        cfg = {"interesse_activo": True, "interesse_cpv": "72000000",
               "interesse_cpv_excl": "72100000"}
        solto, vals = radar.condicao_do_interesse_contratos({}, cfg)
        preso, vals_p = radar.condicao_do_interesse_contratos({}, cfg, presa=True)
        self.assertTrue(preso.startswith("EXISTS ("), preso)
        self.assertIn("AND NOT EXISTS (", preso)
        self.assertEqual(vals, vals_p)
        with radar.liga_corpus() as c:
            for chave in ("506000000", "506000001"):
                contas = [c.execute("SELECT COUNT(*) FROM contratos c WHERE "
                                    "c.adjudicante_chave=? AND " + f,
                                    [chave] + vals).fetchone()[0]
                          for f in (solto, preso)]
                self.assertEqual(contas[0], contas[1])
                self.assertTrue(contas[0])


class TestOVocabularioCPVNaoVoltaADescer(BaseTemporaria):
    """3.ª ronda, G83 (29/09/2026): o `/cpv.json` (149 KB) descia em cada
    visita ao Perfil, com ETag e tudo. A Cloudflare, quando comprime,
    passa a etiqueta a fraca (`W/"..."`), e o browser devolve-a assim; o
    `in` do werkzeug só aceitava as fortes, e nunca havia 304."""

    def test_a_etiqueta_fraca_tambem_da_304(self):
        cliente = radar.app.test_client()
        etiqueta = cliente.get("/cpv.json?de=anuncios").headers["ETag"]
        for enviada in (etiqueta, "W/" + etiqueta):
            r = cliente.get("/cpv.json?de=anuncios",
                            headers={"If-None-Match": enviada})
            self.assertEqual(r.status_code, 304, enviada)
            self.assertEqual(r.get_data(), b"")


class TestProcurarNaPecaNaoRedesenhaTudo(BaseTemporaria):
    """3.ª ronda, G84 (29/09/2026): procurar dentro da peça levava 2,2 a
    2,4 s até ao `load`. A procura leva 0,06 s; o que pesava era o
    `?procurar=` em TODAS as imagens -- o browser pedia outra vez ao
    servidor as páginas já vistas, desenhadas de novo a 2x sem nada para
    marcar. Só as páginas onde o termo está mudam de endereço."""

    def test_so_as_paginas_com_o_termo_levam_a_procura(self):
        try:
            import pymupdf
        except ImportError:
            self.skipTest("sem pymupdf no Python dos testes")
        caminho = os.path.join(self.pasta, "ensaio.pdf")
        doc = pymupdf.open()
        doc.new_page().insert_text((72, 72), "primeira pagina")
        doc.new_page().insert_text((72, 72), "aqui ha tecnicos")
        doc.new_page().insert_text((72, 72), "terceira pagina")
        doc.save(caminho)
        doc.close()
        with radar.app.test_request_context("/"):
            _, corpo = radar.visualizador_de_peca(
                "1/2026", "ensaio.pdf", caminho, "/documento/x", "técnicos", "/")
        self.assertIn("/2.png?procurar=t%C3%A9cnicos'", corpo)
        self.assertIn("/1.png'", corpo)
        self.assertIn("/3.png'", corpo)
        self.assertEqual(corpo.count("?procurar="), 1)
        self.assertIn("aparece em <b>1 página</b>", corpo)


class TestTerceiraRondaCoerenciaDeDesenhoETexto(_CicloDoTesteComUtilizadores):
    """Lote 8 da 3.ª ronda (29/09/2026): o que se desenhava ou se dizia de
    duas maneiras. Os documentos da proposta com a caixa numa linha e o
    nome na seguinte, a «Nova proposta» sem estilo, a barra a acender
    «Concursos» numa proposta, as faixas de aviso a chegar vazias, os
    formatos (o preço do DR no campo, a data em ISO, os CPV com a barra),
    o «tu» que sobrava, a árvore dos CPV com dois «Guardar» e um filtro
    que exigia acentos, e as datas sem ano recusadas sem se dizer."""

    @staticmethod
    def _nossa_folha():
        with open(os.path.join(os.path.dirname(radar.__file__), "estilo",
                               "miragov-radar.css"), encoding="utf-8") as f:
            return f.read()

    def test_g87_a_caixa_do_documento_fica_ao_lado_do_nome(self):
        folha = self._nossa_folha()
        self.assertRegex(folha, r"\.docs-da-proposta \.doc-pronto\{display:flex;"
                                r"flex-direction:row")
        self.assertIn(".docs-da-proposta .doc-pronto input{flex:none;width:auto", folha)

    def test_g88_a_nova_proposta_tem_os_campos_do_sistema(self):
        h = self.cliente.get("/proposta/nova").get_data(as_text=True)
        for campo in ("n-entidade", "n-titulo", "n-porque"):
            self.assertIn("<label class='mg-field__label' for='%s'>" % campo, h)
            self.assertIn("class='mg-field__input' id='%s'" % campo, h)
        self.assertIn("<div class='mg-card__body'><form method='post' "
                      "class='form-nova'>", h)

    def test_g89_uma_proposta_acende_as_propostas(self):
        r = self.cliente.post("/proposta/nova", data={"entidade": "Junta X",
                                                       "titulo": "Limpeza"})
        id_ = int(re.search(r"/proposta/(\d+)", r.headers["Location"]).group(1))
        for rota in ("/proposta/nova", "/proposta/%d" % id_):
            h = self.cliente.get(rota).get_data(as_text=True)
            self.assertRegex(h, r"<a[^>]*href='%s'[^>]*aria-current"
                             % radar.PROPOSTAS, rota)
            self.assertNotRegex(h, r"<a[^>]*href='%s'[^>]*aria-current"
                                % radar.LISTA, rota)
        # e a data de criação à portuguesa (G91)
        self.assertRegex(h, r"Criada a \d{2}/\d{2}/\d{4}")

    def test_g90_o_aviso_chega_com_o_texto(self):
        # o texto fica no aviso à vista; o que entra depois é a região só
        # para o leitor de ecrã
        self.assertNotIn("t.innerHTML = '';", radar.BASE)
        self.assertIn("vivo.className = 'so-leitor';", radar.BASE)

    def test_g91_o_preco_no_campo_e_os_cpv_por_palavras(self):
        self.assertEqual(radar.preco_do_campo("230.000,00 EUR"), "230 000,00 €")
        self.assertEqual(radar.preco_do_campo(""), "")
        # gravar sem mexer não muda nada
        self.assertEqual(radar.preco_escrito(radar.preco_do_campo("230.000,00 EUR")),
                         "230.000,00 EUR")
        self._proposta("preparar")
        h = self._ficha()
        self.assertIn("name='valor_proposta' value='118 500,00 €'", h)
        self.assertNotIn("118.500,00 EUR", h)
        with radar.liga() as c:
            c.execute("INSERT INTO cpv_dict (codigo8, descricao, simples) VALUES "
                      "('90911200', 'Serviços de limpeza de edifícios', 'limpeza')")
        texto = radar.resumo_filtro("cpv=90911200|software&dist=Braga|Porto")
        self.assertIn("90911200 Serviços de limpeza de edifícios, software", texto)
        self.assertIn("distrito Braga, Porto", texto)
        self.assertNotIn("|", texto)

    def test_g95_um_guardar_so_no_perfil(self):
        h = self.cliente.get("/configuracoes/interesse").get_data(as_text=True)
        self.assertEqual(h.count("Guardar o perfil</button>"), 1)
        self.assertIn("form='form-perfil'", h)
        self.assertNotIn("onclick='arvoreAplicar()'>Guardar", h)
        # e a árvore desenha os ramos ao abrir, e filtra sem acentos
        self.assertIn("function arvoreDesenharFilhos", radar.ARVORE_JS)
        self.assertIn("normalize('NFD')", radar.ARVORE_JS)
        self.assertNotIn("filhos[cod].forEach(function(f) { det.appendChild",
                         radar.ARVORE_JS)

    def test_g96_a_data_sem_ano_e_deste_ano(self):
        ano = datetime.date.today().year
        self.assertEqual(radar.data_do_texto("2/10"), "%d-10-02" % ano)
        self.assertEqual(radar.data_de_filtro("2/10"), "%d-10-02" % ano)
        self.assertEqual(radar.data_do_texto("31/2"), "")
        id_ = self._proposta()
        self.cliente.post("/tarefa/nova", data={
            "ref": "60/2026", "proposta_id": str(id_), "o_que": "ligar ao júri",
            "quando": "2/10"})
        with radar.liga() as c:
            self.assertEqual(c.execute("SELECT quando FROM tarefas WHERE "
                                       "o_que='ligar ao júri'").fetchone()[0],
                             "%d-10-02" % ano)
        # e o campo de uma data que não se lê marca-se
        self.assertIn("input.campo-data", radar.BASE)

    def test_g97_o_erro_de_entrar_e_uma_frase(self):
        self.assertEqual(
            radar.frase_do_aviso_de_entrar("utilizador ou palavra-passe errados"),
            # desde 1/10/2026 (J7) a ligação pede-se por e-mail, logo abaixo
            "Utilizador ou palavra-passe errados. Se se esqueceu da "
            "palavra-passe, peça uma ligação para a repor em «Esqueceu-se "
            "da palavra-passe?», mais abaixo.")
        self.assertEqual(radar.frase_do_aviso_de_entrar("Já tem ponto."), "Já tem ponto.")

    def test_g97_o_resumo_aberto_a_mao_vai_para_o_mercado(self):
        r = self.cliente.get("/contratos/resumo?q=x",
                             headers={"Sec-Fetch-Mode": "navigate"})
        self.assertEqual(r.status_code, 302)
        self.assertTrue(r.headers["Location"].endswith("/contratos?q=x"))
        # o fetch da página continua a receber o pedaço
        self.assertEqual(self.cliente.get("/contratos/resumo").status_code, 200)

    def test_g97_na_ficha_nao_se_manda_para_a_ficha(self):
        id_ = self._proposta()
        radar.criar_tarefa("ligar", "2026-10-02", proposta_id=id_, ref="60/2026")
        with radar.app.test_request_context(
                "/", headers={"Referer": "http://localhost/anuncio/60%2F2026"}):
            self.assertIn("mais abaixo", radar.recado_das_tarefas_que_ficam(id_))
        with radar.app.test_request_context(
                "/", headers={"Referer": "http://localhost/concursos"}):
            self.assertIn("na ficha", radar.recado_das_tarefas_que_ficam(id_))

    def test_g97_a_ajuda_explica_o_lote_os_papeis_e_o_dispensar(self):
        h = self.cliente.get("/ajuda").get_data(as_text=True)
        for termo in ("lote", "gestor-e-membro", "por-a-empresa-a-trabalhar"):
            self.assertIn("<dt id='%s'>" % termo, h)


class TestALeituraAssociadaAsPecas(BaseTemporaria):
    """A verificação depois da resposta (29/09/2026, 3.ª ronda): o que se
    grava é o que as peças sustentam, e o guião do ensaio confronta com
    as peças certas. O modelo nunca é chamado: o `_perguntar()` é um
    duplo."""

    def _ler(self, respostas):
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, estado, texto) VALUES "
                      "('90/2026','UTAN','novo','')")
            c.execute("INSERT INTO documentos (ref, nome, texto, texto_estado) VALUES "
                      "('90/2026','CE.pdf',?,'ok')",
                      ("Cláusula 1.ª - Objeto\nFornecimento de uma UTAN.\f"
                       "Cláusula 2.ª - Características\nCaudal máximo de insuflação "
                       "[m3/h] 1540\n",))
        vistos = []

        def perguntar(cadeia, instrucao, texto):
            vistos.append(texto)
            for chave, resposta in respostas.items():
                if '{"%s"' % chave in instrucao.replace(" ", ""):
                    return dict(resposta), "", "duplo:m"
            return None, "falhou", ""

        with unittest.mock.patch.object(radar, "cadeia_de_fornecedores",
                                        lambda: [("duplo", "u", "m", "k", {})]), \
             unittest.mock.patch.object(radar, "extrair_textos", lambda ref: None), \
             unittest.mock.patch.object(radar, "_perguntar", perguntar):
            radar.analisar_pecas("90/2026")
        return radar.analise_de("90/2026"), vistos

    def test_o_numero_inventado_grava_se_marcado_e_as_clausulas_tipo_saem(self):
        # 23853: «caudais nominais 1200 m3/h», com a tabela a dizer 1540
        linha, vistos = self._ler({"objecto": {
            "objecto": "- UTAN com caudal de 1540 m3/h (pág. 2)\\n"
                       "- caudais nominais 1200 m3/h (pág. 2)\\n"
                       "- Cumprir a legislação aplicável",
            "localizacao": "não consta"}})
        self.assertIn("[pág. 2]", vistos[0])
        objecto = linha["objecto"].split("\n")
        self.assertEqual(objecto[0], "- UTAN com caudal de 1540 m3/h (pág. 2)")
        self.assertIn("confirmar: o número 1200", objecto[1])
        self.assertEqual(len(objecto), 2)

    def test_a_resposta_em_lista_e_as_palavras_passam_pelas_guardas(self):
        # 4/10/2026: o Flash-Lite devolve listas, e a lista não passava
        # pelas guardas; a palavra inventada (21830) grava-se marcada
        linha, _ = self._ler({"objecto": {
            "objecto": ["- Caudal máximo de insuflação 1540 m3/h (pág. 16, Caderno de Encargos)",
                        "- Entrega no Ministério da Justiça"],
            "localizacao": "não consta"}})
        objecto = linha["objecto"].split("\n")
        self.assertEqual(objecto[0], "- Caudal máximo de insuflação 1540 m3/h (pág. 2)")
        self.assertIn("«Justiça»", objecto[1])

    def test_a_pagina_gravada_e_a_do_codigo(self):
        # 4.ª ronda (30/09/2026): o modelo cita a página ao lado, e o que
        # se grava é a página onde a linha está no texto que ele leu
        linha, _ = self._ler({"objecto": {
            "objecto": "- Caudal máximo de insuflação 1540 m3/h (pág. 1)",
            "localizacao": "não consta (pág. 1)"}})
        self.assertEqual(linha["objecto"], "- Caudal máximo de insuflação 1540 m3/h (pág. 2)")
        self.assertEqual(linha["localizacao"], "não consta")

    def test_o_ensaio_diz_se_a_pagina_citada_bate(self):
        # 4.ª ronda: a ferramenta com que se julga diz, por linha, se a
        # página citada é a da janela encontrada
        import importlib.util
        caminho = os.path.join(os.path.dirname(os.path.abspath(radar.__file__)),
                               ".claude", "skills", "ensaio-de-leitura", "ensaio.py")
        spec = importlib.util.spec_from_file_location("ensaio_de_leitura", caminho)
        ensaio = importlib.util.module_from_spec(spec)
        with unittest.mock.patch.object(sys, "stdout", io.TextIOWrapper(io.BytesIO())):
            spec.loader.exec_module(ensaio)
        fonte = "Cláusula 1 - Objeto\nrotina\fCláusula 2 - Local\nRua da Holanda, Lisboa\f"
        comprimida, mapa = ensaio.comprime(fonte)
        _, _, sitio = ensaio.apoio("Rua da Holanda, Lisboa", fonte, comprimida, mapa)
        self.assertEqual(ensaio.nota_da_pagina("Rua da Holanda (pág. 2)", fonte, sitio, [0]),
                         "✓ pág. 2")
        self.assertEqual(ensaio.nota_da_pagina("Rua da Holanda (pág. 3)", fonte, sitio, [0]),
                         "✗ citada pág. 3, encontrada na 2")
        self.assertEqual(ensaio.nota_da_pagina("Rua da Holanda", fonte, sitio, [0]),
                         "· sem página citada; encontrada na 2")
        # um ficheiro sem páginas (.docx) não tem página a conferir
        sem = "Rua da Holanda, Lisboa"
        c2, m2 = ensaio.comprime(sem)
        _, _, s2 = ensaio.apoio(sem, sem, c2, m2)
        self.assertEqual(ensaio.nota_da_pagina("Rua da Holanda (pág. 1)", sem, s2, [0]),
                         "✗ citada pág. 1, e o ficheiro não tem páginas")

    def test_o_ensaio_casa_as_fontes_com_paginas_e_zip(self):
        # 23389, 23728, 22036: as fontes trazem « (pág. …)» e «zip/membro»,
        # e o guião só confrontava com o ficheiro sem páginas
        import importlib.util
        with radar.liga() as c:
            for nome, texto in (("CE.pdf", "Cláusula 1 - Objeto UPS"),
                                ("Pecas.zip", "o Programa"), ("Anexo.xlsx", "cadastro")):
                c.execute("INSERT INTO documentos (ref, nome, texto, texto_estado) "
                          "VALUES ('91/2026',?,?,'ok')", (nome, texto))
        caminho = os.path.join(os.path.dirname(os.path.abspath(radar.__file__)),
                               ".claude", "skills", "ensaio-de-leitura", "ensaio.py")
        spec = importlib.util.spec_from_file_location("ensaio_de_leitura", caminho)
        ensaio = importlib.util.module_from_spec(spec)
        # o guião troca o sys.stdout ao ser importado
        with unittest.mock.patch.object(sys, "stdout", io.TextIOWrapper(io.BytesIO())):
            spec.loader.exec_module(ensaio)
        nomes, _, _ = ensaio.texto_das_pecas(
            radar, "91/2026", "CE.pdf (pág. 1–3), Pecas.zip/Programa.pdf (pág. 4), Anexo.xlsx")
        self.assertEqual(sorted(nomes), ["Anexo.xlsx", "CE.pdf", "Pecas.zip"])


# ------------------------------------------------ lote 10: «Nada lento»

class TestAMemoriaDoCorpusSobreviveAoReinicio(BaseTemporaria):
    """Lote 10 (29/09/2026): «a primeira visita ao Mercado leva 25 s (depois
    0,7 s), e às Entidades 4 s». As contas guardavam-se só em memória do
    processo, com o dia na chave: a primeira pessoa de cada empresa, em
    cada dia e depois de cada reinício -- cada release --, pagava tudo.
    Agora guardam-se também num ficheiro ao lado do corpus, e o dia só
    entra quando a pergunta o usa."""

    def setUp(self):
        super().setUp()
        semear_corpus()
        radar._MEMORIA_DO_CORPUS.clear()
        self.addCleanup(radar._MEMORIA_DO_CORPUS.clear)
        self.contas = []

    def _conta(self, pergunta=("x",), valor=None):
        def calcular():
            self.contas.append(1)
            return valor if valor is not None else {"n": 7, "l": [1, 2]}
        return radar.lembrado_do_corpus(pergunta, calcular)

    def test_um_reinicio_encontra_a_conta_feita(self):
        primeira = self._conta()
        radar._MEMORIA_DO_CORPUS.clear()          # o processo novo
        self.assertEqual(self._conta(), primeira)
        self.assertEqual(len(self.contas), 1)
        self.assertTrue(os.path.exists(radar.ficheiro_da_memoria()))

    def test_um_corpus_novo_conta_outra_vez_e_deita_fora_o_velho(self):
        self._conta()
        with radar.liga_corpus() as c:
            c.execute("INSERT INTO contratos (ano, objecto) VALUES (2026, 'x')")
        radar._MEMORIA_DO_CORPUS.clear()
        self._conta()
        self.assertEqual(len(self.contas), 2)
        with sqlite3.connect(radar.ficheiro_da_memoria()) as m:
            self.assertEqual(m.execute("SELECT COUNT(DISTINCT marca) FROM "
                                       "memoria").fetchone()[0], 1)

    def test_o_dia_so_entra_quando_a_pergunta_o_usa(self):
        with unittest.mock.patch.object(radar.time, "gmtime",
                                        return_value=time.gmtime(0)):
            self._conta(("sem dia",))
            self._conta(("date('now', '+3 months')",))
        self._conta(("sem dia",))                          # outro dia: igual
        self.assertEqual(len(self.contas), 2)
        self._conta(("date('now', '+3 months')",))         # outro dia: conta
        self.assertEqual(len(self.contas), 3)

    def test_o_valor_e_o_mesmo_venha_da_conta_ou_do_disco(self):
        """Passa sempre por JSON: um tuplo na primeira vez e uma lista na
        segunda eram duas respostas diferentes à mesma pergunta."""
        a = self._conta(("t",), valor=(1, [2, 3]))
        radar._MEMORIA_DO_CORPUS.clear()
        self.assertEqual(a, self._conta(("t",), valor=(1, [2, 3])))
        self.assertEqual(a, [1, [2, 3]])

    def test_tem_tecto_em_memoria_e_em_disco(self):
        with unittest.mock.patch.object(radar, "TECTO_DA_MEMORIA", 3), \
                unittest.mock.patch.object(radar, "TECTO_DA_MEMORIA_EM_DISCO", 4):
            for i in range(9):
                self._conta(("p", i))
                self.assertLessEqual(len(radar._MEMORIA_DO_CORPUS), 3)
        with sqlite3.connect(radar.ficheiro_da_memoria()) as m:
            self.assertEqual(m.execute("SELECT COUNT(*) FROM memoria")
                             .fetchone()[0], 4)

    def test_um_ficheiro_estragado_nao_estraga_a_pagina(self):
        with open(radar.ficheiro_da_memoria(), "w") as f:
            f.write("isto nao e uma base")
        self.assertEqual(self._conta()["n"], 7)


class TestOCorpusAqueceEmFundo(BaseTemporaria):
    """Lote 10: a vigia do corpus faz, em fundo e com o perfil de cada
    empresa, as contas que a primeira visita ao Mercado e às Entidades
    pediria -- pelas MESMAS funções das páginas, senão as chaves não
    batiam e a memória não servia a ninguém."""

    def setUp(self):
        super().setUp()
        semear_corpus()
        radar.gravar_config({"interesse_activo": True,
                             "interesse_cpv": "72000000"})
        radar._MEMORIA_DO_CORPUS.clear()
        self.addCleanup(radar._MEMORIA_DO_CORPUS.clear)

    def test_depois_de_aquecer_as_paginas_nao_contam_nada(self):
        radar.aquecer_o_corpus()
        cliente = radar.app.test_client()
        with consultas_do_radar("corpus") as feitas:
            for rota in ("/contratos", "/contratos?ver=fim", "/entidades",
                         "/entidades?ver=clientes"):
                self.assertEqual(cliente.get(rota).status_code, 200, rota)
            for rota in ("/contratos/resumo", "/contratos/resumo?ver=fim"):
                self.assertEqual(cliente.get(rota).status_code, 200, rota)
        contas = [q for q in feitas
                  if re.search(r"COUNT\(\*\) n, COALESCE\(SUM|CREATE TEMP "
                               r"TABLE recorte|SUM\(c\.preco_contratual", q)]
        self.assertEqual(contas, [])

    def test_o_mercado_sem_perfil_tambem_fica_aquecido(self):
        # Medido em produção a 29/09/2026, já com a v2.0.24: o resumo do
        # Mercado com o perfil levantado (o «ver tudo», e o que o dono vê,
        # que não tem empresa) levou 33 s na primeira visita -- o
        # aquecimento só fazia o perfil de cada empresa.
        radar.aquecer_o_corpus()
        cliente = radar.app.test_client()
        with consultas_do_radar("corpus") as feitas:
            for rota in ("/contratos?interesse=nao",
                         "/contratos?interesse=nao&ver=fim",
                         "/contratos/resumo?interesse=nao",
                         "/contratos/resumo?interesse=nao&ver=fim"):
                self.assertEqual(cliente.get(rota).status_code, 200, rota)
        contas = [q for q in feitas
                  if re.search(r"COUNT\(\*\) n, COALESCE\(SUM|CREATE TEMP "
                               r"TABLE recorte|SUM\(c\.preco_contratual", q)]
        self.assertEqual(contas, [])

    def test_sexta_ronda_cada_divisao_de_cpv_fica_aquecida(self):
        """6.ª ronda (5/10/2026, perfil 16): a primeira pesquisa por uma
        divisão larga levava segundos (o CPV 45, só desde janeiro, 5,7 s
        nos gráficos com o disco quente). Aquecidas sem o perfil, servem
        todas as empresas; o número é o de uma pesquisa feita à mão."""
        divisoes = radar.divisoes_do_corpus()
        self.assertTrue(divisoes)
        radar.aquecer_o_corpus()
        cliente = radar.app.test_client()
        with consultas_do_radar("corpus") as feitas:
            for div in divisoes:
                for rota in ("/contratos?cpv=%s000000&interesse=nao" % div,
                             "/contratos/resumo?cpv=%s000000&interesse=nao" % div):
                    self.assertEqual(cliente.get(rota).status_code, 200, rota)
        contas = [q for q in feitas
                  if re.search(r"COUNT\(\*\) n, COALESCE\(SUM|CREATE TEMP "
                               r"TABLE recorte|SUM\(c\.preco_contratual", q)]
        self.assertEqual(contas, [])

    def test_a_vigia_aquece_ao_arrancar_e_so_quando_algo_muda(self):
        aquecidas, estados = [], [("a",), ("a",), ("b",), ("b",), ("b",)]
        with unittest.mock.patch.object(radar, "estado_para_aquecer",
                                        side_effect=estados), \
                unittest.mock.patch.object(radar, "aquecer_o_corpus",
                                           lambda: aquecidas.append(1)), \
                unittest.mock.patch.object(radar, "construir_indice_de_texto",
                                           lambda: None):
            esperas = []
            radar.vigiar_o_corpus(voltas=5, esperar=esperas.append)
        # ao arrancar; e o «b» só depois de ficar igual uma volta inteira
        self.assertEqual(len(aquecidas), 2)
        self.assertEqual(len(esperas), 5)

    def test_a_vigia_nao_morre_com_um_erro(self):
        with unittest.mock.patch.object(radar, "estado_para_aquecer",
                                        side_effect=RuntimeError("disco")):
            radar.vigiar_o_corpus(voltas=2, esperar=lambda s: None)
        self.assertIn("disco", radar.le_marca("ultimo_erro_vigia_corpus", ""))

    def test_mudar_o_perfil_pede_outro_aquecimento(self):
        antes = radar.estado_para_aquecer()
        radar.gravar_config({"interesse_cpv": "50000000"})
        self.assertNotEqual(antes, radar.estado_para_aquecer())


class TestAPesquisaDoMercadoPeloIndiceDeTexto(BaseTemporaria):
    """Lote 10: a primeira pesquisa de texto no Mercado levava 8 a 34 s --
    um `LIKE '%termo%'` sobre os dois milhões de objectos. O índice FTS5
    `trigram` responde ao mesmo `LIKE`, e por isso dá as MESMAS linhas:
    confere-se aqui contra o `LIKE` da tabela, com e sem acentos, com
    termos curtos e com caracteres que se escapam."""

    TERMOS = ("manutenção", "MANUTENCAO", "limpeza", "serviços manutenção",
              "ab", "1", "50%", "x_y", "manutencao 1", "inexistente",
              '"serviços de manutenção 3"', "limpeza|manutenção 2")

    def setUp(self):
        super().setUp()
        semear_corpus()
        with radar.liga_corpus() as c:
            c.execute("INSERT INTO contratos (ano, objecto) VALUES "
                      "(2026, 'Limpeza 50% das escolas x_y')")
        radar.iniciar_corpus()                 # enche o objecto_norm
        radar._TEXTO_PRONTO.clear()
        self.addCleanup(radar._TEXTO_PRONTO.clear)

    def _ids(self, q):
        onde, valores = radar.condicoes_contratos({"q": q})
        with radar.liga_corpus() as c:
            return sorted(r[0] for r in c.execute(
                "SELECT c.id FROM contratos c" + onde, valores))

    def test_as_mesmas_linhas_com_e_sem_indice(self):
        self.assertFalse(radar.indice_de_texto_pronto())
        antes = {q: self._ids(q) for q in self.TERMOS}
        self.assertTrue(radar.construir_indice_de_texto(avisar=lambda m: None))
        self.assertTrue(radar.indice_de_texto_pronto())
        for q in self.TERMOS:
            self.assertEqual(self._ids(q), antes[q], q)
        self.assertTrue(antes["manutenção"])
        self.assertTrue(antes["50%"])

    def test_com_o_perfil_as_mesmas_linhas_e_o_cpv_por_exists(self):
        radar.gravar_config({"interesse_activo": True,
                             "interesse_cpv": "72000000"})

        def ids():
            onde, valores = radar.filtros_dos_contratos({"q": "manutenção"})
            with radar.liga_corpus() as c:
                return onde, sorted(r[0] for r in c.execute(
                    "SELECT c.id FROM contratos c" + onde, valores))
        onde_antes, antes = ids()
        radar.construir_indice_de_texto(avisar=lambda m: None)
        onde, depois = ids()
        self.assertEqual(depois, antes)
        self.assertTrue(antes)
        self.assertIn("EXISTS (SELECT 1 FROM contrato_cpv x", onde)
        self.assertNotIn("EXISTS", onde_antes)     # sem índice, como estava

    def test_vai_pelo_indice_so_quando_pode(self):
        radar.construir_indice_de_texto(avisar=lambda m: None)
        onde, valores = radar.condicoes_contratos(
            {"q": "limpeza ab|vigilância escolas|50%"})
        # «limpeza ab» e «50%» ficam no LIKE (um termo curto, um escapado);
        # «vigilância escolas» vai pelo índice, os dois termos num MATCH só
        self.assertEqual(onde.count("MATCH ?"), 1)
        self.assertEqual(onde.count("c.objecto_norm LIKE"), 3)
        self.assertIn('"vigilancia" AND "escolas"', valores)

    def test_os_gatilhos_mantem_o_indice_como_a_tabela(self):
        radar.construir_indice_de_texto(avisar=lambda m: None)
        # a importação: apaga o ano, volta a pôr (com REPLACE), e o arranque
        # enche o objecto_norm que faltar
        with radar.liga_corpus() as c:
            c.execute("DELETE FROM contratos WHERE objecto LIKE '%manutenção 1%'")
            c.execute("INSERT OR REPLACE INTO contratos (id, ano, objecto, "
                      "objecto_norm) SELECT id, ano, 'Vigilância nocturna', "
                      "'vigilancia nocturna' FROM contratos WHERE objecto "
                      "LIKE '%manutenção 2%'")
            c.execute("INSERT INTO contratos (ano, objecto) VALUES "
                      "(2026, 'Limpeza de praias')")
        radar.iniciar_corpus()
        with radar.liga_corpus() as c:
            # o próprio FTS5 confere o índice contra a tabela
            c.execute("INSERT INTO %s(%s, rank) VALUES ('integrity-check', 1)"
                      % ((radar.INDICE_DE_TEXTO,) * 2))
            for termo in ("manutencao 2", "vigilancia", "praias", "manutencao 1"):
                pelo_indice = sorted(r[0] for r in c.execute(
                    "SELECT rowid FROM %s WHERE objecto_norm LIKE ?"
                    % radar.INDICE_DE_TEXTO, ("%" + termo + "%",)))
                pela_tabela = sorted(r[0] for r in c.execute(
                    "SELECT id FROM contratos WHERE objecto_norm LIKE ?",
                    ("%" + termo + "%",)))
                self.assertEqual(pelo_indice, pela_tabela, termo)

    def test_um_corpus_reposto_sem_indice_volta_ao_like(self):
        """Visto pronto, não se pergunta outra vez -- mas só enquanto o
        ficheiro for o mesmo: um corpus refeito ou reposto de uma cópia
        sem o índice punha a pesquisa a perguntar por uma tabela que não
        existe."""
        radar.construir_indice_de_texto(avisar=lambda m: None)
        self.assertTrue(radar.indice_de_texto_pronto())
        with radar.liga_corpus() as c:
            c.execute("DELETE FROM corpus_estado WHERE chave=?",
                      (radar.MARCA_DO_INDICE_DE_TEXTO,))
        self.assertFalse(radar.indice_de_texto_pronto())
        self.assertEqual(self._ids("limpeza"), self._ids("limpeza"))

    def test_construir_duas_vezes_nao_faz_nada(self):
        self.assertTrue(radar.construir_indice_de_texto(avisar=lambda m: None))
        self.assertFalse(radar.construir_indice_de_texto(avisar=lambda m: None))


class TestAPaginaDoMercadoConfereOCPVPelaOrdem(BaseTemporaria):
    """Lote 10: com o perfil largo, o `+c.id IN (...)` do G79 continuava a
    materializar as 400 mil do recorte para mostrar vinte (0,49 s, o
    tecto da página). Pela ordem, com o CPV conferido por `EXISTS`, são
    0,003 s -- e as MESMAS linhas, em qualquer página."""

    ONDE = TestAPaginaDoMercadoAndaPelaOrdem.ONDE

    def test_as_mesmas_linhas_em_todas_as_paginas(self):
        semear_corpus(n=90)
        sql = ("SELECT c.id FROM contratos c%s ORDER BY c.data_celebracao "
               "DESC, c.id DESC LIMIT 20 OFFSET ?")
        with radar.liga_corpus() as c:
            for desvio in (0, 20, 40):
                vals = ["72*", "9*", desvio]
                antes = [r[0] for r in c.execute(sql % self.ONDE, vals)]
                novo = sql % radar.onde_da_pagina(self.ONDE, 1000, desvio, 1000)
                self.assertIn("EXISTS (SELECT 1 FROM contrato_cpv x", novo)
                self.assertIn("c.id NOT IN (SELECT", novo)   # o excluído fica
                self.assertEqual([r[0] for r in c.execute(novo, vals)], antes)

    def test_um_cpv_raro_numa_pagina_funda_fica_no_in(self):
        onde = radar.onde_da_pagina(self.ONDE, 1000, 980, 2 * 10 ** 6)
        self.assertNotIn("EXISTS", onde)
        self.assertIn("+c.id IN (SELECT", onde)

    def test_cpv_por_exists_respeita_os_parenteses(self):
        onde = (" WHERE (c.id IN (SELECT contrato_id FROM contrato_cpv WHERE "
                "(cpv8 GLOB ? OR cpv8 GLOB ?))) AND c.ano=?")
        self.assertEqual(
            radar.cpv_por_exists(onde),
            " WHERE (EXISTS (SELECT 1 FROM contrato_cpv x WHERE x.contrato_id"
            " = c.id AND ((cpv8 GLOB ? OR cpv8 GLOB ?)))) AND c.ano=?")


class TestOsAnunciosDeUmDistritoPelaRowid(BaseTemporaria):
    """Lote 10: o filtro por distrito custava 0,74 s -- três contagens, cada
    uma a conferir 200 mil `ref` (texto) contra a lista dos do distrito.
    Pela `rowid` do mesmo anúncio confere-se em metade, e são os mesmos."""

    def test_os_mesmos_anuncios(self):
        with radar.liga() as c:
            for i, d in enumerate(("|Lisboa|", "|Porto|", "|*|", "",
                                   "|Porto|Lisboa|", "|Setúbal|")):
                c.execute("INSERT INTO anuncios (ref, estado, data_pub, "
                          "distrito) VALUES (?, 'novo', '2026-09-01', ?)",
                          ("%d/2026" % i, d))
            frag, vals = radar.fragmento_local_e_valor("Lisboa", "")
            self.assertIn("+rowid IN (SELECT rowid", frag)
            pela_rowid = sorted(r[0] for r in c.execute(
                "SELECT ref FROM anuncios WHERE " + frag, vals))
            pela_ref = sorted(r[0] for r in c.execute(
                "SELECT ref FROM anuncios WHERE " + frag.replace(
                    "rowid", "ref"), vals))
        self.assertEqual(pela_rowid, pela_ref)
        self.assertEqual(pela_rowid, ["0/2026", "2/2026", "4/2026"])


