class TestOCalendarioPesadoPedeOsPedacos(BaseTemporaria):
    """Lote 10: o «Tudo» do Calendário eram 369 KB de HTML -- cada linha
    duas vezes (a grelha e a agenda do telemóvel), mais as escondidas em
    cada «+N». Numa página pesada o «+N» e a agenda pedem-se à parte; e
    entre a grelha e os pedaços estão TODAS as linhas, sem faltar uma."""

    def setUp(self):
        super().setUp()
        self.dia = datetime.date.today() + datetime.timedelta(days=2)
        with radar.liga() as c:
            for n in range(radar.LINHAS_SEM_PEDACOS + 20):
                c.execute("INSERT INTO anuncios (ref, titulo, entidade, "
                          "estado, data_pub, prazo) VALUES (?,?,?,?,?,?)",
                          ("%d/2026" % n, "Anúncio %d" % n, "Município",
                           "novo", self.dia.isoformat(), self.dia.isoformat()))
        self.cliente = radar.app.test_client()

    def test_a_pagina_nao_leva_as_escondidas_e_os_pedacos_trazem_nas(self):
        pagina = self.cliente.get("/calendario?ver=porver").get_data(as_text=True)
        self.assertIn("data-pedaco='%s'" % self.dia.isoformat(), pagina)
        self.assertIn("data-pedaco='agenda'", pagina)
        vistos = set(re.findall(r"Anúncio (\d+)<", pagina))
        self.assertEqual(len(vistos), radar.CABEM_NO_DIA)
        mais = self.cliente.get("/calendario?ver=porver&pedaco="
                                + self.dia.isoformat()).get_data(as_text=True)
        vistos |= set(re.findall(r"Anúncio (\d+)<", mais))
        self.assertEqual(len(vistos), radar.LINHAS_SEM_PEDACOS + 20)
        agenda = self.cliente.get("/calendario?ver=porver&pedaco=agenda"
                                  ).get_data(as_text=True)
        self.assertEqual(len(set(re.findall(r"Anúncio (\d+)<", agenda))),
                         radar.LINHAS_SEM_PEDACOS + 20)

    def test_um_pedaco_aberto_a_mao_volta_a_pagina(self):
        r = self.cliente.get("/calendario?ver=porver&pedaco=agenda",
                             headers={"Sec-Fetch-Mode": "navigate"})
        self.assertEqual(r.status_code, 302)
        self.assertTrue(r.headers["Location"].endswith("/calendario?ver=porver"))

    def test_uma_pagina_leve_leva_tudo_dentro(self):
        with radar.liga() as c:
            c.execute("DELETE FROM anuncios WHERE CAST(ref AS INTEGER) > 10")
        pagina = self.cliente.get("/calendario?ver=porver").get_data(as_text=True)
        self.assertNotIn("data-pedaco", pagina)
        self.assertEqual(len(set(re.findall(r"Anúncio (\d+)<", pagina))), 11)


class TestACitacaoAbreNaPagina(_CicloDoTesteComUtilizadores):
    """L1 do plano de Outubro (30/09/2026): cada linha da leitura diz
    «(pág. 14)», e isso era texto -- para confirmar, abria-se a peça e
    procurava-se a página à mão. A citação passa a ligação que abre a
    peça dentro da ficha, nessa página, com o excerto por cima.

    Duas coisas que não são óbvias e que estes testes guardam: a citação
    quase nunca diz de que peça veio (a leitura não o guarda por campo),
    e é a ficha que a escolhe pelas palavras da linha; e o anúncio do DR
    vem entre as peças, e a página 1 dele ganhava a qualquer caderno se
    não se limitasse às peças que a leitura leu."""

    LINHA = "- Fornecimento de três servidores de rack com garantia (pág. 2)"

    def _pecas(self):
        pasta = radar.pasta_do_anuncio("60/2026")
        os.makedirs(pasta, exist_ok=True)
        textos = {
            "CE.pdf": "Caderno de encargos\fCláusula 3.ª O fornecimento de três "
                      "servidores de rack, com garantia de cinco anos.",
            "PC.pdf": "Programa do procedimento\fArtigo 2.º Os documentos da proposta.",
            "Anúncio DR.pdf": "Anúncio\fServidores de rack e garantia e fornecimento",
        }
        with radar.liga() as c:
            for nome, texto in textos.items():
                with open(os.path.join(pasta, nome), "wb") as f:
                    f.write(b"%PDF-1.4 " + nome.encode())
                c.execute("INSERT INTO documentos (ref, nome, tamanho, texto) "
                          "VALUES (?,?,?,?)", ("60/2026", nome, 1024, texto))
            c.execute("INSERT INTO analise (ref, objecto, fontes, modelo, quando) "
                      "VALUES (?,?,?,?,?)",
                      ("60/2026", self.LINHA, "CE.pdf (pág. 2), PC.pdf (pág. 2)",
                       "m", "2026-09-30 10:00"))

    def test_o_excerto_acha_a_frase_sem_acentos_nem_maiusculas(self):
        pagina = ("Texto de enchimento. " * 20 + "A PRESTAÇÃO DE SERVIÇOS DE "
                  "MANUTENÇÃO inclui as deslocações. " + "Mais texto. " * 20)
        excerto, achou = radar.excerto_da_pagina(pagina, "prestacao de servicos de manutencao")
        self.assertTrue(achou)
        self.assertIn("PRESTAÇÃO DE SERVIÇOS", excerto)
        self.assertTrue(excerto.startswith("…"))

    def test_sem_a_frase_fica_o_inicio_da_pagina_e_di_lo(self):
        excerto, achou = radar.excerto_da_pagina("Cláusula 1.ª Objecto do contrato.",
                                                 "nada disto aparece aqui")
        self.assertFalse(achou)
        self.assertTrue(excerto.startswith("Cláusula 1.ª"))

    def test_a_linha_liga_a_pagina_com_a_peca_da_citacao(self):
        cita = radar.citacao_com_ligacao("60/2026")
        h = cita("Garantia de 5 anos (Caderno de Encargos, pág. 14–15)")
        self.assertIn("href='/anuncio/60/2026?pagina=14&amp;", h)
        self.assertIn("rotulo=Caderno+de+Encargos", h)
        self.assertIn("#pag-14'", h)
        self.assertTrue(h.startswith("Garantia de 5 anos <a class='citacao'"))
        # sem citação, só escapa
        self.assertEqual(cita("A <b> & B"), "A &lt;b&gt; &amp; B")

    def test_a_ficha_mostra_a_citacao_como_ligacao(self):
        self._pecas()
        h = self.cliente.get("/anuncio/60/2026").get_data(as_text=True)
        self.assertIn("<a class='citacao'", h)
        self.assertIn("pagina=2", h)

    def test_abre_a_peca_certa_na_pagina_com_o_excerto(self):
        self._pecas()
        h = self.cliente.get("/anuncio/60/2026?pagina=2&citacao=" + quote(
            "Fornecimento de três servidores de rack com garantia")).get_data(as_text=True)
        leitor = h.split("<div class='leitor'>", 1)[1]
        self.assertIn("<span class='n'>CE.pdf</span>", leitor)
        self.assertIn("<blockquote class='citacao-excerto'>", leitor)
        self.assertIn("pág. 2 de 2", leitor)
        self.assertIn("servidores de rack", leitor)

    def test_uma_pagina_que_nao_e_numero_nao_parte(self):
        self._pecas()
        for pagina in ("abc", "0", "-3", "99999999", "²", "①"):
            r = self.cliente.get("/anuncio/60/2026?pagina=%s&citacao=x" % pagina)
            self.assertEqual(r.status_code, 200)
            self.assertNotIn("citacao-excerto", r.get_data(as_text=True))

    def test_a_citacao_nao_passa_para_outra_peca(self):
        self._pecas()
        h = self.cliente.get("/anuncio/60/2026?pagina=2&citacao=servidores").get_data(as_text=True)
        outra = re.search(r"href='([^']*peca=PC\.pdf[^']*)'", h).group(1)
        self.assertNotIn("pagina=", outra)


class TestORegistoDosEnvios(_CicloDoTesteComUtilizadores):
    """L7 do plano de Outubro (30/09/2026, ele: «ficar registado nos
    alertas da plataforma que foi enviado»). A base já guardava quando
    cada anúncio saiu em cada alerta; o ecrã mostrava 25 anúncios soltos
    e não dizia se tinha saído por e-mail ou só para o AVISOS.txt -- sem
    e-mail configurado o resumo marca-se como enviado na mesma."""

    def setUp(self):
        super().setUp()
        with radar.liga() as c:
            c.execute("INSERT INTO filtros_guardados (id, nome, consulta, alerta) "
                      "VALUES (7, 'Software', 'q=software', 1)")
            for n in range(61, 65):
                c.execute("INSERT INTO anuncios (ref, titulo, entidade, data_pub, estado) "
                          "VALUES (?,?,?,?,'novo')",
                          ("%d/2026" % n, "Anúncio %d" % n, "E", "2026-09-29"))
                c.execute("INSERT INTO alertas_vistos (filtro_id, ref, visto_em) "
                          "VALUES (7, ?, '2026-09-29 08:00')", ("%d/2026" % n,))

    def _achados(self, refs):
        return [({"id": 7, "nome": "Software"}, [{"ref": r} for r in refs])]

    def _enviar_imediatos(self, resposta):
        """O envio imediato com o e-mail a responder `resposta`; o corpo
        do resumo não interessa aqui, e os anúncios falsos não o têm."""
        with unittest.mock.patch.object(radar, "alertas_por_enviar",
                                        lambda so_imediatos=False: self._achados(["61/2026"])), \
                unittest.mock.patch.object(radar, "texto_do_resumo", lambda *a: ""), \
                unittest.mock.patch.object(radar, "html_do_resumo", lambda *a: ""), \
                unittest.mock.patch.object(radar, "enviar_email", lambda *a, **k: resposta):
            radar.enviar_imediatos({})

    def test_um_resumo_com_quatro_grava_um_envio_com_quatro(self):
        radar.marcar_alertas_enviados(self._achados(
            ["61/2026", "62/2026", "63/2026", "64/2026"]), "email")
        envios = radar.envios_dos_alertas()
        self.assertEqual(len(envios), 1)
        self.assertEqual(len(envios[0]["anuncios"]), 4)
        self.assertEqual(envios[0]["canal"], "email")

    def test_dois_envios_sao_duas_linhas(self):
        with unittest.mock.patch.object(radar, "datetime") as falso:
            falso.now.return_value = datetime.datetime(2026, 9, 29, 8, 36)
            radar.marcar_alertas_enviados(self._achados(["61/2026", "62/2026"]), "email")
            falso.now.return_value = datetime.datetime(2026, 9, 30, 8, 36)
            radar.marcar_alertas_enviados(self._achados(["63/2026"]), "ficheiro")
        envios = radar.envios_dos_alertas()
        self.assertEqual([len(e["anuncios"]) for e in envios], [1, 2])
        self.assertEqual([e["canal"] for e in envios], ["ficheiro", "email"])

    def test_um_envio_falhado_nao_grava(self):
        self._enviar_imediatos((False, "senha recusada"))
        self.assertEqual(radar.envios_dos_alertas(), [])

    def test_sem_email_configurado_fica_como_ficheiro(self):
        self._enviar_imediatos((False, radar.EMAIL_POR_CONFIGURAR))
        self.assertEqual(radar.envios_dos_alertas()[0]["canal"], "ficheiro")

    def test_o_acervo_nao_e_envio(self):
        radar.marcar_alertas_enviados(self._achados(["61/2026"]), "email")
        with radar.liga() as c:
            c.execute("UPDATE alertas_vistos SET enviado_em=? WHERE ref='62/2026'",
                      (radar.ACERVO,))
        self.assertEqual(sum(len(e["anuncios"]) for e in radar.envios_dos_alertas()), 1)

    def test_as_configuracoes_e_a_ficha_dizem_o_envio(self):
        radar.marcar_alertas_enviados(self._achados(["61/2026", "62/2026"]), "email")
        h = self.cliente.get("/configuracoes/alertas").get_data(as_text=True)
        self.assertIn("<th>Enviado</th>", h)
        self.assertIn("<summary>2 anúncios</summary>", h)
        self.assertIn("por e-mail", h)
        h = self.cliente.get("/anuncio/61/2026").get_data(as_text=True)
        self.assertIn("pelo alerta «Software», por e-mail", h)
        h = self.cliente.get("/anuncio/63/2026").get_data(as_text=True)
        self.assertNotIn("pelo alerta", h)


class TestOsDoisPequenosDoPlanoDeOutubro(_CicloDoTesteComUtilizadores):
    """L7 b e c do plano de Outubro: a dica por cima da árvore do Perfil
    da empresa (que não tem palavras-chave: são as áreas CPV), e o total
    das peças no botão do ZIP -- o tamanho de cada uma já se via."""

    def test_a_dica_esta_no_perfil(self):
        h = self.cliente.get("/configuracoes/interesse").get_data(as_text=True)
        self.assertIn(radar.DICA_DO_PERFIL, h)

    def test_o_zip_diz_o_total(self):
        pasta = radar.pasta_do_anuncio("60/2026")
        os.makedirs(pasta, exist_ok=True)
        with radar.liga() as c:
            for nome, tamanho in (("CE.pdf", 1536 * 1024), ("PC.pdf", 512 * 1024)):
                with open(os.path.join(pasta, nome), "wb") as f:
                    f.write(b"%PDF-1.4")
                c.execute("INSERT INTO documentos (ref, nome, tamanho) VALUES (?,?,?)",
                          ("60/2026", nome, tamanho))
            c.execute("UPDATE anuncios SET docs_estado='ok' WHERE ref='60/2026'")
        h = self.cliente.get("/anuncio/60/2026").get_data(as_text=True)
        self.assertIn("Descarregar todas (ZIP, 2,0 MB)", h)



class TestAQuintaRondaDeTestes(BaseTemporaria):
    """4/10/2026, a 5.ª ronda (os perfeccionistas) e as decisões dele do
    mesmo dia. Cada teste é um achado que existiu."""

    def test_o_destino_depois_de_entrar_nao_sai_do_site(self):
        """O destruidor: «/\t/evil.example» passava como caminho e o
        browser, que apaga o tab, ia para //evil.example; e a quebra de
        linha no Location dava 500."""
        for mau in ("/\t/evil.example", "/\n/x", "/\r\nSet-Cookie: x", "//x", "/\\x"):
            self.assertEqual(radar.destino_seguro(mau), "/", repr(mau))
        self.assertEqual(radar.destino_seguro("/concursos?q=a b"), "/concursos?q=a b")

    def test_um_preco_absurdo_nao_se_le(self):
        self.assertIsNone(radar.preco_escrito("100000000000000000000"))
        self.assertEqual(radar.preco_escrito("118 500,00"), "118.500,00 EUR")

    def test_a_pagina_de_uma_pesquisa_escolhe_se_no_indice(self):
        """5/10/2026: «escola» por prazo lia o `texto` de cada candidato;
        agora a página escolhe-se no `ix_anuncios_cobre`, e as linhas e a
        ordem são as mesmas."""
        radar.iniciar_db()
        with radar.liga() as c:
            for i, (titulo, prazo) in enumerate((("Escola A", "2026-11-02"),
                                                 ("Escola B", "2026-10-20"),
                                                 ("Ponte", "2026-10-10"),
                                                 ("Escola C", ""))):
                c.execute("INSERT INTO anuncios (ref, titulo, titulo_norm, data_pub, "
                          "estado, prazo) VALUES (?,?,?,?,?,?)",
                          ("%d/2026" % i, titulo, titulo.lower(), "2026-09-0%d" % (i + 1),
                           "novo", prazo))
        onde, vals = radar.condicoes({"q": "escola", "estado": ""})
        ordem = radar.ordem_da_lista({"ordem": "prazo"})
        sql = radar.consulta_da_pagina(onde, 5000, ordem)
        self.assertIn("INDEXED BY ix_anuncios_cobre", sql)
        with radar.liga() as c:
            self.assertEqual([r["ref"] for r in c.execute(sql, vals + [20, 0])],
                             ["1/2026", "0/2026", "3/2026"])

    def test_o_nif_apanha_as_grafias_sem_nif_pelos_indices(self):
        """5/10/2026: o `OR` passou a `rowid IN (… UNION …)`; continua a
        apanhar os anúncios sem NIF com a mesma grafia da entidade."""
        radar.iniciar_db()
        with radar.liga() as c:
            for ref, nif, ent in (("1/2026", "506809323", "Câmara X"),
                                  ("2/2026", "", "Câmara X"),
                                  ("3/2026", "", "Outra")):
                c.execute("INSERT INTO anuncios (ref, titulo, data_pub, estado, nif, "
                          "entidade) VALUES (?,'t','2026-09-01','novo',?,?)", (ref, nif, ent))
        onde, vals = radar.condicoes({"nif": "506 809 323", "estado": ""})
        with radar.liga() as c:
            self.assertEqual(sorted(r[0] for r in c.execute(
                "SELECT ref FROM anuncios" + onde, vals)), ["1/2026", "2/2026"])

    def test_a_data_continua_conferida_sem_o_strptime(self):
        self.assertEqual(radar.data_pt("2026-08-21"), "21/08/2026")
        self.assertEqual(radar.data_pt("2026-08-21 10:00"), "21/08/2026")
        self.assertEqual(radar.data_pt("2026-02-31"), "2026-02-31")
        self.assertEqual(radar.data_pt(""), "—")

    def test_os_caracteres_do_windows_do_base_limpam_se(self):
        """«Captações de Água \\x96 Queiriga» via-se com um espaço duplo e
        ia assim para o CSV: o dump do IMPIC traz os C1 do cp1252."""
        self.assertEqual(radar._des_html("Água \x96 Queiriga"), "Água – Queiriga")
        self.assertEqual(radar.corta("a\x93b\x94", 80), "a“b”")
        self.assertEqual(radar.celula_csv("x\x85"), "x…")

    def test_os_termos_deixam_o_pagamento_para_depois(self):
        """5/10/2026 (decisão dele, depois da 6.ª ronda): os termos
        prometiam um pré-pago com corte no próprio dia, que o financeiro da
        ronda leu como incompatível com um pagamento a 30 dias, e não havia
        ainda maneira de cobrar. Até as condições se definirem, não há
        cobranças, e nenhuma empresa paga sem as ter aceitado."""
        with open(os.path.join(os.path.dirname(radar.SITE), "termos.html"),
                  encoding="utf-8") as f:
            termos = f.read()
        self.assertIn("Durante a fase beta não há cobranças.", termos)
        self.assertIn("Nenhuma empresa passa a pagar sem as ter aceitado.", termos)
        self.assertNotIn("o acesso ao serviço pára nesse dia", termos)
        self.assertNotIn("sete dias antes no plano mensal", termos)

    def test_uma_data_de_1900_ou_9999_nao_se_le(self):
        for mau in ("01/01/1900", "31/12/9999", "1900-01-01"):
            self.assertEqual(radar.data_do_texto(mau), "", mau)
        self.assertEqual(radar.data_do_texto("5/10/2026"), "2026-10-05")

    def test_a_tarefa_de_um_documento_caducado_fica_atrasada(self):
        """Um alvará caducado há um mês dava a tarefa «para hoje» e
        «0 atrasadas»."""
        self.assertEqual(radar.data_da_tarefa_do_documento("2026-08-17", "2026-10-04 09:00"),
                         "2026-08-17")

    def test_o_telefone_grava_se_num_so_formato(self):
        self.assertEqual(radar.telefone_arrumado("912345678"), "912 345 678")
        self.assertEqual(radar.telefone_arrumado("+351912345678"), "+351 912 345 678")
        self.assertEqual(radar.telefone_arrumado("(+351) 912-345-678"), "+351 912 345 678")
        self.assertEqual(radar.telefone_arrumado("+44 20  7946 0958"), "+44 20 7946 0958")

    def test_um_alerta_por_palavras_le_se_do_indice(self):
        """Criar ou ligar um alerta por palavras levava 94 a 133 s a frio:
        o `titulo_norm` vive depois do `texto` na tabela."""
        onde, _ = radar.condicoes({"q": "limpeza vidros", "estado": ""})
        self.assertIn("INDEXED BY ix_anuncios_cobre", radar._anuncios_para(onde))
        onde, _ = radar.condicoes({"q": "x", "ent": "Lisboa", "estado": ""})
        self.assertEqual(radar._anuncios_para(onde), "anuncios")
        radar.iniciar_db()
        with radar.liga() as c:
            c.execute("INSERT INTO anuncios (ref, titulo, titulo_norm, data_pub, estado) "
                      "VALUES ('1/2026', 'Limpeza de vidros', 'limpeza de vidros', "
                      "'2026-09-01', 'novo')")
        onde, vals = radar.condicoes({"q": "vidros", "estado": ""})
        with radar.liga() as c:
            self.assertEqual([r[0] for r in c.execute(
                "SELECT ref FROM " + radar._anuncios_para(onde) + onde, vals)], ["1/2026"])

    def test_a_fita_soma_o_que_a_lista_tem(self):
        """A fita ia de ontem a ontem+6 e o «mais para a frente» contava
        de hoje+7: as tarefas desses dois dias não caíam em lado nenhum."""
        hoje = radar.date(2026, 10, 4)
        tarefas = [{"feita_em": None, "quando": (hoje + radar.timedelta(days=d)).isoformat()}
                   for d in (0, 5, 6, 30)]
        with unittest.mock.patch.object(
                radar, "_dia_da_tarefa",
                lambda t: radar.datetime.strptime(t["quando"], "%Y-%m-%d").date()), \
                radar.app.test_request_context("/"):
            h = radar._fita_da_semana(hoje, hoje, tarefas, {}, "/")
        nas_celulas = sum(int(n) for n in re.findall(r"(\d+) tarefas?", h))
        depois = int(re.search(r"depois de \w+ \d+: (\d+)", h).group(1))
        self.assertEqual(nas_celulas + depois, len(tarefas))


class TestAQuartaRondaDeTestes(BaseTemporaria):
    """4/10/2026, a 4.ª ronda (oito perfis num painel de ensaio). Cada
    teste é um achado que existiu."""

    def test_o_script_do_aviso_nao_usa_uma_variavel_por_definir(self):
        """Quatro perfis: `h is not defined` em todas as páginas que voltam
        com aviso sem âncora -- o leitor de ecrã não o lia, o foco caía no
        body e o × não fechava."""
        js = fonte_do_painel()
        bloco = js.split("var t = document.querySelector('.aviso-da-vez');", 1)[1][:1500]
        self.assertLess(bloco.index("var h ="), bloco.index("h.indexOf('desfazer')"))

    def test_uma_data_iso_impossivel_nao_passa(self):
        """O destruidor: «2026-13-45» e «2026-02-31» entravam numa tarefa."""
        for mau in ("2026-13-45", "2026-02-31", "9999-99-99"):
            self.assertEqual(radar.data_do_texto(mau), "", mau)
        self.assertEqual(radar.data_do_texto("2026-02-28"), "2026-02-28")

    def test_a_resposta_sem_javascript_volta_ao_site_e_nao_ao_hoje(self):
        """O visitante sem conta lia «Voltar ao Hoje» e «dois dias úteis»,
        quando o site diz «no próprio dia útil»."""
        cliente = radar.app.test_client()
        with unittest.mock.patch.object(radar, "_avisar_do_pedido", lambda *a: None):
            ok = cliente.post("/pedir-acesso", data=TestSitePublico.BOM,
                              environ_base=TestSitePublico.FORA,
                              follow_redirects=True).get_data(as_text=True)
            mau = cliente.post("/pedir-acesso", data=dict(TestSitePublico.BOM, nome=""),
                               environ_base=TestSitePublico.FORA).get_data(as_text=True)
        self.assertNotIn("Voltar ao Hoje", ok + mau)
        self.assertIn("no próprio dia útil", ok)
        self.assertIn('href="/">Voltar ao site', ok)
        # desde a 5.ª ronda o formulário volta preenchido, ali mesmo
        self.assertIn("action='/pedir-acesso'", mau)
        self.assertIn("value='Obras Lda'", mau)
        # as áreas são caixas desde 8/10/2026: volta marcada a que veio
        self.assertIn("value='Obras públicas e construção' checked", mau)

    def test_o_resumo_do_filtro_nao_mostra_a_aba(self):
        """O dono via «porver» solto ao lado de «Escolher por CPV»."""
        self.assertEqual(radar._sem_a_aba("estado=porver"), "")
        self.assertEqual(radar._sem_a_aba("estado=porver&q=escola"), "q=escola")


class TestOPedidoLevaONifEOPlano(BaseTemporaria):
    """30/09/2026, os planos pagos: o formulário pedia o NIF e o plano.
    4/10/2026 (decisão dele): pede só o nome, a empresa, o e-mail, o
    telemóvel e a área -- o NIF e o plano obrigatórios faziam desistir
    quem só queria experimentar, com medo de ficar a pagar. O plano
    escolhe-o o dono ao aceitar. Uma página antiga, em cache, que ainda
    mande o NIF e o plano, vê-os guardados."""

    FORA = TestSitePublico.FORA
    BOM = TestSitePublico.BOM

    def setUp(self):
        super().setUp()
        self.enterContext(unittest.mock.patch.object(
            radar, "_avisar_do_pedido", lambda id_, p: None))
        self.cliente = radar.app.test_client()

    def pedir(self, **mudar):
        return self.cliente.post("/pedir-acesso", data=dict(self.BOM, **mudar),
                                 environ_base=self.FORA,
                                 headers={"Accept": "application/json"})

    def ultimo(self):
        with radar.liga() as c:
            return c.execute("SELECT nif, plano, telefone FROM pedidos_acesso "
                             "ORDER BY id DESC").fetchone()

    def test_sem_nif_nem_plano_grava_se(self):
        self.assertTrue(self.pedir().get_json()["ok"])
        self.assertEqual(tuple(self.ultimo()), ("", "", "912 345 678"))

    def test_uma_pagina_antiga_com_nif_e_plano_grava_os(self):
        self.assertTrue(self.pedir(nif=" PT 123 456 789 ", plano="duo").get_json()["ok"])
        self.assertEqual(tuple(self.ultimo())[:2], ("123456789", "duo"))

    def test_um_nif_com_algarismos_de_outra_escrita_nao_passa(self):
        self.assertEqual(radar.nif_do_pedido("١٢٣٤٥٦٧٨٩"), "")
        self.assertEqual(radar.nif_do_pedido("123456789"), "123456789")

    def test_o_telemovel_e_obrigatorio_e_confere_se(self):
        r = self.pedir(telefone="")
        self.assertEqual(r.status_code, 400)
        self.assertIn("o telemóvel", r.get_json()["erro"])
        r = self.pedir(telefone="91 abc")
        self.assertEqual(r.status_code, 400)
        self.assertIn("O telemóvel não parece válido", r.get_json()["erro"])
        self.assertIsNone(self.ultimo())
        for bom in ("+351 912 345 678", "912345678", "(+351) 21-000.00.00"):
            self.assertTrue(radar.telefone_valido(bom), bom)
        for mau in ("12345678", "1" * 16, "912 345 67x", "+-+-+-+-+-"):
            self.assertFalse(radar.telefone_valido(mau), mau)

    def test_um_plano_desconhecido_fica_sem_plano(self):
        self.pedir(plano="tudo-gratis")
        self.assertEqual(self.ultimo()["plano"], "")

    def test_o_aviso_ao_dono_diz_o_telemovel_e_a_area(self):
        enviados = []
        with unittest.mock.patch.object(
                radar, "enviar_email",
                lambda assunto, corpo, cfg=None: enviados.append(corpo) or (True, "ok")):
            TestSitePublico._avisar_original(0, dict(self.BOM))
        self.assertIn("Telemóvel: 912 345 678", enviados[0])
        self.assertIn("Área: Obras públicas e construção", enviados[0])
        self.assertNotIn("NIF", enviados[0])

    def test_o_site_pede_so_os_cinco_campos(self):
        with open(radar.SITE, encoding="utf-8") as f:
            # o «€/ano» vai preso ao número (4.ª ronda: partia no telemóvel)
            site = f.read().replace("&nbsp;€/ano", " €/ano")
        # o anual paga-se de uma vez desde 1/10/2026 (decisão dele: «pagam logo
        # a totalidade, se saírem saíram»), e não em 12 prestações
        for frase in ("39 €", "75 €", "429 €/ano", "825 €/ano", "605 €/ano",
                      "55 €/mês + IVA", "31 de dezembro de 2026",
                      'id="planos"'):
            self.assertIn(frase, site)
        for frase in ("Contas para toda a equipa", "Todas as que precisar",
                      '"name": "Vigia"', "VigIA+",
                      "Ainda não está decidido", '"price": "0"', "prestações"):
            self.assertNotIn(frase, site)
        formulario = site.split('id="form-acesso"', 1)[1].split("</form>", 1)[0]
        self.assertEqual(
            # as áreas são nove caixas com o mesmo nome (8/10/2026)
            list(dict.fromkeys(n for n in re.findall(r'name="(\w+)"', formulario)
                               if n not in ("website", "plano", "vista"))),
            ["nome", "empresa", "email", "telefone", "sector", "mensagem"])
        # os obrigatórios continuam cinco: «o que vende, e onde» é
        # opcional (LANC-F, 4/10/2026)
        self.assertNotIn("required", re.search(r"<textarea[^>]*>", formulario).group(0))

    def test_os_planos_estao_a_vista_com_a_nota_do_fundador(self):
        """5/10/2026 (decisão dele): enquanto os pagamentos não estão
        prontos, os botões de pedir saem dos cartões. O selo na diagonal
        era «muito stock»; o vidro fosco que se lhe seguiu escondia os
        preços que o «Quanto custa?» dizia em claro, e o leitor de ecrã lia
        o desfocado (6.ª ronda). Ficam à vista, com uma linha por baixo."""
        with open(radar.SITE, encoding="utf-8") as f:
            site = f.read()
        planos = site.split('id="t-planos"', 1)[1].split('<div class="em-todos"', 1)[0]
        self.assertNotIn("indisponiveis", site)
        self.assertNotIn("planos-vidro", site)
        self.assertNotIn("filter:blur", site)
        self.assertIn("Os planos pagos abrem em breve.", planos)
        # por cima dos preços (7/10/2026, ele): no telemóvel lia-se 39 € e
        # 75 € três cartões antes de saber que ainda não se paga
        self.assertLess(planos.index("abrem em breve"), planos.index("39 €"))
        self.assertIn('href="#fundador"', planos)
        self.assertIn('id="fundador"', site)
        self.assertNotIn("plano-selo", site)
        # decisão dele, no mesmo dia: o site não diz porque é que não abrem
        self.assertNotIn("métodos de pagamento", site)
        self.assertNotIn("data-plano", planos)
        self.assertIn('data-plano="fundador"', site)

    def test_os_termos_publicados_sao_os_dos_planos(self):
        pasta = os.path.dirname(radar.SITE)
        with open(os.path.join(pasta, "termos.html"), encoding="utf-8") as f:
            termos = f.read()
        with open(os.path.join(pasta, "privacidade.html"), encoding="utf-8") as f:
            privacidade = f.read()
        for frase in ("<h2>Os planos</h2>", "<h2>Os preços</h2>", "Preço de fundador",
                      "{{NOME}}", "{{MORADA}}"):
            self.assertIn(frase, termos)
        self.assertNotIn("<h2>Fase beta</h2>", termos)
        # a privacidade diz o que o formulário pede, e já não o NIF
        self.assertIn("telemóvel", privacidade)
        self.assertNotIn("NIF da empresa, e-mail", privacidade)


class TestOResumoDoMercadoNaoRebentaComNumerosFormatados(unittest.TestCase):
    """2/10/2026: o resumo do Mercado dava 500 com qualquer filtro. O #185
    passou o `k` de cada barra pelo `mil_pt()`, e dois gráficos já o
    davam formatado («4 823»): ValueError: invalid literal for int()."""

    def test_uma_barra_com_o_k_ja_formatado(self):
        h = radar.barras_v([{"t": "2025", "v": 1.0, "k": radar.mil_pt(4823)},
                            {"t": "2026", "v": 2.0, "k": 12}],
                           "Teste", fmt=radar.mil_pt_f, unidade="procedimentos")
        self.assertIn("4\u00a0823", h)
        self.assertIn("12", h)

    def test_muitas_barras_com_a_tabela_dos_numeros(self):
        linhas = [{"t": str(2000 + i), "v": float(i + 1), "k": radar.mil_pt(1000 + i)}
                  for i in range(radar.MAX_ROTULOS_BARRAS + 3)]
        self.assertIn("1\u00a0000", radar.barras_v(linhas, "Teste"))


class TestAuditoriaDe1OutubroOsPequenos(unittest.TestCase):
    """Os achados da UX-AUDITORIA-1-10 que são uma regra ou uma palavra."""

    @staticmethod
    def _ler(*caminho):
        with open(os.path.join(os.path.dirname(os.path.abspath(radar.__file__)),
                               *caminho), encoding="utf-8") as f:
            return f.read()

    def test_n6_o_topo_azul_foca_a_ambar(self):
        # o --focus magenta ficava a 2,36:1 sobre o azul do topo do site,
        # das páginas legais e do lado azul do entrar
        self.assertIn(".topo :focus-visible{outline-color:var(--seal-on-dark)}",
                      self._ler("site", "moldura.css"))
        self.assertIn(".entrar-lado :focus-visible{outline-color:var(--focus-on-header)}",
                      self._ler("estilo", "miragov-radar.css"))

    def test_n7_o_desconto_diz_que_e_de_sempre(self):
        # as outras três colunas são do perfil e dos últimos anos
        self.assertIn("Desconto quando ganha (de sempre)",
                      inspect.getsource(radar.concorrentes))

    def test_n10_as_iniciais_na_pilula_escolhida_nao_sao_transparentes(self):
        # branco a 28 % sobre o azul: ~4,3:1 para letra de 12 px
        regra = re.search(r"\.periodos a\.on \.av\{([^}]*)\}", radar.CSS_NOVO).group(1)
        self.assertNotIn("color-mix", regra)
        self.assertIn("background:var(--on-brand)", regra)
        self.assertIn("color:var(--brand)", regra)

    def test_n5_as_setas_de_ordenar_tem_24px(self):
        regra = re.search(r"\.mg-table th a\.ordenar\{([^}]*)\}",
                          self._ler("estilo", "miragov-radar.css")).group(1)
        self.assertIn("min-height:24px", regra)

    def test_n5_a_ref_de_uma_proposta_sem_anuncio_nao_e_ligacao(self):
        p = dict.fromkeys(radar.COLUNAS_DA_PROPOSTA)
        p.update(id=7, titulo="Consulta", estado="em_analise")
        linha = radar.linha_da_pipeline(p, 7, {})
        # desde 6/10/2026 não há coluna da referência: sem anúncio, a
        # linha não leva referência nenhuma, nem ligação a mais
        self.assertTrue(linha.startswith("<tr><td class='o'>"), linha[:80])
        self.assertNotIn("mg-code", linha)


class TestUXMercadoDe1Outubro(_CicloDoTesteComUtilizadores):
    """As correcções de UX do Mercado, das Entidades, da Situação, da Conta,
    do Perfil e dos gráficos que os relatórios de 30/09/2026 deixavam para
    depois de 5/10 -- e que ele mandou fazer a 1/10/2026 («Faz todos»).
    Cada método diz de que achado vem; todos falhavam com o código de
    antes."""

    FORA = {"REMOTE_ADDR": "203.0.113.7"}

    def _gestor(self):
        return TestAsCorreccoesDeUXDoLancamento._gestor(self)

    def _ver(self, rota, cliente=None):
        if cliente:
            r = cliente.get(rota, environ_base=self.FORA)
        else:
            r = self.cliente.get(rota)
        self.assertEqual(r.status_code, 200, rota)
        return r.get_data(as_text=True)

    @staticmethod
    def _folha():
        return TestAsCorreccoesDeUXDoLancamento._ficheiro("estilo",
                                                         "miragov-radar.css")

    # -- UX-7-LEIS.md ------------------------------------------------------

    def test_j2_as_tres_vistas_do_mercado_por_cima_e_nas_entidades(self):
        """J2: as abas do Mercado estavam por baixo do filtro e da contagem,
        e carregar em «Entidades» levava a uma página sem elas."""
        semear_corpus()
        mercado = self._ver("/contratos")
        self.assertLess(mercado.index("aria-label='Vistas do Mercado'"),
                        mercado.index("id='pergunta'"))
        self.assertNotIn("<div class='mercado-resumo'><nav", mercado)
        entidades = self._ver("/entidades")
        abas = entidades.split("aria-label='Vistas do Mercado'>", 1)[1]
        abas = abas.split("</nav>", 1)[0]
        self.assertIn("href='/contratos'>Por celebração</a>", abas)
        self.assertIn("href='/contratos?ver=fim'>Por fim estimado</a>", abas)
        self.assertIn("aria-current='page' href='/entidades'>Entidades</a>", abas)
        # e as cinco das Entidades continuam, por baixo
        self.assertLess(entidades.index("aria-label='Vistas do Mercado'"),
                        entidades.index("aria-label='Vistas das entidades'"))
        # A segunda barra numa linha da grelha que não é a da primeira:
        # este teste afirmava `grid-row:4`, a mesma das duas, e a barra
        # das entidades tapava a do Mercado (N2 da UX-AUDITORIA-1-10).
        folha = self._folha()
        primeira = re.search(r"\.topo>\.mg-tabs,[^{]*\{[^}]*grid-row:(\d+)", folha)
        segunda = re.search(r"\.topo>\.abas-mercado\+\.mg-tabs\{grid-row:(\d+)", folha)
        self.assertEqual(int(segunda.group(1)), int(primeira.group(1)) + 1)

    def test_m1_a_situacao_nao_desenha_as_fases_abertas_duas_vezes(self):
        """M1: «Abertas, por fase» eram as quatro primeiras barras do
        «Propostas por fase», na mesma página."""
        self._proposta()
        h = self._ver("/situacao")
        self.assertNotIn("Abertas, por", h)
        self.assertEqual(h.count("Propostas por fase</h2>"), 1)
        # o «Por submeter» e o «Em jogo» ficam no número e na lista dele
        self.assertEqual(h.count("id='em-analise'"), 1)
        self.assertEqual(h.count("id='entregues'"), 1)

    def test_m2_a_conta_em_tres_cartoes(self):
        """M2: seis assuntos num cartão só, com a empresa e a equipa
        dentro da «Conta» pessoal."""
        with radar.liga() as c:
            c.execute("INSERT INTO historico (quem, accao, detalhe, quando) "
                      "VALUES ('dono', 'suporte', 'entrou para ver', "
                      "'2026-10-01 10:00:00')")
        gestor = self._gestor()
        h = self._ver("/configuracoes/conta", gestor)
        for titulo in ("A minha conta", "A empresa e a equipa", "Registo do suporte"):
            self.assertIn("<h2 class='mg-card__title'>%s</h2>" % titulo, h)
        minha = h.split("A minha conta</h2>", 1)[1].split("A empresa e a equipa</h2>")[0]
        self.assertIn("Sessões abertas", minha)
        self.assertNotIn("A nossa empresa", minha)
        self.assertIn("a empresa e a equipa", self._ver("/configuracoes/conta", gestor)
                      .split("mg-card__meta", 1)[1][:200])

    def test_m3_os_distritos_agrupados_por_regiao_sem_mudar_o_que_se_grava(self):
        """M3: vinte caixas seguidas, sem grupo, no Perfil e no aceitar."""
        nos_grupos = [d for _, ds in radar.DISTRITOS_POR_REGIAO for d in ds]
        self.assertEqual(sorted(nos_grupos), sorted(radar.DISTRITOS))
        self.assertEqual(len(radar.DISTRITOS_POR_REGIAO), 7)
        h = self._ver("/configuracoes/interesse")
        self.assertEqual(h.count("<fieldset class='dist-regiao'>"), 7)
        # o que se grava é o de sempre: um `dist` por distrito, e o
        # «todos» não tem nome
        self.assertEqual(len(re.findall(r"name='dist' value='[^']+'", h)), 20)
        self.assertIn("<input type='checkbox' data-todos>", h)
        self.assertNotIn("name='dist' data-todos", h)

    def test_m4_as_entidades_paginam_a_vinte_e_o_numero_e_a_lista(self):
        """M4: 60 linhas de uma vez, e o «a acabar» contava as da janela
        toda por cima de uma lista cortada nas 60."""
        with radar.liga() as c:
            for i in range(25):
                c.execute("INSERT INTO entidades_seguidas (chave, nome) "
                          "VALUES (?, ?)", ("5000000%02d" % i, "Entidade %02d" % i))
        um = self._ver("/entidades?ver=seguidas")
        dois = self._ver("/entidades?ver=seguidas&pag=2")
        self.assertEqual(um.count("name='vs'"), 20)
        self.assertEqual(dois.count("name='vs'"), 5)
        self.assertIn("class='mg-pager'", um)
        self.assertIn("ver=seguidas", um.split("class='mg-pager'", 1)[1])
        self.assertEqual(radar.CABEM_NA_LISTA, radar.POR_PAGINA_LISTA)

    def test_e9_o_lote_so_aparece_quando_alguma_linha_o_tem(self):
        """E9 (e M4, nas Propostas): a coluna «Lote» toda de travessões,
        que no telemóvel ficavam sem rótulo."""
        id_ = self._proposta()
        sem = self._ver("/propostas?estado=analisar")
        self.assertNotIn("<th>Lote</th>", sem)
        cabecalho = sem.split("<thead><tr>", 1)[1].split("</tr>", 1)[0]
        linha = sem.split("<tbody>", 1)[1].split("</tr>", 1)[0]
        # "<th" e não "<th>": desde os Concursos (J4) as colunas que
        # ordenam levam atributos no cabeçalho
        self.assertEqual(cabecalho.count("<th"), linha.count("<td"))
        with radar.liga() as c:
            c.execute("UPDATE propostas SET lote=2 WHERE id=?", (id_,))
        com = self._ver("/propostas?estado=analisar")
        self.assertIn("<th>Lote</th>", com)
        self.assertIn(">L2</td>", com)

    # -- UX-ECRAS-EM-FALTA-E-ESCURO.md -------------------------------------

    def test_e11_os_numeros_e_o_nosso_lado_antes_do_filtro_recolhido(self):
        """E11: o primeiro número a 1 063 px no telemóvel, depois do
        filtro inteiro e da árvore."""
        semear_corpus()
        h = self._ver("/entidade/506000000")
        filtro = h.index("id='filtros-entidade'")
        self.assertLess(h.index("class='mg-stats"), filtro)
        self.assertLess(h.index("class='lado-nosso'"), filtro)
        self.assertIn("<details class='ent-filtrar'><summary>Filtrar os contratos", h)
        filtrada = self._ver("/entidade/506000000?q=manuten")
        self.assertIn("<details class='ent-filtrar' open>", filtrada)

    def test_e12_os_graficos_e_a_tabela_da_entidade_tem_titulos(self):
        """E12: os sete gráficos tinham por título um `div` a 500/14, e a
        tabela do fim nenhum."""
        semear_corpus()
        compra = self._ver("/entidade/506000000")
        self.assertIn("<h2 class='mg-card__title'>A quem compra", compra)
        self.assertNotIn("<div class='mg-field__label'>A quem compra", compra)
        ganha = self._ver("/entidade/510000000")
        self.assertIn("Os últimos contratos que ganhou · sempre</h2>", ganha)

    # -- UX-ICONES-DICAS-PESOS.md ------------------------------------------

    def test_13_os_valores_dos_graficos_fora_do_title(self):
        """13 (B.1 #3, #4): os valores escondidos das barras, as fatias da
        concentração e o desfecho dos quadradinhos só no `title`."""
        linhas = [{"t": "2026 T%d" % i, "v": 1000.0 * i, "k": i} for i in range(1, 9)]
        g = radar.barras_v(linhas, "Evolução")
        numeros = g.split("<details class='graf-numeros'>", 1)[1]
        self.assertIn("ver os números", numeros)
        self.assertIn("<td>2026 T3</td>", numeros)
        self.assertIn(html.escape(radar.euros_curto(3000.0)), numeros)
        ganha = [{"n": "Empresa %d" % i, "v": 100.0 - i, "total": 1000.0,
                  "quantas": 9} for i in range(6)]
        conc = radar.concentracao_html(ganha)
        self.assertIn("<td>Empresa 0</td>", conc.split("graf-numeros", 1)[1])
        fita = radar._fita_connosco(["ganho", "perdido", "ganho", "analisar"])
        self.assertIn("ganha 2", fita)
        self.assertIn("perdida 1", fita)
        self.assertIn("1 em curso", fita)

    def test_15_os_titulos_dos_graficos_e_da_situacao_sao_h2(self):
        """15 (C.2 #5): 16 cartões com um rótulo 500/14 por título, que o
        leitor de ecrã não encontrava por títulos."""
        g = radar.barras_h([{"n": "X", "v": 1.0, "k": 1}], "Quem ganha")
        self.assertIn("<h2 class='mg-card__title'>Quem ganha</h2>", g)
        h = self._ver("/situacao")
        for titulo in ("O negócio", "Propostas por fase", "Por submeter", "Em jogo"):
            self.assertRegex(h, r"<h2 class='mg-card__title'[^>]*>%s" % titulo)
        self.assertNotIn("<div class='mg-field__label' style='margin-bottom:6px'>"
                         "O negócio", h)

    def test_16_o_corpo_das_tabelas_dos_contratos_a_14(self):
        """16 (C.2 #4): o corpo a 12 px nos contratos, 14 nos Concursos."""
        regra = radar.CSS.split(".tab-contratos td{", 1)[1].split("}", 1)[0]
        self.assertIn("var(--text-sm)", regra)
        self.assertNotIn("var(--text-xs)", regra)

    def test_c2_7_o_numero_grande_nao_passa_o_titulo_no_telemovel(self):
        """C.2 #7: a 600 px o título desce a 22 e o número ficava a 28."""
        bloco = self._folha().split(
            "@media (max-width:600px){\n .mg-pagehead__title{", 1)[1].split("}}", 1)[0]
        self.assertIn(".mg-stat__value,.ficha-prazo b{font-size:var(--text-xl)", bloco)


class TestAsCorreccoesDeUXDoLancamento(_CicloDoTesteComUtilizadores):
    """As correcções de UX aprovadas a 30/09/2026 («sim a todas»), das três
    auditorias desse dia: `docs/historico/UX-7-LEIS.md`,
    `UX-ICONES-DICAS-PESOS.md` e `UX-ECRAS-EM-FALTA-E-ESCURO.md`. Cada
    método diz de que achado vem; todos falhavam com o código de antes."""

    FORA = {"REMOTE_ADDR": "203.0.113.7"}

    @staticmethod
    def _ficheiro(*caminho):
        with open(os.path.join(os.path.dirname(os.path.abspath(radar.__file__)),
                               *caminho), encoding="utf-8") as f:
            return f.read()

    def _folha(self):
        return self._ficheiro("estilo", "miragov-radar.css")

    def _gestor(self):
        with radar.liga() as c:
            if not c.execute("SELECT 1 FROM utilizadores WHERE email='dono'").fetchone():
                radar.contas.criar_utilizador(c, "dono", "senha-comprida",
                                              pela_consola=True)
            radar.contas.criar_utilizador(c, "gestora", "senha-comprida",
                                          nome="Ana Gestora", papel="admin",
                                          empresa_id=1)
        cliente = radar.app.test_client()
        r = cliente.post("/entrar", data={"email": "gestora",
                                          "senha": "senha-comprida"},
                         environ_base=self.FORA)
        self.assertEqual(r.status_code, 302)
        return cliente

    def _ver(self, cliente, rota):
        r = cliente.get(rota, environ_base=self.FORA)
        self.assertEqual(r.status_code, 200, rota)
        return r.get_data(as_text=True)

    @staticmethod
    def _marcacao(h):
        """O `<main>` sem guiões nem o diálogo do motivo (que é modal, e
        tem o seu primário)."""
        h = h.split("<main", 1)[-1]
        h = re.sub(r"(?s)<script.*?</script>", "", h)
        return re.sub(r"(?s)<dialog.*?</dialog>", "", h)

    def _sem_anuncio(self):
        with radar.liga() as c:
            c.execute("INSERT INTO propostas (estado, titulo, entidade) "
                      "VALUES ('analisar', 'Consulta prévia', 'Câmara')")
            return c.execute("SELECT MAX(id) FROM propostas").fetchone()[0]

    # -- UX-7-LEIS.md --------------------------------------------------

    def test_v1_o_abandonar_e_neutro_na_lista_e_na_ficha(self):
        """V1: vinte «Abandonar» laranja tinham o tom das etiquetas
        urgentes (era cinzento a 02/09)."""
        lista = self._marcacao(self.cliente.get(radar.LISTA).get_data(as_text=True))
        self.assertIn("class='mg-btn mg-btn--sm mg-btn--secondary' "
                      "aria-label='Abandonar: ", lista)
        self.assertNotIn("mg-btn--warning", lista)
        self.assertNotIn("mg-btn--warning", self._marcacao(self._ficha()))

    def test_f1_os_alvos_de_todos_os_dias_tem_44_no_toque(self):
        """F1 e E10: a triagem, o «Mudar», as abas, a paginação e a caixa ✓
        ficavam entre 24 e 32 px no dedo."""
        toque = self._folha().split("@media (pointer:coarse){", 1)[1].split("}}", 1)[0]
        for alvo in (".col-acc .mg-btn--sm", ".celula-ranhura .mg-btn--sm",
                     "main.mg select", ".mg-tab", ".mg-pager>a",
                     ".mg-btn--sm{min-height:44px}", ".periodos a"):
            self.assertIn(alvo, toque)
        self.assertIn("min-height:44px", toque)
        self.assertIn(".chk::before{content:'';position:absolute;inset:-11px}", toque)

    def test_v2_e8_um_so_primario_por_ecra(self):
        """V2, F2 e E8: a Conta tinha 5 botões cheios, os Alertas 4, as
        Propostas 2, o Perfil 2, a ficha com proposta 7, a entidade 4 e a
        proposta sem anúncio 3."""
        self._proposta()
        sem = self._sem_anuncio()
        gestor = self._gestor()
        for rota in ("/configuracoes/conta", "/configuracoes/alertas",
                     "/configuracoes/interesse", "/propostas?estado=analisar",
                     "/anuncio/60%2F2026", "/proposta/%d" % sem,
                     "/entidade/n:ipl"):
            h = self._marcacao(self._ver(gestor, rota))
            self.assertLessEqual(h.count("mg-btn--primary"), 1, rota)
        conta = self._marcacao(self._ver(gestor, "/configuracoes/conta"))
        self.assertIn("class='mg-btn mg-btn--primary'>Criar convite", conta)
        # H2: o segundo caminho para criar uma conta fica recolhido
        self.assertIn("<summary class='nota'>Criar sem convite", conta)

    def test_sexta_ronda_um_guardar_de_linha_nunca_e_principal(self):
        """6.ª ronda (6/10/2026, inventário dos 24 «Guardar»): o «Guardar a
        correcção» das notas era principal, e uma ficha com várias notas
        tinha vários; o da proposta esticava na grelha."""
        for funcao in (radar._mexer_na_nota, radar.mexer_na_tarefa):
            self.assertNotIn("mg-btn--primary", inspect.getsource(funcao),
                             funcao.__name__)
        self.assertIn(".prop-campos>.mg-btn{justify-self:start}", radar.CSS_TUDO)

    def test_f2_trazer_pecas_nao_e_o_botao_cheio_da_ficha_por_ver(self):
        h = self._marcacao(self._ficha())
        self.assertIn("Trazer peças", h)
        self.assertNotIn("mg-btn--primary", h)

    def test_z1_o_calendario_vazio_diz_porque_e_aponta_os_por_ver(self):
        daqui_a_3 = (datetime.date.today() + datetime.timedelta(days=3)).isoformat()
        with radar.liga() as c:
            c.execute("UPDATE anuncios SET prazo=? WHERE ref='60/2026'", (daqui_a_3,))
        h = self.cliente.get("/calendario").get_data(as_text=True)
        self.assertIn("Nenhuma proposta da empresa fecha nestas seis semanas.", h)
        self.assertIn("href='/calendario?ver=porver'>Há 1 por ver com prazo", h)

    def _verificacao_falhou(self):
        radar.marca("ultima_verificacao", "2026-09-30 20:00:00")
        radar.marca("ultima_mensagem", "o DR não aceitou a pesquisa (apiVersion)")
        radar.marca("ultima_ok", "0")

    def test_v6_b1_a_falha_da_verificacao_e_do_dono_em_palavras(self):
        """V6 e B.1 #1 (ícones): a falha era só cor e `title`, e o gestor
        de uma empresa cliente via o vermelho e a dica técnica."""
        self._verificacao_falhou()
        dono = self.cliente.get("/").get_data(as_text=True)     # acesso local
        self.assertIn("a última verificação falhou", dono)
        self.assertRegex(dono, r"class='mau'><svg[^>]*mg-icon")
        gestor = self._ver(self._gestor(), "/")
        self.assertNotIn("falhou", gestor)
        self.assertNotIn("apiVersion", gestor)
        self.assertIn("<span>desde a última verificação, ", gestor)

    def test_v4_cliente_e_concorrente_sao_neutros(self):
        self.assertNotRegex(radar.CSS, r"\.ent-papel\.(cliente|concorrente)\{")

    def test_v5_a_coluna_falta_nao_e_laranja(self):
        self.assertIn(".tab-lista td.falta{color:var(--ink);", self._folha())

    def test_v3_o_cartao_do_prazo_nao_repete_a_etiqueta(self):
        """V3, e desde 6/10/2026 (front end novo) mais: sem alterações
        o cartão do prazo não existe -- a data está por baixo do título e
        os dias na etiqueta. E a célula dos factos já não os repete."""
        daqui_a_5 = (datetime.date.today() + datetime.timedelta(days=5)).isoformat()
        with radar.liga() as c:
            c.execute("UPDATE anuncios SET prazo=? WHERE ref='60/2026'", (daqui_a_5,))
        h = self._marcacao(self._ficha())
        self.assertNotIn("id='prazo'", h)
        self.assertEqual(h.count("Faltam 5 dias"), 1)
        self.assertIn("<div class='mg-alert mg-alert--info'><div class='mg-alert__body'>"
                      "<div class='mg-alert__title'>Falta decidir.", h)

    def test_f3_h6_as_entidades_comparam_por_cima_e_sem_o_abrir(self):
        """F3: o «comparar» só existia depois da 60.ª linha. H6: o nome e o
        «abrir» davam no mesmo sítio. A.3: o cabeçalho era um «☐»."""
        self._proposta()
        h = self._marcacao(self.cliente.get("/entidades").get_data(as_text=True))
        tabela = h.split("action='/entidades'", 1)[1]
        self.assertIn("href='/entidade/n%3Aipl'", tabela)
        self.assertLess(tabela.index("Comparar as marcadas"), tabela.index("<table"))
        self.assertEqual(tabela.count("Comparar as marcadas"), 2)
        self.assertNotIn("class='nota abrir'", tabela)
        self.assertNotIn("<th>☐</th>", tabela)
        self.assertIn("<th><span class='so-leitor'>Comparar</span></th>", tabela)
        # B.1 #2 (ícones): a abreviatura explica-se por baixo
        self.assertIn(radar.LEGENDA_DO_PAPEL, tabela)

    def test_h5_o_mais_nao_repete_a_conta(self):
        h = self._ver(self._gestor(), "/")
        baixo = h.split("class='barra-baixo'", 1)[1]
        self.assertIn(">Configurações<", baixo)
        self.assertNotIn(">A conta<", baixo)

    def test_h3_o_mercado_nao_repete_a_procura_da_entidade(self):
        # sem corpus o Mercado não desenha o cartão da pergunta: lê-se o código
        self.assertNotIn("<form class='procura-entidade'", inspect.getsource(radar))

    def test_v7_as_datas_do_fim_estimado_sem_negrito(self):
        self.assertNotIn("<tr><td class='d'><b>%s</b><br>", inspect.getsource(radar))

    def test_h7_a_arvore_do_perfil_fecha_quando_ja_ha_cpv(self):
        aberta = self.cliente.get("/configuracoes/interesse").get_data(as_text=True)
        self.assertRegex(aberta, r"<details class='arvore'[^>]* open>")
        radar.gravar_config({"interesse_cpv": "72000000", "interesse_activo": True})
        fechada = self.cliente.get("/configuracoes/interesse").get_data(as_text=True)
        self.assertNotRegex(fechada, r"<details class='arvore'[^>]* open>")

    def test_j8_m5_v8_os_pedidos_de_acesso(self):
        """J8: a ligação do pedido aceite estava num `<code>`, sem
        «Copiar». M5: os pendentes misturados com os decididos. V8: um
        «aceitar…» cheio por pedido, e «activa» verde."""
        # o ecrã do aceite é o `_pedido_aceite()` desde 5/10/2026: o mesmo
        # para a empresa nova e para o «juntar»
        self.assertIn("_pedido_aceite(", inspect.getsource(radar.aceitar_pedido))
        self.assertIn("caixa_de_copiar(ligacao", inspect.getsource(radar._pedido_aceite))
        with radar.liga() as c:
            for estado in ("recusado", ""):
                c.execute("INSERT INTO pedidos_acesso (criado_em, nome, empresa, "
                          "email, sector, estado) VALUES ('2026-09-30 10:00', "
                          "'Ana', 'Obras', 'ana@exemplo.pt', 'obras', ?)", (estado,))
        h = self._marcacao(self.cliente.get("/pedidos-de-acesso").get_data(as_text=True))
        self.assertLess(h.index(">Por decidir &middot; 1<"), h.index(">Decididos &middot; 1<"))
        self.assertNotIn("mg-btn--primary", h)
        self.assertIn('{{ tom_mau if e.suspensa else "" }}',
                      radar.MOLDES_JINJA.loader.get_source(
                          radar.MOLDES_JINJA, "plataforma.html")[0])

    def test_f4_os_alvos_do_topo_do_site_no_telemovel(self):
        self.assertIn(".topo nav a.entrar,.topo nav .btn-pequeno{display:inline-flex;"
                      "align-items:center;min-height:44px",
                      self._ficheiro("site", "moldura.css"))

    # -- UX-ICONES-DICAS-PESOS.md --------------------------------------

    def test_b1_2_cliente_e_concorrente_no_glossario(self):
        termos = {t for _, grupo in radar.GLOSSARIO for t, _ in grupo}
        self.assertLessEqual({"Cliente", "Concorrente"}, termos)

    def test_c2_1_2_8_9_nenhum_peso_a_700(self):
        folha = self._folha()
        self.assertIn("main.mg :is(b,strong){font-weight:600}", folha)
        self.assertIn("main.mg h3:not([class]){font-size:var(--text-lg);font-weight:600}",
                      folha)
