class TestAFichaPeloPapel(_CicloDoTesteComUtilizadores):
    """7/10/2026, ele: «uma página de cliente vs uma página de concorrente
    tem de mostrar coisas diferentes. Eu não quero saber se o IGFEJ vende
    para a Direção dos Tribunais». No corpus de ensaio os municípios só
    compram (clientes) e as empresas só vendem (concorrentes)."""

    _ver = TestUXMercadoDe1Outubro._ver

    def test_o_cliente_nao_mostra_o_que_vende(self):
        semear_corpus()
        h = self._ver("/entidade/506000000")
        self.assertIn("A quem compra", h)
        self.assertNotIn("A quem vende", h)
        self.assertNotIn("Os últimos contratos que ganhou", h)
        self.assertIn("Compra · 24 meses", h)

    def test_o_concorrente_nao_mostra_o_que_compra(self):
        semear_corpus()
        h = self._ver("/entidade/510000001")
        self.assertIn("A quem vende", h)
        self.assertIn("Como ganha", h)
        self.assertIn("Os últimos contratos que ganhou", h)
        self.assertNotIn("A quem compra", h)
        self.assertIn("Ganha · 24 meses", h)
        self.assertIn("Desconto que dá", h)
        self.assertIn("Maior cliente", h)
        self.assertIn("os contratos dele a acabar", h)
        # um concorrente não lança concursos: sai a contagem dos anúncios
        self.assertNotIn("no Diário da República</a>", h)

    def test_contra_nos_conta_as_propostas_que_nos_ganhou(self):
        semear_corpus()
        id_ = self._proposta("perdido")
        with radar.liga() as c:
            c.execute("UPDATE propostas SET vencedor='Empresa 1, Lda' "
                      "WHERE id=?", (id_,))
        self.assertEqual(len(radar.propostas_que_nos_ganhou(
            "510000001", "Empresa 1, Lda")), 1)
        self.assertEqual(radar.propostas_que_nos_ganhou(
            "510000002", "Empresa 2, Lda"), [])
        h = self._ver("/entidade/510000001")
        self.assertIn("Contra nós <i>1</i>", h)


class TestOPortaoDaIgualdade(unittest.TestCase):
    """D1, fase 0 (9/10/2026): o HTML sai do `radar.py` para moldes, e
    a regra dele é que nada muda ao que o browser recebe. O
    `ferramentas/igual.py` mede-o; isto prova que o portão acusa o que
    deve e só normaliza o que tem razão escrita para normalizar."""

    @classmethod
    def setUpClass(cls):
        import importlib.util
        caminho = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "ferramentas", "igual.py")
        spec = importlib.util.spec_from_file_location("igual", caminho)
        cls.igual = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(cls.igual)

    def _gravacoes(self, a, b, nome="gestor/raiz"):
        pasta = tempfile.mkdtemp(prefix="igual-")
        self.addCleanup(shutil.rmtree, pasta, ignore_errors=True)
        for lado, texto in (("a", a), ("b", b)):
            if texto is None:
                os.makedirs(os.path.join(pasta, lado, "gestor"), exist_ok=True)
                continue
            ficheiro = os.path.join(pasta, lado, nome)
            os.makedirs(os.path.dirname(ficheiro), exist_ok=True)
            with open(ficheiro, "w", encoding="utf-8") as f:
                f.write(texto)
        return self.igual.comparar(os.path.join(pasta, "a"),
                                   os.path.join(pasta, "b"))

    def test_o_que_muda_de_pedido_para_pedido_nao_conta(self):
        hoje = datetime.date.today().strftime("%d/%m/%Y")
        molde = ("<input type='hidden' name='csrf' value='%s'>"
                 "<input type='hidden' name='envio' value='%s'>"
                 "<input type='hidden' name='versao' value='%s'>"
                 "<script>(function(){var V=\"%s\",vis=0})()</script>"
                 "<td>" + hoje + " %s</td>")
        self.assertEqual(self._gravacoes(
            molde % ("tok1", "ab12", "cd34", "ef56", "15:45"),
            molde % ("tok2", "9f9f", "0e0e", "7a7a", "15:46")), [])

    def test_um_espaco_a_mais_acusa_e_mostra_onde(self):
        diferencas = self._gravacoes(
            "<p>Como o Mira Gov trabalha para a empresa.</p>",
            "<p>Como o Mira Gov trabalha  para a empresa.</p>")
        self.assertEqual(len(diferencas), 1)
        _ficheiro, [(linha, _antes, depois)] = diferencas[0]
        self.assertEqual(linha, 1)
        self.assertIn("trabalha  para", depois)

    def test_a_grafia_das_aspas_nao_conta_mas_um_escape_a_mais_conta(self):
        # D1, fase 3: o `html.escape` dá `&quot;` e `&#x27;`, o Jinja `&#34;`
        # e `&#39;` -- o mesmo carácter. Um escape a mais é outro texto.
        self.assertEqual(self._gravacoes("<p>O&#x27;Neil &quot;x&quot;</p>",
                                         "<p>O&#39;Neil &#34;x&#34;</p>"), [])
        self.assertEqual(len(self._gravacoes("<p>O&#x27;Neil</p>",
                                             "<p>O&amp;#39;Neil</p>")), 1)
        self.assertEqual(len(self._gravacoes("<p>O&#x27;Neil</p>",
                                             "<p>O'Neil</p>")), 1)

    def test_uma_data_que_nao_e_de_hoje_nao_se_normaliza(self):
        # a normalização das horas é só a das de hoje: uma data fixa da
        # base que mude é uma diferença verdadeira
        self.assertEqual(len(self._gravacoes(
            "<td>01/03/2025 09:00</td>", "<td>01/03/2025 09:01</td>")), 1)

    def test_um_pedido_que_so_existe_de_um_lado_acusa(self):
        self.assertEqual(len(self._gravacoes("<p>ola</p>", None)), 1)

    def test_nenhuma_rota_com_parametros_fica_por_medir(self):
        # uma rota nova com parâmetros precisa de um exemplo no
        # `EXEMPLOS` (ou de uma lista vazia com a razão), senão o portão
        # deixava-a de fora sem ninguém saber
        _lista, sem_exemplo = self.igual.pedidos(radar, {
            "pombal": "x", "empresa": 1, "proposta": 1, "etiqueta": "x",
            "tipo": "x"})
        self.assertEqual(sem_exemplo, [])



class TestOsMoldesJinja(unittest.TestCase):
    """D1, fase 2 (9/10/2026): os moldes passaram de `%` a Jinja. O que
    o `%` garantia sem se pensar nisso tem de continuar garantido."""

    def test_um_nome_em_falta_rebenta_como_rebentava_o_por_cento(self):
        import jinja2
        with self.assertRaises(jinja2.UndefinedError):
            radar.desenhar("erro.html", {"css": "", "titulo": "t",
                                         "logo": ""})      # falta o texto

    def test_o_texto_que_nao_vem_marcado_e_escapado(self):
        molde = radar.MOLDES_JINJA.from_string("<p>{{ x }}</p>")
        self.assertEqual(molde.render(x="<b>&"), "<p>&lt;b&gt;&amp;</p>")

    def test_o_ultimo_fim_de_linha_do_molde_nao_se_perde(self):
        self.assertEqual(radar.MOLDES_JINJA.from_string("a\n").render(), "a\n")


class TestOHookReconheceOCommit(unittest.TestCase):
    """10/10/2026: o hook que trava o commit com testes a falhar não
    reconhecia `git -C pasta commit` -- as opções com o valor a seguir --,
    e esse commit gravava sem os testes correrem. Isto guarda as formas
    de escrever o commit, e as que não são commit."""

    @classmethod
    def setUpClass(cls):
        import importlib.util
        caminho = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               ".claude", "hooks", "testes_antes_do_commit.py")
        spec = importlib.util.spec_from_file_location("hook_commit", caminho)
        modulo = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(modulo)
        cls.rx = modulo.RX_COMMIT

    def test_as_formas_de_gravar_sao_reconhecidas(self):
        for comando in (
                "git commit -m 'x'",
                "git -C /home/a/radar commit -am 'x'",
                'git -C "/home/a/uma pasta" commit -m x',
                "git -c user.name=x commit -m x",
                "git --git-dir=/x/.git commit",
                "git --git-dir /x/.git --work-tree /x commit",
                "git -C /p -c a=b -q commit",
                "cd /x && git commit -m x",
                "ls; git commit",
                "/usr/bin/git commit -m x",
                "(git commit -m x)",
                "git add -A && git -C /p commit -m x"):
            self.assertTrue(self.rx.search(comando), comando)

    def test_o_que_nao_grava_passa(self):
        for comando in (
                "git log -1",
                "git -C /p log --grep commit",
                "git status",
                "echo 'git commit'",
                "grep -n commit radar.py"):
            self.assertFalse(self.rx.search(comando), comando)

if __name__ == "__main__":

    unittest.main(verbosity=2)
